import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Благовіщенню Пресвятої Богородиці","e":"Akathist to the Annunciation of the Most Holy Theotokos","secs":[{"h":"Кондак 1","ps":["Ізбра́нной в предві́чнім Сові́ті Богоотрокови́це Марі́ї, послужи́ти ве́лію та́їнству боговоплоще́нія, сія́ющей ді́вственной чистото́ю па́че ви́сшия небе́сния чистоти́, благогові́йния пі́нія принесе́м Тебі́, Богоро́дице, о всера́достном от Арха́нгела благове́щенії Твоє́м. Ти же, я́ко обра́дованная і ра́дость па́дшим лю́дем пода́ти могу́щая, ізба́ви нас от вся́ких бід і гріхо́вния печа́лі, і возведи́ нас к небе́сній ра́дости, да с Гавриї́лом вопіє́м Тебі́:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л предстоя́й Престо́лу Бо́жию ви́ну зрить непристу́пную Боже́ственную Сла́ву, єгда́ же при́йде вре́м'я ізбавле́нія челові́ков, прия́ повелі́ніє Госпо́днє: Бу́ди служи́тель стра́шному чудеси́ і та́їнству сокрове́нному: милосе́рдієм Мої́м подви́гся ко взиска́нію заблу́дшаго Ада́ма, сни́ти тщу́ся. Гряди́ у́бо во град Назаре́т, в не́мже отрокови́ця Марі́я обита́єть, да прелюбе́зную красоту́ ді́вства у́зриши. Гряди́ к сему́ одушевле́нному Бо́жию Киво́ту, ко второ́му Небесі́ на землі́ су́щему. Іди́ к Сей Оби́телі Воплоще́нія Моєго́ і возвісти́ нетлі́нноє Моє́ от Нея́ прише́ствіє. Блюди́ же, да не смути́ши і да не устраши́ши ду́шу Ді́ви, да в ра́дості бу́деть, а не в печа́лі благові́стіє твоє́. Сего́ ра́ди приступи́ к Ней кро́тко і пе́рвий глас твой ра́дость Єй да принесе́ть, і да возопіє́ши Єй си́це:","Ра́дуйся, Благода́тная, Є́юже ра́дость возсія́єть.","Ра́дуйся, Обра́дованная, Є́юже кля́тва ісче́знеть.","Ра́дуйся, Благослове́нная, Є́юже вся твар обновля́ється.","Ра́дуйся, Препросла́вленная, Є́юже весь мир спаса́ється.","Ра́дуйся, Богоізбра́нная Отрокови́це, па́дшаго Ада́ма воззва́ніє.","Ра́дуйся, Пренепоро́чная Ді́во, слез Є́виних ізбавле́ніє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 2","ps":["Ви́дів Арха́нгел Гавриї́л, я́ко Человіколю́бець Госпо́дь умилосе́рдися, ги́блемий зря род челове́ч, удиви́ся зіло́, ка́ко Бог, Єго́же небеса́ вмісти́ти не мо́гуть, в діви́честій хо́щеть вмісти́тися утро́бі, ка́ко не опали́ть ю огнь Божества́, ка́ко Бог, на Него́же Херуви́ми і Серафи́ми воззрі́ти не смі́ють, хо́щеть во о́бразі раба́ яви́тися на землі́, да с челові́ки поживе́ть. Сему́ неізрече́нному та́їнству чудя́щеся со стра́хом возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неуразумева́ємий стра́шнаго та́їнства открива́я, рече́ Влади́ка А́нгелов ко Архистрати́гу: что смуща́єшися, Гавриї́ле, о но́вости ве́щі? А́ще не опали́ огнь купину́ в пусти́ні горі́вшую і не сгора́вшую, не опали́ть вся́чеськи утро́бу Діви́чу Огнь Божества́ Моєго́, но па́че ороси́ть ю і освяти́ть благода́ть Моя́. Іді́же бо хо́щеть Бог, побіжда́ються єстества́ уста́ви. Гавриї́л же, сія́ сли́шав, ра́дости іспо́лнися Боже́ственния, і оти́де в Назаре́т, ісполня́я повелі́ніє Госпо́днє, помишля́юще в себі́, ка́ко вни́деть к Отрокови́це і ка́ко возвісти́ть Єй та́їнство чуде́сноє, во є́же не смути́ти Єя́ діви́чеський по́мисл, і рече́ к себі́: возвіщу́ у́бо Єй пе́рвіє ра́дость, і цілу́я воспою́ глас такови́й:","Ра́дуйся, Ра́досте всему́ ми́ру, Тебі́ бо Єди́ной подоба́єть ра́доватися.","Ра́дуйся, Сла́досте А́нгелов, от Тебе́ Єди́ній благоволи́ Госпо́дь воплоти́тися.","Ра́дуйся, Неув'яда́ємий Цві́те чистоти́, Ти бо небе́сноє благоуха́ніє всему́ ми́ру яви́ла єси́.","Ра́дуйся, білосні́жний кри́не ді́вства, Ти бо ра́йськоє ді́вство на землі́ насади́ла єси́.","Ра́дуйся, Сокро́вище па́че всего́ дража́йшеє, Твоєя́ бо добро́ти возжела́ Цар Небе́сний.","Ра́дуйся, У́тро всему́ ми́ру світлі́йшеє, Твої́м бо сві́том разго́ниться мрак гріхо́вний.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною укріпля́ємий слеті́ с небе́сних висо́т вели́кий Арха́нгел і в Назаре́т град при́йде, і обрі́те Святу́ю Ді́ву во вну́треннем черто́ге Своє́м не о жите́йських пеку́щуюся, но в моли́тві і чте́нії кни́жнім Пребива́ющую. Та бо разгну́в кни́гу Іса́її проро́ка, чита́ше словеса́ єго́: “Се Ді́ва во чре́ві при́йметь і роди́ть Си́на і нареку́ть і́м'я Єму́ Емману́їл”. І распаля́шеся серафи́мською любо́вію не то́чію к Іму́щему ско́ро прийти́ Христу́, но і к Діви́ці о́ной, Я́же і́мать роди́ти Того́, і размишля́ше коль неізрече́нно єсть та́їнство сіє́ і коль вели́ко єсть досто́їнство Діви́ці Тоя́, і моля́шеся, о є́же уви́діти Ю, і а́ще возмо́жно, после́днейшею Єй би́ти раби́нею Тоя́, да с ра́достію воспоє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще страх ве́лій і благогові́ніє к Богоотрокови́ці, Ю́же Бог ізбра́ би́ти Влади́чицею не́ба і землі́, вели́кий Арха́нгел прибли́жися ко вну́тренним две́рем черто́га Тоя́, і се а́біє внеза́пу предста́ Преблагослове́нній с кро́тостію вели́кою, предста́ Пренепоро́чній небе́сний Ві́стник, да ра́дость всему́ ми́ру благовісти́ть, предста́ безпло́тний Чи́стой Ді́ві, да безче́стіє же́нськоє в честь преложи́ть, і между́ Созда́телем і созда́нієм уневе́щеніє да сотвори́ть, і сві́тлим гла́сом а́біє глаго́ла Неіскусобра́чній:","Ра́дуйся, Благода́тная, лику́й ни́ні і весели́ся, я́ко Госпо́дь с Тобо́ю.","Ра́дуйся, Благослове́нная, сли́ши ни́ні і приклони́ у́хо Твоє́, я́ко возжела́ Цар добро́ти Твоєя́.","Ра́дуйся, Обра́дованная, я́ко благослове́нна Ти в жена́х.","Ра́дуйся, Препросла́вленная, я́ко ве́лія сла́ва Твоя́ на небесі́х.","Ра́дуйся, Богоізбра́нная Отрокови́це, я́ко спасе́ться Тобо́ю от пре́лести весь род челові́чеський.","Ра́дуйся, преізя́щная Діви́це, я́ко возвесели́ться о Тебі́ весь превисоча́йший собо́р А́нгельський.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 4","ps":["Бу́рю внутр іму́щи помишле́ній сумни́тельних, см'яте́ся Пресвята́я Ді́ва, таково́є небе́сноє благові́стіє усли́шавше, поми́сливше же в себі́, каково́ бу́деть цілова́ніє сіє́, рече́ ко Арха́нгелу: Є́ва, прама́тер Моя́, приє́мши ра́зум змії́н, лиши́ся пи́щі Боже́ственния і ізгна́на бисть із рая́, ті́мже і Аз бою́ся цілова́нія стра́ннаго твоєго́, стидя́щеся поползнове́нія. Сего́ ра́ди отступи́ от две́рей Мої́х, і не віща́й глаго́лов, їх же сбитія́ ніка́коже мо́жеши показа́ти, да не обольще́на бу́ду, что ум мой і ду́шу смуща́єши... Аз же в тишині́ ду́ха Моєго́ воспіва́ти бу́ду: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Арха́нгел смире́нних глаго́л Пресвяти́я Ді́ви висоту́, рече́ к Ней: Что мене́ бої́шися, Всенепоро́чная, па́че Тебе́ боя́щагося? Что мене́ благогові́єши, Влади́чице, Тебі́ че́стно благогові́ющему? Не удивля́йся стра́нному моєму́ зра́ку, не ужаса́йся, Арха́нгел бо єсьм. Змій прельсти́ Є́ву іногда́, аз же Бо́жий предста́тель по́слан єсьм Боже́ственний Сові́т Предві́чний пові́дати Тебі́. Не бо́йся, Марія́м, обріла́ бо єси́ благода́ть у Бо́га безмі́рний ра́ди ді́вственния чистоти́ Твоєя́. Сего́ ра́ди зачне́ши во чре́ві і роди́ши Си́на і нарече́ши І́м'я Єму́ Ісу́с. Сей бу́деть Ве́лій і Син Ви́шняго нарече́ться. І дасть Єму́ Госпо́дь Бог престо́л Дави́да отця́ Єго́ і воцари́ться в до́му Іа́ковли во ві́ки і Ца́рствію Єго́ не бу́деть конця́. Благовіству́юще же сіє́ ве́ліє благоче́стія та́їнство, со стра́хом вопію́ Тебі́ сицева́я:","Ра́дуйся, звіздо́ незаходи́мая, вводя́щая в мир Вели́коє Со́лнце Христа́.","Ра́дуйся, заре́ присносія́ющая, явля́ющая челові́ком всего́ ми́ра Творця́.","Ра́дуйся, па́че у́тра світлі́йшая, всем во тьмі гріха́ сидя́щим світ благода́ті облиста́ющая.","Ра́дуйся, па́че зла́та дража́йшая, всім неві́дущим Бо́га сокро́вище ві́ри показу́ющая.","Ра́дуйся, Лі́ствице Небе́сная, Є́юже Бог нисхо́дить с небе́с.","Ра́дуйся, мо́сте к небесе́м приводя́й, І́мже мир ісполня́ється чуде́с.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 5","ps":["Богодухнове́нния глаго́ли Арха́нгелови сли́шавше, Пресвята́я Ді́ва смути́ся па́че би́вшаго, зане́ ті́ї Рождество́ Єй возвіща́ху. Сего́ ра́ди рече́ ко Архистрати́гу: Глаго́ли Мні я́вственнійше, ка́ко зачну́, Ді́ва су́щи отрокови́ця бра́ку неприча́стная. Ка́ко бу́деть сіє́, іді́же му́жа не зна́ю? Ка́ко у́бо глаго́леши, я́ко рожду́, бою́ся єда́ лесть глаго́леши? Сія́ рече́ не неві́рія ра́ди, но я́ко не ві́ді, ка́ко мо́жеть роди́ти, єстества́ зако́ни превосше́дши. Сего́ ра́ди рече́ ко А́нгелу: скажи́ Мі о́браз рожде́нія, во є́же не повреди́тися ді́вству Моєму́, і тогда́ обря́щеши се́рдце Моє́ к Бо́жию ізволе́нію гото́воє, да с ра́достію воспою́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів Арха́нгел вели́чіє ві́ри Пречи́стия, рече́ к Ней: Глаго́ли, я́же мні віща́єши, оби́чая єсть рождества́ челові́ков сме́ртних, зако́нам же єстества́ не рабо́таєть Ісу́с, Соді́тель єстества́, Отрокови́це. Ти і́щеши уви́діти от мене́ о́браз зача́тія Твоєго́, но той несказа́нен єсть: Дух Святи́й на́йдеть на Тя і Си́ла Ви́шняго осіни́ть Тя, ті́мже і ражда́ємоє Свя́то нарече́ться Син Бо́жий. От Того́ во чре́ві приї́меши і Той соверши́ть в Тебі́ недові́домоє зача́тіє, о Пресвята́я Ді́во. Сего́ ра́ди прославля́ю Тя си́це:","Ра́дуйся, Ду́ха Пресвята́го Неві́сто Богоізбра́нная і преднарече́нная.","Ра́дуйся, Бо́га Отця́ Дщер прелюби́мая і превожделе́нная.","Ра́дуйся, сви́тче Боже́ственний, в не́мже пе́рстом О́тчим напису́ється в Тебі́ Бо́жиє Сло́во.","Ра́дуйся, злати́й світи́льниче, І́мже Огнь Божества́ возсія́єть всему́ ми́ру.","Ра́дуйся, глубино́ неісчерпа́ємая, неудобозри́мая і А́нгельськима очи́ма.","Ра́дуйся, висото́ неізглаго́ланная, неудобовосходи́мая челові́чеськими по́мисли.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 6","ps":["Пропові́дника Боже́ственнаго і Ві́стника небе́снаго тя ві́рую би́ти, рече́ Пресвята́я Ді́ва ко А́нгелу: ви́жду бо тя а́нгельською облиста́єма сві́тлостію, оба́че стижду́ся ско́ро ві́ровати словесе́м Твої́м, не уві́дівше пе́рвіє со вся́кою ізве́стностью. Сли́шах бо Свяще́нную ні́кую Ді́ву Емману́їла ражда́ющую, проро́ком дре́вле предрече́нную. Сего́ ра́ди хощу́ разумі́ти, ка́ко єстество́ челові́чеськоє прете́рпить Божества́ растворе́ніє, да позна́ю та́їнства си́лу і с ві́рою воспою́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіява́єть ни́ні, Пречи́стая, Тобо́ю всему́ ми́ру ве́ліє Та́їнство воплоще́нія Бо́жия, — рече́ Арха́нгел к Богоро́диці, — Ти бо єси́ О́ная Свята́я Ді́ва, о Не́йже предрече́ Іса́їя. Ти єси́ Двер Божества́, чистото́ю запечатле́нная і ді́вством храни́мая, Ю́же Ієзекі́їль предви́ді. Госпо́дь про́йдеть Тобо́ю, я́коже со́лнечная луча́ стекло́ іли́ криста́лл прохо́дить, просвіща́ющи і освяща́ющи Тя Боже́ственною Сла́вою, во є́же би́ти Тебі́ і́стинною Ма́терію Бо́жієй, ражда́ющей Соверше́ннаго Бо́га і Соверше́ннаго челові́ка, і Ді́вою Нетлі́нною, я́коже пре́жде Рождества́, та́кожде в Рождестві́ і по Рождестві́ Твоє́м, роди́ши бо Си́на, Соблюда́юща Твоє́ ді́вство неврежде́нно. Сего́ ра́ди, прославля́юще вели́чіє та́йни Твоєя́, вопію́ Тебі́ си́це:","Ра́дуйся, Купино́ Неопали́мая, Ю́же не опали́ть огнь Божества́, Моїсе́єм Предзри́мая.","Ра́дуйся, две́ре затворе́нная, Є́юже про́йдеть Бог, Ієзекі́їлем предрече́нная.","Ра́дуйся, Ски́ніє преди́вная, Я́же Невмісти́маго Бо́га не ті́сно вмісти́ть, Авраа́мом прообразова́нная.","Ра́дуйся, руно́ ороше́нноє, на Него́же Влади́ка я́ко ка́пля дожде́вная ти́хо сни́деть, Гедео́ном предвеща́нноє.","Ра́дуйся, земле́ ненасі́янная, Сло́во Небе́сноє, я́ко пшени́цю плодоно́сную, чи́сто прозяба́ющая.","Ра́дуйся, ни́во неора́нная, Си́на Бо́жия, я́ко клас Боже́ственний, я́ві проізраста́ющая.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 7","ps":["Хотя́щи ві́ровати стра́шній та́йні Арха́нгелом возвеще́нной, Пресвята́я Ді́ва оба́че смути́ся промишля́ющи висоти́ сія́ вели́чество, і вся стидя́щися, глаго́лаше: Рци Мі, Гавриї́ле, і́стиннійшая, ка́ко нетлі́нній би́вши чистоті́ Моє́й, рожду́ с пло́тію Безпло́тнаго? Чудеса́ всегда́ би́ша мно́жицею Боже́ственною си́лою чудоді́йствуєма, ді́ва же неіскусому́жні нікогда́же роди́. Сего́ ра́ди ка́ко мо́жеть всі́ми невмісти́мий і всі́ми неви́димий во чре́во деви́чіє всели́тися, є́же Сам созда́? Рци Мі сія́, да с ві́рою воспою́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ва і стра́шна і чу́дна Твоя́ та́їнства, рече́ А́нгел Богоро́дице, і но́вую твар показа́ Тобо́ю всіх Творе́ць Госпо́дь, Ти бо Єди́на Царя́ Воплоща́єма приї́меши во утро́бі, да Ти Єди́на Ма́ти Си́на Бо́жия пронарече́шися, Чи́стая. Сего́ ра́ди не диви́ся чудеси́ і да не сумни́шися: “Бог, іді́же хо́щеть, побіжда́ється єстества́ чин”, вся бо возмо́жна суть Всемогу́щему. І я́коже от ребр Ада́мових создана́ бисть Є́ва без ма́тері дре́внім Богозда́нієм, та́ко і ни́ні от Твоєго́ ді́вства воплоща́ється без отця́ всіх Госпо́дь. І да уві́рить Тя жезл Ааро́нов невла́жно прозя́бший і руно́ Гедео́ново, зане́, я́ко ро́су, зача́тіє приї́меши, Нетлі́нная Ді́ва су́щи. Та́кожде і купина́ во огні́ неопа́льно преби́вшая да возвісти́ть Ті, я́ко приї́меши огнь, Божества́, Присноді́ва, і по Рождестві́ пребу́деши Чи́стая. Сего́ ра́ди прийми́ цілова́ніє моє́, да всі племена́ земна́я с ра́достію воспою́ть Тебі́:","Ра́дуйся, же́зле Ааро́нов, нетлі́ніє всему́ ми́ру прозя́бший.","Ра́дуйся, фи́никс Дави́дов, безсме́ртіє па́дшим лю́дем процві́тшій.","Ра́дуйся, Ски́ніє Небе́сная, от Херуви́мов осіня́ємая і ублажа́ємая.","Ра́дуйся, Свята́я Святи́х Бо́льшая, от Серафи́мов почита́ємая і присносла́вимая.","Ра́дуйся, Ча́ше Безсме́ртнаго Царя́, в Не́йже растворя́ється от Свята́го Ду́ха всеми́рная ра́дость.","Ра́дуйся, Ста́мно Боже́ственния ма́нни, от Нея́же ві́рним уготовля́ється неізрече́нная сла́дость.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 8","ps":["Стра́ннаго Рождества́ сего́ вели́чество смуща́єть М'я, — рече́ Пресвята́я Ді́ва ко А́нгелу, — поне́же Всеблаго́й благоволи́ па́че ума́ всели́тися в М'я, да храм чист душе́ю і пло́тію соблюде́н бу́ду Єму́, глас ра́дованія глаго́л твої́х приє́мши, весе́лія Боже́ственнаго ісполня́ються, да упраздни́ться ни́ні Мно́ю дре́внєє Є́вино осужде́ніє і да воздає́ться Мно́ю днесь долг челові́ков, да всі Сві́тлому Благові́щенію сему́ ра́дующеся, благода́рственно воспою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся твар ни́ні о Тебі́ ра́дується, Благода́тная, А́нгельський Собо́р і челові́чеський род, — рече́ Арха́нгел, — я́ко даде́ся Тебі́ ра́дость Боже́ственная і я́ко вся́коє обітова́ніє Бо́жиє Тобо́ю ни́ні приє́млеть коне́ць: Тобо́ю днесь благослови́ся Авраа́м о сі́мені своє́м. Тобо́ю ни́ні свободи́ся Є́ва от дре́внія печа́лі. Тобо́ю лику́єть Ада́м, я́ко днесь ісполня́ється пе́рвоє благові́стіє па́дшим лю́дем: сі́м'я Жени́ сотре́ть главу́ змі́я. Тобо́ю вся твар ни́ні начина́єть свобожда́тися от ра́бства тлі́нію в свобо́ду сла́ви чад Бо́жиїх. Тобо́ю ни́ні подаде́ся всему́ ро́ду челові́чеському вся́кая ра́дость і весе́ліє ві́чноє, да всі во ві́ки восхва́лять Тя си́це:","Ра́дуйся, Обра́дованная Ді́во, от дре́вніх патріа́рхов прообразова́нная.","Ра́дуйся, Свята́я Богоневі́сто, всі́ми проро́ки дре́вле предвозвіще́нная.","Ра́дуйся, Вертогра́ді заключе́нний, в Него́же Цар Небе́сний возжела́ вни́ти.","Ра́дуйся, Кла́дезю запечатле́нний, от Него́же нікто́же возмо́жеть іспи́ти.","Ра́дуйся, Са́де Боже́ственний, в Не́мже от всіх цвіто́в Свята́го Ду́ха ра́йськоє благоуха́ніє во весь мир ізнесе́ся.","Ра́дуйся, Раю́ новонасажде́нний, в Не́мже Боже́ственноє дре́во жи́зні посреді́ Тебе́ к прозябе́нію угото́вися.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся ни́ні о Тебі́, Пречи́стая, сли́шаще ди́вноє Твоє́ со Арха́нгелом Гавриї́лом собесі́дованіє і найпа́че моле́ніє Твоє́ сіє́: “Ду́шу очи́сти, Ті́ло освяти́, Це́рков сотвори́ М'я вмісти́тельну Бо́жию і Ски́нію богоукраше́ну, да наї́тієм Пресвята́го Ду́ха сотворю́ся храм одушевле́н і Ма́тер Чи́стая Жи́зні”. Єгда́ же по моли́тві сей ізрекла́ єси́ із смире́ннаго се́рдця Твоєго́: “Се Раба́ Госпо́дня, бу́ди Мі по глаго́лу твоєму́, да всели́ться Бог в М'я”, вся Небе́сния Си́ли просла́виша Бо́га, ви́дяще, я́ко гото́во се́рдце Твоє́ к прия́тію Боже́ственному, і со стра́хом і с ра́достію воспі́ша Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я Боже́ственний Святи́й Арха́нгел Гавриї́л бисть в стра́сі і в молча́нії глубо́цім і прекрати́ глаго́ли своя́, єгда́, Пресвята́я Ді́во, Ти ізрекла́ єси́ смире́нноє сло́во Своє́: “Се раба́ Госпо́дня, бу́ди Мі по глаго́лу твоєму́”. В нача́лі мирська́го битія́ тво́рчеським сло́вом сим: “да бу́деть”, Творце́м ізрече́нним, создана́ би́ша вся́чеськая ви́димая і неви́димая. Ни́ні же сло́во сіє́, Ді́вою ізрече́нноє, низведе́ Творця́ тва́рі в мир сей і та́ко открива́ється днесь є́же от ві́ка та́їнство вели́коє: Син Бо́жий Син Ді́ви бива́єть, да бо́га Ада́ма соді́лаєть. Соприсносу́щноє Сло́во О́тчеє, не разлучи́вся от го́рних, сни́де на зе́млю і бисть Плоть і всели́ся в ни, неізрече́нно істоща́ється і во Утро́бу Діви́чу вселя́ється. Да ра́дується у́бо не́бо і земля́ і со Арха́нгелом да поє́ть Пречи́стій Ді́ві си́це:","Ра́дуйся, Не́бо земно́є, до го́рних висо́т смире́нним ду́хом возше́дшеє.","Ра́дуйся, Селе́ніє Небе́сноє, Сло́во Бо́жиє неізрече́нно вмісти́вшеє.","Ра́дуйся, Благослове́нная, зача́тіє Преві́чнаго Бо́га нетлі́нно приє́мшая.","Ра́дуйся, Благода́тная, Черто́г Ді́вства Твоєго́ в зача́тії Єди́на сохра́ньшая.","Ра́дуйся, Чи́стая Ді́во, єстества́ уста́ви в боговоплоще́нії пресла́вно побіди́вшая.","Ра́дуйся, Богоневі́сто, єстество́ А́нгельськоє в благове́щенії Твоє́м преди́вно возвесели́вшая.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й мир, Человіколю́бець Госпо́дь сни́де, я́ко дождь на руно́ в Пречи́стую утро́бу Твою́, о Богома́ти, і а́біє неізрече́нним наї́тієм Свята́го Ду́ха соді́яся недові́домоє зача́тіє і Преві́чноє Сло́во Бо́жиє Плоть бисть і всели́ся в Тя, восприя́в Ю от Пречи́стих крове́й Твої́х без услажде́нія плотська́го, но не без услажде́нія духо́внаго: тогда́ бо Діви́чеськоє се́рдце Твоє́ боже́ственним іспо́лнися жела́нієм і дух Твой горя́ще пла́менем Серафи́мськия любві́, ум же весь, а́ки вні Себі́ бив, в Бо́зі углубля́шеся. І та́ко услажда́яся неізрече́ннаго Боголю́бія сего́ і у́мнаго Боговиді́нія, Ти поклони́лася єси́ Воплоща́ємому от Тебе́ Го́споду Твоєму́ і ра́достно воспі́ла єси́ Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і́бо ді́вственно от Ду́ха Свя́та зачала́ єси́ Предві́чнаго Бо́га і Ді́ва пребила́ єси́ і та́ко Є́ву от дре́внія печа́лі свободи́ла єси́. Днесь — ра́дость Благові́щенія, ді́вственноє торжество́ і та́їнство вели́ко, нача́ло на́шего спасе́нія. Днесь весели́ться не́бо і ра́дується земля́. Сего́ ра́ди вели́кий Гавриї́л пе́рвий от всея́ тва́рі, разумі́в ду́хом вели́коє боговоплоще́нія та́їнство, поклони́ся со стра́хом ве́ліїм вопло́щшемуся в деви́чей утро́бі Спа́су ми́ра і вопло́щшую Пречи́стую Ді́ву почти́ подоба́ющим поклоне́нієм, я́ко Цари́цю не́ба і землі́, і с благогові́нієм ве́ліїм воспі́ Єй такова́я:","Ра́дуйся, висо́каго та́їнства Воплоще́нія Бо́жия пречу́дноє соверше́ніє.","Ра́дуйся, неізрече́ннаго составле́нія Пло́ті Христо́вой пресла́вноє явле́ніє.","Ра́дуйся, черто́же безсі́меннаго уневі́щенія, в Не́мже Творе́ць всего́ ми́ра днесь вмісти́ся.","Ра́дуйся, Ковче́же Боже́ственнаго Воплоще́нія, І́мже ра́дость ве́лія всей вселе́нній ни́ні дарова́ся.","Ра́дуйся, Діви́це, Боготка́нную порфи́ру от Пречи́стия Пло́ті Твоєя́ Сло́ву Бо́жию істка́вшая.","Ра́дуйся, Отрокови́це, нетлі́нную багряни́цю от ді́вственних крове́й Твої́х А́гнцю Бо́жию взаїмода́вшая.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє принесла́ єси́, Пречи́стая, єгда́ по отше́ствії Арха́нгелові посіти́ла єси́ пра́ведную Єлисаве́ту ю́жицю Твою́ і возвісти́ла єй ра́дость Благові́щенія, во весе́лії ду́ха, глаго́люще: “Вели́чить душа́ Моя́ Го́спода і возра́довася дух Мой о Бо́зі Спа́сі Моє́м. Я́ко призрі́ на смире́ніє Раби́ Своєя́, се бо отни́ні ублажа́ть М'я всі ро́ди”. Сіє́ посіще́ніє Твоє́ возвесели́ пра́ведную Єлисаве́ту і взигра́ся от ра́дости младе́нець Іоа́нн во чре́ві єя́, і іспо́лнися Ду́ха Свя́та Єлисаве́т, і рече́: “Отку́ду мні сіє́, да при́йде Ма́ти Го́спода Моєго́ ко мні”. Да взигра́ється ни́ні і наш дух, ощуща́ющи в день Благові́щенія Твоєго́ ра́дость посіще́нія Твоєго́. Сего́ ра́ди с Єлисаве́тою возопіє́м Тебі́: “Благослове́нна Ти в жена́х і Благослове́н Плод чре́ва Твоєго́”, Єму́ же ви́ну да поє́м всі: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ ве́лій і Боже́ственний возсія́ в душі́ Твоє́й, Пречи́стая, єгда́ по гла́су Арха́нгела Дух Святи́й сни́де на Тя і Си́ла Ви́шняго осіни́ Тя і єгда́ а́біє зачала́ єси́ в Богоблагода́тній ді́вственній утро́бі Своє́й Творця́ сві́тов, Єго́же світ во тьмі сві́тить і тьма єго́ не об'я́т. Той просвіти́ Тя, я́ко со́лнце, сві́том Божества́ Своєго́, Всю просла́ви і обожи́, сего́ ра́ди “сія́єть добро́та Твоя́, блиста́єть чистоти́ Твоєя́ сві́тлость, я́коже предрече́ о Тебі́ в Пі́сніх Дух Святи́й: “Вся добра́ єси́, бли́жняя Моя́, і поро́ка ність в Тебі́”. Вся Ізбра́нна, Вся Преукраше́нна яви́лася єси́, Ю́же Бог возлюби́, Вся Чи́стая і Боже́ственний Сла́ви іспо́лненна. Сим Боже́ственним Твої́м Сві́том просвіща́ємії, да воспої́м Тя і ми в пі́сніх, я́ко Ма́тер Сві́та си́це:","Ра́дуйся, Свіще́ Боже́ственнаго Сві́та, Світ Невече́рній в утро́бі Твоє́й поне́сшая.","Ра́дуйся, Луче́ У́мнаго Со́лнця, весь мир сві́том Лиця́ Бо́жия просвіти́вшая.","Ра́дуйся, Небе́сний Світи́льниче, на сві́щниці земно́м всей вселе́нной возжже́нний.","Ра́дуйся, Живоно́сний Істо́чниче, благода́тію Ду́ха Свята́го преізоби́льно ороше́нний.","Ра́дуйся, Світоно́сная Ді́во, Єя́же ра́ди світ Богові́дінія днесь нам всім возсія́.","Ра́дуйся, Ізбра́нная Богоневі́сто, Є́юже ни́ні ра́дость неізрече́нная весь мир облиста́.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственная і ра́дость ве́лія процвіте́ днесь всему́ ми́ру, Пречи́стая, в світоно́сний день Благові́щенія Твоєго́, я́ко Тебе́ ра́ди в день он дре́вняя печа́ль преста́ і нача́ло спасе́нія челові́ков положи́ся: Син Бо́жий, Син Ді́ви яви́ся і земля́ Є́ви ра́ди проклята́ би́вшая, Тобо́ю, Ді́во, днесь па́ки благослови́ся. Херуви́м от дре́ва жи́зні отступа́єть і врата́ ра́йськия ві́рним днесь па́ки отверза́ються, мир же весь іспо́лнися ра́дости, отне́ліже вели́кий Гавриї́л є́же ра́дуйся Тебі́, Ді́во, сви́ше возгласи́. Сего́ ра́ди небеса́ у́бо досто́йно днесь да веселя́ться, земля́ же да ра́дується, вся́коє же диха́ніє і твар да пою́ть о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще всера́достноє от Арха́нгела Благові́щеніє Твоє́, Богоро́дице, восхваля́єм всі стра́шноє, пресла́вноє і ве́ліє та́їнство чи́стаго і ді́вственнаго от Ду́ха Свята́го зача́тія Твоєго́, поклоня́ємся нетлі́нно зача́тому от Тебе́ Си́ну Твоєму́ Христу́ Бо́гу на́шему і от всего́ се́рдця ві́руєм і іспові́дуєм, я́ко і в Боже́ственном зача́тії і по Рождестві́ Твоє́м Ти пребила́ єси́ Присноді́ва. Сего́ ра́ди с Гавриї́лом принесе́м Тебі́ сицеви́й Арха́нгельський глас:","Ра́дуйся, Благода́тная, облече́нная в Со́лнце, сія́ющая благода́тію і сла́вою всей вселе́нній.","Ра́дуйся, Благослове́нная, от восто́к со́лнця до за́пад препі́тая і превозноси́мая по всей поднебе́сній.","Ра́дуйся, А́нгельськоє вели́коє удивле́ніє, Гавриї́ла красото́ю ді́вства Своєго́ удиви́вшая.","Ра́дуйся, всему́ ми́ру благо́є весе́ліє, па́дшия лю́ди ра́достію Благові́щенія Твоєго́ возвесели́вшая.","Ра́дуйся, смире́нная Раба́ Госпо́дня, висото́ю смире́нія Своєго́ Бо́га на зе́млю низве́дшая.","Ра́дуйся, Милосе́рдная Ма́ти Бо́га Ви́шняго, Ма́тернім заступле́нієм Свої́м мно́гіє грі́шники ко Христу́ приве́дшая.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 13","ps":["О, Всепі́тая Паракли́та Неві́сто, Чи́стая бра́ка не позна́вшая Ді́во! Арха́нгела красото́ю Ді́вства удиви́вшая і Бо́гу Сло́ву Плоть нетлі́нно днесь взаїмода́вшая, ни́нішняя на́ша приє́мши приноше́нія о всера́достнем от Гавриї́ла благове́щенії Твоє́м, Христу́ Бо́гу обруче́нния в ді́встві сохрани́, всіх же в чистоті́ укріпи́ і от бід ізба́ви, да свобо́ждшеся Тобо́ю от ві́чних мук, Тобо́ю рай да обря́щем, іді́же всі да воспоє́м о Тебі́ Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л предстоя́й Престо́лу Бо́жию ви́ну зрить непристу́пную Боже́ственную Сла́ву, єгда́ же при́йде вре́м'я ізбавле́нія челові́ков, прия́ повелі́ніє Госпо́днє: Бу́ди служи́тель стра́шному чудеси́ і та́їнству сокрове́нному: милосе́рдієм Мої́м подви́гся ко взиска́нію заблу́дшаго Ада́ма, сни́ти тщу́ся. Гряди́ у́бо во град Назаре́т, в не́мже отрокови́ця Марі́я обита́єть, да прелюбе́зную красоту́ ді́вства у́зриши. Гряди́ к сему́ одушевле́нному Бо́жию Киво́ту, ко второ́му Небесі́ на землі́ су́щему. Іди́ к Сей Оби́телі Воплоще́нія Моєго́ і возвісти́ нетлі́нноє Моє́ от Нея́ прише́ствіє. Блюди́ же, да не смути́ши і да не устраши́ши ду́шу Ді́ви, да в ра́дості бу́деть, а не в печа́лі благові́стіє твоє́. Сего́ ра́ди приступи́ к Ней кро́тко і пе́рвий глас твой ра́дость Єй да принесе́ть, і да возопіє́ши Єй си́це:","Ра́дуйся, Благода́тная, Є́юже ра́дость возсія́єть.","Ра́дуйся, Обра́дованная, Є́юже кля́тва ісче́знеть.","Ра́дуйся, Благослове́нная, Є́юже вся твар обновля́ється.","Ра́дуйся, Препросла́вленная, Є́юже весь мир спаса́ється.","Ра́дуйся, Богоізбра́нная Отрокови́це, па́дшаго Ада́ма воззва́ніє.","Ра́дуйся, Пренепоро́чная Ді́во, слез Є́виних ізбавле́ніє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак 1","ps":["Ізбра́нной в предві́чнім Сові́ті Богоотрокови́це Марі́ї, послужи́ти ве́лію та́їнству боговоплоще́нія, сія́ющей ді́вственной чистото́ю па́че ви́сшия небе́сния чистоти́, благогові́йния пі́нія принесе́м Тебі́, Богоро́дице, о всера́достном от Арха́нгела благове́щенії Твоє́м. Ти же, я́ко обра́дованная і ра́дость па́дшим лю́дем пода́ти могу́щая, ізба́ви нас от вся́ких бід і гріхо́вния печа́лі, і возведи́ нас к небе́сній ра́дости, да с Гавриї́лом вопіє́м Тебі́:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Молитва перша","ps":["Прийми́, Всеблагомо́щная, Пречи́стая Госпоже́ Влади́чице Богороди́тельнице, сія́ честни́я да́ри, Тебі́ єди́ной прикла́дния от нас, недосто́йних рабо́в Твої́х, от всіх родо́в ізбра́нная, всіх тва́рей небе́сних і земни́х ви́шшая я́вльшаяся. Поне́же бо Тебе́ ра́ди бисть Госпо́дь сил с на́ми, і Тобо́ю Си́на Бо́жия позна́хом, і сподо́бихомся Свята́го Ті́ла Єго́ і Пречи́стия Кро́ве Єго́. Ті́мже блаже́нна єси́ в ро́діх родо́в, Богоблаже́нная, Херуви́мов світлі́йши і Серафи́мов честні́йши су́щая. І ни́ні, Всепі́тая Пресвята́я Богоро́дице, не преста́й моля́щися о нас, недосто́йних рабі́х Твої́х, є́же ізба́витися нам от вся́каго сові́та лука́ваго і от вся́каго обстоя́нія: і сохрани́тися нам неврежде́нним от вся́каго ядови́таго прило́га дия́вольськаго. Но да́же до конця́ моли́твами Твої́ми неосужде́нних нас соблюди́: я́ко да Твої́м заступле́нієм і по́мощію спаса́ємі, сла́ву, хвалу́, благодаре́ніє і поклоне́ніє за вся в Тро́йці Єди́ному Бо́гу і всіх Созда́телю возсила́єм, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["К Тебі́, Пречи́стій Бо́жієй Ма́тері, аз окая́нний, припа́дая, молю́ся: виждь, Цари́це, я́ко безпреста́нно согріша́ю і прогнівля́ю Си́на Твоєго́ і Бо́га моєго́. І мно́гажди а́ще ка́юся, лож пред Бо́гом обріта́юся, і ка́юся трепе́ща, да не ка́ко порази́ть м'я Госпо́дь, і по часі́ ма́лі па́ки та́яжде творю́. Сія́ ві́дущи, Влади́чице моя́, Пресвята́я Богоро́дице, почто́ не поми́луєши, почто́ не укріпи́ши м'я, і чесо́ ра́ди не пода́си мі всегда́ блага́я твори́ти? Ві́си у́бо, о Влади́чице, я́ко отню́дь і́мам в не́нависті зла́я моя́ діла́ і все́ю ми́слію люблю́ зако́н Бо́га моєго́. Но не вім, Госпоже́ Пречи́стая, отку́ду я́же ненави́жду, та́я творю́, і сей преступа́ю. Но не попуща́й, Пресвята́я, во́лі моє́й соверша́тися, неподо́бна бо єсть, но да бу́деть во мні во́ля Си́на Твоєго́ і Бо́га моєго́, да м'я спасе́ть, і вразуми́ть, і пода́сть мі благода́ть Свята́го Ду́ха, даби́ аз отни́ні преста́л скверноде́йствовати, і про́чеє бих пожи́л в повелі́ніїх Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь, поклоне́ніє і велелі́піє со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, Пресвята́я, Богоізбра́нная Ді́во, Свята́го Уті́шителя Ду́ха Всенепоро́чная Неві́сто, Пребоже́ственнаго же Отця́ Небе́снаго Дщер Превожделе́нная, посреді́ те́рнія ми́ра сего́ Тім обре́тенная, я́ко крин пресві́тлий добро́тою ді́вства блиста́ющийся, да Си́ну Бо́жию Чи́стая Ма́тер Неіскусобра́чная бу́деши! Что у́бо воздади́м Тебі́ в пресві́тлий день сей Благові́щенія, во́ньже Арха́нгела Гавриї́ла красото́ю безмі́рнаго ді́вства Своєго́ удиви́ла єси́ і от того́ неізрече́нноє обра́дованіє восприя́ла єси́? Что принесе́м Тебі́ за вся утіше́нія Твоя́, ї́миже возвесели́ла єси́ в день сей весь мир ви́димий і неви́димий, найпа́че же па́дший дре́вле род челові́ч? Днесь спасе́нія на́шего нача́ло і є́же от ві́ка та́їнства явле́ніє: ни́ні у́бо Сло́во Бо́жиє ти́хо сни́де с небе́с, я́ко ка́пля ка́плющая на зе́млю, і всели́ся в Твою́ Богоблагода́тную Ді́вственную утро́бу і бисть Плоть спасе́нія на́шего ра́ди. Сего́ ра́ди днесь А́нгели лику́ють на небесі́х і вся твар весели́ться і ра́дується, пра́зднующе нача́ло свобожде́нія своєго́ от рабо́ти істлі́нія в свобо́ду сла́ви чад бо́жиїх. Ни́ні ра́дується же́нськоє єстество́, Є́ви ра́ди па́дшеє, та бо повину́вшися змі́ю печа́ль роди́ жена́м і неудержа́нно введе́ смерть. Ти же, Ді́во, разріши́ла єси́ от го́ркия рабо́ти весь род челові́ч і свобо́дою Христо́вою єстество́ же́нськоє почти́ла єси́, зане́ ді́вством чи́стим па́ки і́стинную жизнь ввела́ єси́, і сего́ ра́ди же́ни, ді́вство держа́ще, врага́ я́ві побіжда́ти начина́ють. Ни́ні Ада́м лику́єть, ви́дів, я́ко в пресві́тлий день сей іспо́лнися на Тебі́ пе́рвоє ра́йськоє благові́стіє, я́ко сі́м'я Жени́ сотре́ть главу́ змі́я. С ни́мже ликовству́єть ни́ні весь род челові́ч, поне́же Тобо́ю, Пречи́стая, упраздни́ся днесь дре́внєє отвраще́ніє Бо́жиє к челові́ком, Бо́га бо па́ки привела́ єси́ к нам. Сего́ ра́ди зрим Тя ни́ні, я́коже дре́вле Іа́ков, я́ко Лі́ствицю Висо́кую, Є́юже сни́де Бог на зе́млю і я́ко Мост пречу́ден, і́мже су́щих от землі́ па́ки возво́диши на не́бо. Что воздади́м Тебі́, Цари́це не́ба і землі́, за вся сія́, і́миже ра́дость несказа́нную подала́ єси́ па́дшим і заблу́ждшим лю́дем Твої́м? Вся на́ші же́ртви і приноше́нія нічто́же суть пред вели́чеством благодія́ній Твої́х. Єди́ноє то́чію уго́дно Тебі́: “се́рдце сокруше́нно і смире́нно”, єго́же і Син Твой і Госпо́дь наш “не унічижи́ть”. Сего́ ра́ди мо́лим Тя: іспо́лни нас от превосходя́щия висоти́ смире́нія Своєго́ єли́ка вмісти́ти возмо́жем, да принесе́м Ті во всесвяти́й день Благові́щенія Твоєго́ Твоя́ от Твої́х, во є́же во вся́цім ді́лі бла́зі не ми́слити висо́кая, но ви́ну в смире́нії ду́ха пребива́ти. Се́ю пе́рвейшею доброді́телію укра́шени, в пресві́тлий день сего́ пра́здника Твоєго́ в кро́тости і чистоті́ се́рдця со Арха́нгелом Гавриї́лом возопіє́м тебі́: Ра́дуйся, Благода́тная, Ра́дуйся, Обра́дованная, Ра́дуйся, Преблагослове́нная, Госпо́дь с Тобо́ю і Тобо́ю с на́ми во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь спасе́нія на́шего глави́зна, / і є́же от ві́ка та́їнства явле́ніє: / Син Бо́жий, Син Ді́ви бива́єть, / і Гавриї́л благода́ть благовіству́єть. / Ті́мже і ми с ним Богоро́диці возопії́м: / ра́дуйся, Благода́тная, // Госпо́дь с Тобо́ю."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Арха́нгельський глас / вопіє́м Ті, Чи́стая: / Ра́дуйся, / Благода́тная, // Госпо́дь с Тобо́ю."]},{"h":"Задостойник","ps":["Благовіству́й, земле́, ра́дость ве́лію, / хвалі́те, Небеса́, Бо́жию сла́ву.","Я́ко одушевле́нному Бо́жию киво́ту, / да ніка́коже ко́снеться рука́ скве́рних. / Устні́ же ві́рних, Богоро́дице, немо́лчно, / глас А́нгела воспіва́юще, / с ра́достію да вопію́ть: / Ра́дуйся, Благода́тная, / Госпо́дь с Тобо́ю."]}],"notes":[]},{"u":"Акафіст Богоявленню Господньому","e":"Akathist to the Theophany of the Lord","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до, Царю́ не́ба і землі́, Тебі́ Просвіти́теля на́шего зря́ще во Іорда́ні от раба́ креща́єма, небеса́ ужасо́шася, і вся земля́ вострепета́, А́нгели же удиви́шася і вся твар возра́довася. Ми же недосто́йнії благода́рственно Тебі́ вопіє́м: ко грі́шником і митаре́м яви́лся єси́, да вода́ми оми́єши челові́ков гріхи́.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні Крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Ікос 1","ps":["А́нгельськия днесь предгряді́те си́ли, Влади́ку Христа́ зря́ще, ко Іорда́нським струя́м гряду́ща Ада́мов гріх очи́стити, і смотря́ще толи́коє Бо́жиє та́їнство, со стра́хом просла́віте ве́ліє снисхожде́ніє Єго́, я́ко Бог челові́ком уподо́бися і отню́дь не ві́дий гріха́ прихо́дить, я́ко А́гнець Бо́жий взя́ти всего́ ми́ра гріхи́. Сего́ ра́ди прославля́юще Боже́ственноє явле́ніє Христо́во, воспо́йте Єму́ я́коже і во Вифлеє́мі славосло́вія сицева́я:","Сла́ва Тебі́, Си́не Бо́жий, от Отця́ с небесе́ в мир сей прише́дий;","сла́ва Тебі́, Преви́шній Бо́же, да́же до ра́бія зра́ка снизше́дий.","Сла́ва Тебі́, Спаси́телю ми́ра, я́ко челові́ко ко Іоа́нну крести́тися гряди́й;","сла́ва Тебі́, Просвіти́телю тва́рі, я́ко нов Ада́м па́дшаго Ада́ма гріхи́ на Себі́ понеси́й.","Сла́ва Тебі́, Безнача́льний Сві́те, ве́лію зарю́ просвіще́нія всему́ ми́ру на Іорда́ні возсія́ти восхоті́вий;","сла́ва Тебі́, Со́лнце Пра́вди, світоно́сноє у́тро благода́ті челові́ком в Богоявле́нії Твоє́м дарова́ти возжела́вий.","Сла́ва Тебі́, мир от дре́внія пре́лести оми́ти прише́дшему;","сла́ва Тебі́, ве́ліє благоче́стія та́їнство нам показа́вшему.","Сла́ва Тебі́, чудеса́ ве́лія нам вода́ми мно́гими сотвори́вшему;","сла́ва Тебі́, небеса́ і всю зе́млю сві́том ра́зума просвіти́вшему.","Сла́ва Тебі́, фарао́на ми́сленнаго в струя́х Іорда́нських потопи́вшему;","сла́ва Тебі́, но́вия лю́ди во вода́х креще́нія к ві́чной жи́зні приве́дшему.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні Крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 2","ps":["Ви́дів ду́хом Боже́ственний Предте́ча Твоє́, Христе́, в мир прише́ствіє, при́йде із пусти́ні на Іорда́н, сві́тло лю́дем вопія́: Прибли́жися і яви́ся Ізбавле́ніє на́ше, пока́йтеся і водо́ю очи́стітеся, і срі́сти Єго́ потщі́теся, да чи́стими помишле́нії просвіща́ємі, душа́ми чи́стими і нескве́рними усти́ с весе́лієм воспо́йте Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний в себі́ явля́я, світи́льник Сві́та, вели́кий Предте́ча, возопи́ к лю́дем: Очи́стітеся, се бо предгряде́ть Христо́с от тлі мир ізбавля́яй, разріши́ти осужде́ніє Ада́ма Первозда́ннаго. Да возра́дується пусти́ня Іорда́нова і да процвіте́ть, я́ко крин, земля́ же вся ни́ні проро́чеськи да возра́дується. Угото́вайте путь Госпо́день і пра́ви сотворі́те стезі́ Бо́га на́шего, всі с весе́лієм возопи́йте Єму́ та́ко:","Сла́ва Тебі́, неізрече́нний Сві́те, от світи́льника ми́ру пред'явле́нний;","сла́ва Тебі́, Непостижи́мий Сло́ве, от гла́са Твоєго́ Предте́чею предрече́нний.","Сла́ва Тебі́, Огню́ чисти́тельний, Єго́же ді́йством вся́кая нечистота́ потребля́ється;","сла́ва Тебі́, Істо́чниче Благода́тний, І́мже вся́коє єстество́ челові́чеськоє освяща́ється.","Сла́ва Тебі́, Тво́рче не́ба і землі́, от раба́ крести́тися восхоті́вий;","сла́ва Тебі́, Си́не Єдиноро́дний, на Іорда́н яви́тися ізво́ливий.","Сла́ва Тебі́, Царю́ Пра́вди, у Него́же Предте́ча реме́нь сапогу́ разріши́ти убоя́ся;","сла́ва Тебі́, Влади́ко тва́рі, І́мже весь род челові́ч в Креще́нії Твоє́м возвесели́ся.","Сла́ва Тебі́, Преві́чний Бо́же, я́ко Явле́ніє Твоє́ просвіща́єть і вразумля́єть младе́нці;","сла́ва Тебі́, Сві́те ми́ра, я́ко прише́ствіє Твоє́ просветля́єть і умудря́єть сліпці́.","Сла́ва Тебі́, я́ко у Тебе́ Істо́чник живота́;","сла́ва Тебі́, я́ко во сві́ті Твоє́м у́зрим світ.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 3","ps":["Си́лу Божества́ Твоєго́, Христе́, уразумі́в Предте́ча, єгда́ со стра́хом уви́ді Тя на Іорда́н прише́дша, ра́дується душе́ю і трепе́щеть, руко́ю показу́я Тя, і глаго́леть лю́дем: Сей — ізбавля́яй мир от істлі́нія. Сей — свобожда́й нас от ско́рби. Сей — вмі́сто рабо́в, си́ни Бо́жії нас соді́ловаєть. Сей — вмі́сто тьми просвіща́єть челові́ки водо́ю Боже́ственнаго Креще́нія. Се — А́гнець Бо́жий Взе́мляй гріхи́ ми́ра, Єго́же сріта́юще, вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я бога́тство милосе́рдія, ко грі́шником і митаре́м на Іорда́нськую ріку́ прише́л єси́, Ісу́се, не терпі́л бо єси́ зрі́ти от дия́вола мучи́мий род челові́ч, но прише́л єси́, да па́ки рече́ши па́дшему Ада́му: «Гді єси́? Не скрива́йся от Мене́. Хощу́ бо ви́діти тя, а́ще наг єси́ і нищ, і та́ко уподо́бихся тебі́, да не стиди́шися». Сего́ ра́ди пропові́дуєм ве́ліє снисхожде́ніє Твоє́, вопію́ще Тебі́ такова́я:","Сла́ва Тебі́, Па́стирю До́брий, заблу́ждшеє овча́ взиска́ти восхоті́вий;","сла́ва Тебі́, Си́не Єдиноро́дний, понести́ то́є на ра́міх прише́дий.","Сла́ва Тебі́, Ми́лосте Безмі́рная, к челові́ком па́дшим до́лу низше́дий;","сла́ва Тебі́, Люби́ Неізрече́нная, лю́ди отча́янния па́ки го́ре возведи́й.","Сла́ва Тебі́, ру́ки осла́бленния ни́щим укріпля́яй;","сла́ва Тебі́, колі́на разсла́бленния убо́гим ісціля́яй.","Сла́ва Тебі́, пусти́ню жа́ждущую я́ко Лива́н возвесели́вий;","сла́ва Тебі́, пусти́ню Іорда́нову, я́ко Карми́л проізрасти́вий.","Сла́ва Тебі́, Ми́лостиве, я́ко льна куря́щася не угаси́ши;","сла́ва Тебі́, Долготерпіли́ве, я́ко тро́сти сокруше́нния не погубля́єши.","Сла́ва Тебі́, взиска́ти і спасти́ поги́бшія прише́дий;","сла́ва Тебі́, Ада́ма отринове́ннаго призва́ти восхоті́вий.","Сла́ва тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 4","ps":["Бу́рею помишле́ній сумни́тельних іспо́лнен бисть Предте́ча, Христе́ Царю́, єгда́ Ти, я́ко челові́к на ріку́ прише́л єси́ і ра́бськоє креще́ніє от него́ прия́ти восхоті́л єси́, глаго́ля: простри́ ру́ку твою́ і прикосни́ся верху́ Моєму́ і у́жас весь оттряси́, соверша́я повелі́нноє. Тре́петен бисть тогда́ Предте́ча і возопи́, глаго́ля: Что к рабу́ прише́л єси́, скве́рни не іми́й, Го́споди? Что мі повеліва́єши, я́коже ви́ше мене́? Висоти́ небе́сния ніка́коже ізслі́дих звізд число́, ніже́ зе́млю ніколи́же ізмі́рих. Ка́ко крещу́ Нося́щаго го́рстію твар? Ка́ко просвіти́ть світи́льник Сві́та? Ка́ко ру́ку положи́ть раб на Влади́ку? Аз тре́бую Тобо́ю крести́тися, да воспою́ Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Человіколю́бець Госпо́дь смире́нних Предте́чевих глаго́л висоту́ і ви́дів страх єго́, рече́ к нему́: до́брі, о Іоа́нні, я́ко благогові́єши предо Мно́ю, оба́че оста́ви ни́ні і отложи́ боя́знь твою́, до́лжен єси́ послужи́ти Мі, та́ко бо подоба́єть нам іспо́лнити вся́ку пра́вду, да во Мні челові́ков очи́стяться гріси́. Сему́ человіколю́бному сло́ву Твоєму́ вне́млюще, с любо́вію вопіє́м Тебі́ си́це:","Сла́ва Тебі́, Христе́, Сві́те і́стинний, я́ко ми́лость і і́стина о тебі́ сріто́стіся;","сла́ва Тебі́, Царю́ пра́вди, я́ко пра́вда і мир о тебі́ облобиза́стася.","Сла́ва Тебі́, Сладча́йший Ісу́се, я́ко і́стина Твоя́ во Вифлеє́мі от землі́ возсія́;","сла́ва Тебі́, Всеми́лостивейший Спа́се, я́ко пра́вда Твоя́ во Іорда́ні с небесе́ прини́че.","Сла́ва Тебі́, Очище́ніє на́ше, я́ко вода́ми креще́нія нас па́че сні́га убеля́єши;","сла́ва Тебі́, Просвіще́ніє на́ше, я́ко струя́ми благода́ті се́рдце чи́сто в нас созида́єши.","Сла́ва Тебі́, преклони́вий снизхожде́нієм Небеса́, главу́ Свою́ под ру́ку Предте́чеву преклони́ти восхоті́вий;","сла́ва Тебі́, Покрива́яй вода́ми преви́спренняя Своя́, во вода́х Іорда́нських погрузи́тися благоволи́вши.","Сла́ва Тебі́, Го́споди сил, Єго́же вся боя́ться і трепе́щуть, ве́лію боя́знь Предте́че отложи́ти повелі́вий;","сла́ва Тебі́, щедро́т О́тче, у него́же ми́лость безмі́рна і неізслі́дованна, ми́лостію Своє́ю гріхи́ ми́ра покри́ти ізво́ливий.","Сла́ва Тебі́, рожде́йся от Ді́ви, Спаси́телю наш, посіти́ нас неізрече́нним снизхожде́нієм Твої́м;","сла́ва Тебі́, явле́йся всему́ ми́ру, Христе́ Бо́же наш, освяти́ нас Боже́ственним явле́нієм Твої́м.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 5","ps":["Боготе́чная Струя́ сий бла́гости, Го́споди, в струи́ Іорда́нськия возше́л єси́, да вода́ми оми́єши челові́чеський гріх: У́жас бі ви́діти Творця́ небесі́ і землі́ в ріці́ обна́жшагося і от раба́ креще́ніє приє́млющаго. А́нгельськія си́ли дивля́хуся, Іорда́н же ріка́ возвраща́ше струї́ свої́, не могу́ще терпі́ти огня́ пояда́ющаго во́ди єго́, я́ко не оби́чно єму́ єсть Чи́стаго ізмива́ти і Безгрі́шнаго отира́ти. Сего́ ра́ди весели́ся Іорда́не ріко́, і да ра́дуються істо́чници і єзе́ра, і вся бе́здни і моря́, я́ко освяти́ся днесь водно́є єстество́, свободи́вшеся от тая́щагося та́мо кня́зя тьми, і вся твар веселя́щеся да поє́ть с на́ми: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів Тя Боже́ственний Іоа́нн Влади́ку тва́рі во вода́х погружа́єма, да гріхи́ всего́ ми́ра погрузи́ши, і, обнажи́вшагося, да Ада́мову наготу́ па́ки облече́ши во оде́жду сла́ви, вострепета́ душе́ю і возопи́ Тебі́, А́гнцю Бо́жию, очища́ющему согріше́нія ми́ра: «Не смі́ю прикосну́тися верху́ Твоєму́, Влади́ко, Сам м'я освяти́ і просвіти́, я́ко Ти єси́ Живо́т і Світ і Мир ми́рові». Оба́че по глаго́лу Твоєму́ со стра́хом возложи́ десни́цю свою́ на Боже́ственную главу́ Твою́, і крести́в Тя, Безгрі́шна су́ща, с ра́достію возопи́ Тебі́ си́це:","Сла́ва Тебі́, А́гнче Бо́жий, гріхи́ всего́ ми́ра взя́ти на Себі́ прише́дий;","сла́ва Тебі́, Спа́се Милосе́рдий, гріхи́ всіх челові́к потопи́ти во вода́х Іорда́нських восхоті́вий.","Сла́ва Тебі́, нас от скве́рни гріхо́вния оми́вий;","сла́ва Тебі́, преступле́ніє Ада́мово разріши́вий.","Сла́ва Тебі́, Твої́м на землі́ Богоявле́нієм всіх челові́к возвесели́вий;","сла́ва Тебі́, Твої́м во Іорда́ні Креще́нієм весь мир просвіти́вий.","Сла́ва Тебі́, нас ра́ди до о́браза ра́бськаго обнища́вшему;","сла́ва Тебі́, Твоє́ю нището́ю нас Обогати́вшему.","Сла́ва Тебі́, вра́жиє влади́чество Твої́м смире́нієм до конця́ низложи́вшему;","сла́ва Тебі́, Ца́рство Бо́жиє во Твоє́м креще́нії я́ві на землі́ созида́ти нача́вшему.","Сла́ва Тебі́, путь Спасе́нія на Іорда́ні па́дшим лю́дем показа́вшему;","сла́ва Тебі́, Світ Богові́дінія та́мо ві́рним Твої́м возсія́вшему.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 6","ps":["Пропові́дник ди́вний і Предте́ча Іоа́нн мно́гая ізрече́ приходя́щим лю́дем, во є́же угото́вати Тебі́ путь, Го́споди, оба́че умолче́, Тебі́ на Іорда́н прише́дшу, зане́ Ти Сам рекл єси́ єму́: «Не глаго́лю тебі́: рци Мі, я́же глаго́леши беззако́нним і учи́ши грі́шники, то́чію крести́ М'я молча́». Не подоба́ше бо гла́су челові́чеському возглаша́тися, прише́дшу Сло́ву Бо́жию і толи́кому та́їнству соверша́ющуся, єгда́ А́нгели Бо́жії со стра́хом предстоя́ху і вся твар вострепета́. Сего́ ра́ди і ми в молча́нії глубо́цім і со мно́гим благогові́нієм вопіє́м в се́рдці своє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ на Іорда́ні всему́ ми́ру просвіще́ніє ве́ліє і та́їнство стра́шноє єгда́, Влади́ко Христе́, крести́вся от Іоа́нна, Ти а́біє возше́л єси́ от води́, «совозводя́ с Собо́ю мир», і се отверзо́шася Тебі́ небеса́, я́же дре́вле Ада́м затвори́ себе́ і су́щим от него́, да па́ки возрожде́ннії Тобо́ю челові́ци восхожде́ніє улуча́ть в ра́йськия оби́телі, іді́же с ра́достію да воспою́ть Тебі́ си́це:","Сла́ва Тебі́, Царю́ ми́ра, средості́ніє вра́жиє разруши́вшему;","сла́ва Тебі́, ми́лости Пода́телю, рай преслуша́нієм затворе́нний, па́ки отве́рзшему.","Сла́ва Тебі́, не́бо гріхо́м заключе́нноє, на Іорда́ні па́ки отве́рзсто показа́вшему;","сла́ва Тебі́, А́нгели восходя́щия і нисходя́щия отсе́лі яви́ти обетова́вшему.","Сла́ва Тебі́, схожде́нієм Твої́м небеса́ до землі́ приклони́вшему;","сла́ва Тебі́, креще́нієм Твої́м зе́млю до небе́с возве́дшему.","Сла́ва Тебі́, открове́нієм небе́с неізрече́нний та́йни Бо́жия всему́ ми́ру откри́вшему;","сла́ва Тебі́, явле́нієм го́рняго ми́ра Святі́йшеє благослове́ніє Бо́жиє всім ві́рним препода́вшему.","Сла́ва Тебі́, небеса́ при Іліє́ заключи́вшему, не заключа́й нам две́рі милосе́рдія Своєго́;","сла́ва Тебі́, небеса́ на Іорда́ні отве́рзшему, отве́рзи нам вхо́ди Боже́ственнаго Черто́га Твоєго́.","Сла́ва Тебі́, бе́здну человіколю́бія при Креще́нії Твоє́м нам яви́вшему, возведи́ от бездн землі́ всіх до вра́жия отча́янія доше́дших.","Сла́ва Тебі́, восхо́д до тре́тьяго небесе́ ізбра́нним Твої́м сотвори́вшему, вознеси́ в небе́сния оби́телі і нас, до глубини́ гріха́ ниспа́дших.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 7","ps":["Хотя́й Человіколю́бець Госпо́дь спасти́ мир во грісі́х погиба́ющий, яви́ Тро́їчеськаго Богоявле́нія Своєго́ вели́коє та́їнство, і я́коже в нача́лі мирська́го битія́ Дух Бо́жий ноша́шеся верху́ во́ди, я́ко жи́зні Пода́тель, та́ко і при креще́нії Твоє́м, Го́споди, єгда́ на ріці́ Іорда́нстій восхоті́л єси́ обнови́ти і просвіти́ти погиба́ющий род челові́ч і всю твар с на́ми совоздиха́ющую, Той же Дух Святи́й па́ки сни́де с небесі́ отве́рста во ви́ді голуби́ні і почи́ над Тобо́ю, Го́споди, я́ко над но́вим Ада́мом, во є́же пребива́ти отни́ні в но́вих лю́діх ба́нею водно́ю возрожде́нних, да та́ко си́лою сви́ше облече́ннії во обновле́ніє ду́ха ходи́ти начну́ть, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́л єси́ твар, Влади́ко тва́рі, в Твоє́м от Іоа́нна спаси́тельном креще́нії, зане́ я́ко при Но́ї потопи́л єси́ гріхи́ пе́рваго ми́ра, та́ко і во вода́х Іорда́нських па́ки потопи́л єси́ всего́ ми́ра гріхи́, новотвори́ши бо земноро́дния огне́м і Ду́хом і водо́ю, стра́нноє соверша́я возрожде́ніє і обновле́ніє чу́дноє. Ду́хом бо новотвори́ши ду́ші, водо́ю же освяща́єши ті́ло, назида́я челові́ка, і та́ко та́їнственно от води́ соді́ловаєши Ду́хом многоча́дну Це́рков, да при́сно вопіє́м Тебі́ такова́я:","Сла́ва Тебі́, Созда́телю тва́рі, небеса́ приклони́вшему і на Іорда́н снизше́дшему;","сла́ва Тебі́, Спаси́телю ми́ра, небеса́ отве́рзшему і Ду́ха Боже́ственнаго нам яви́вшему.","Сла́ва Тебі́, Всебла́же, я́ко Дух Твой Благи́й наста́вить нас на зе́млю пра́ву;","сла́ва Тебі́, Всеще́дре, я́ко То́йже Дух Твой очи́стить нас от вся́кия скве́рни.","Сла́ва Тебі́, водо́ю і Ду́хом, обветша́вшеє гріхо́м єстество́ на́ше обнови́вшему;","сла́ва Тебі́, огне́м Божества́ в струя́х Іорда́нських многосві́тлоє просвіще́ніє дарова́вшему.","Сла́ва Тебі́, Христе́, вся Боже́ственния си́ли, я́же к животу́ і благоче́стію, Ду́хом Твої́м Святи́м при креще́нії ві́рним препода́вшему;","сла́ва Тебі́, Ісу́се, Нисше́ствієм Ду́ха Твоєго́ Свята́го прича́стники нас Боже́ственнаго єстества́ Сотвори́вшему.","Сла́ва Тебі́, почи́вшим на Тебі́ Ду́хом Прему́дрості і Ра́зума чи́стоє Богові́дініє лю́дем откри́вшему;","сла́ва Тебі́, схожде́нієм на Тя Ду́ха Бо́жия дух сові́та і крі́пости, ві́дінія і благоче́стія і дух стра́ха Бо́жия нам ізли́вшему.","Сла́ва Тебі́, Іорда́нською струє́ю змі́єви глави́ опали́вшему;","сла́ва Тебі́, явле́нієм Ду́ха Бо́жія во ви́ді голуби́ні ко голуби́ней кро́тости і чистоті́ ді́вственной нас призва́вшему.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся, і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 8","ps":["Стра́нно і ди́вно бисть явле́ніє святи́я Тро́йці на Іорда́ні: пе́рвіє Син Возлю́бленний яви́ся во пло́ті от раба́ креща́ємий, а́біє Дух Святи́й сни́де во ви́ді голуби́ні, посліди́ же Пребоже́ственний Оте́ць возгласи́ с небесе́, свиді́тельствуя: «Сей єсть Син Мой Возлю́бленний, о нем же благоволи́х». О, ве́ліє і пресла́вноє та́їнство: «Возгремі́ с небесе́ Госпо́дь і Ви́шній даде́ глас Свой», да сбу́деться Дави́да пра́отця предрече́ніє: «Глас Госпо́день на вода́х, Бог Сла́ви возгремі́, Госпо́дь на вода́х мно́гих. Глас Госпо́день в крі́пості, Глас Госпо́день во великолі́пії». Сего́ ра́ди і ми недосто́йними уста́ми вопіє́м Тебі́ із глубини́ душі́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ во ви́шніх, Ісу́се, ви́ну со Отце́м на небесі́х сосідя́й, но і от ни́жніх ніка́коже отступа́єши, пло́тію от Чи́стия Ді́ви во Вифлеє́мі рожде́нний, ни́ні же на Іорда́ні всему́ ми́ру яви́вийся, да су́щії во тьмі і сі́ні сме́ртній сідя́щия просвіти́ши сві́том Твоєго́ Богоявле́нія. Сего́ ра́ди, просвіти́вшеся сві́том Тро́їчеськаго Открове́нія, вопіє́м Тебі́, яви́вшемуся Бо́гу, і на землі́ ви́дінному і просвіти́вшему мир:","Сла́ва Тебі́, Си́не Бо́жий, во Ви́шніх со Отце́м і Ду́хом покланя́ємий;","сла́ва Тебі́, Си́не Оте́чь, Предте́чею от ни́жніх славосло́вимий.","Сла́ва Тебі́, сіди́й одесну́ю Отця́, Оте́чеським гла́сом с небесі́ пропові́данний;","сла́ва Тебі́, воплоти́вийся нас ра́ди, возлю́бленним Си́ном Бо́жиїм от Того́ всему́ ми́ру наймено́ванний.","Сла́ва Тебі́, во Іорда́нських струя́х явле́нний, Тро́йці Світ незаходи́мий в Креще́нії Твоє́м Показа́вий;","сла́ва Тебі́, дла́нію раба́ креще́нний, нас рабо́в су́щих ба́нею пакибитія́ си́ни Бо́жия сотвори́вий.","Сла́ва Тебі́, Істо́чниче жи́зні і безсме́ртія, па́ки рожде́нієм водо́ю і Ду́хом к пе́рвому благоро́дію ра́йському нас приведи́й;","сла́ва Тебі́, Тво́рче не́ба і землі́, о́гненним креще́нієм но́воє не́бо і зе́млю пра́вди Твоєя́ устро́їти гряди́й.","Сла́ва Тебі́, Восто́че восто́ков, во тьмі і сі́ні спя́щия Креще́нієм Твої́м просвіти́вий;","сла́ва Тебі́, Сві́те от Сві́та, Світ незри́мий Ду́ха Твоєго́ в душа́х на́ших возсія́вий.","Сла́ва Тебі́, Царю́ Безнача́льний, чи́стими струя́ми Креще́нія Твоєго́ прароди́тельський гріх всеконе́чні оми́вий;","сла́ва Тебі́, Влади́ко тва́рі, жа́ждущия лю́ди водо́ю жи́зні ві́чния всебога́тно напоі́вий.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 9","ps":["Все єстество́ А́нгельськоє удиви́ся вели́кому Твоєго́, Христе́, Богоявле́нія та́їнству: Ада́ма бо гріхо́м істлі́вшаго обнови́л єси́ Іорда́нськими струя́ми і глави́ гніздя́щихся та́мо неви́димих змі́єв сокруши́л єси́ во Твоє́м Креще́нії, і та́ко «глубини́ бе́здни сатани́нськия» откри́л єси́ «дно», да ізба́виши ни от тоя́ «глубо́ких вод», і да начне́ши созида́ти Ца́рство Твоє́, не от ми́ра сего́ су́щеє, о нем же проро́к Дави́д предрече́, глаго́ля: «Ца́рство Твоє́ — ца́рство всіх віко́в і Влади́чество Твоє́ — во вся́ком ро́ді і ро́ді», єго́же і ми прославля́юще с во́ї небе́сними вопіє́м Тебі́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я Боже́ственний і А́нгел Бо́жий, Малахі́єй предрече́нний, Вели́кий Предте́ча єди́н то́чію от челові́к сподо́бися, Го́споди, во Твоє́м Креще́нії Ду́ха прише́ствіє ви́діти і глас Оте́чеський с небесе́ сли́шати, свиде́тельствующий Твоє́ Богосино́вство, да бу́деть пе́рвий всему́ ми́ру пропові́дник Тро́їчеськаго Богоявле́нія. Той во у́трій день свиді́тельствова лю́дем, глаго́ля: «Ви́діх Ду́ха Сходя́ща, я́ко го́луб'я с небесе́, і преби́сть на Нем... І аз ви́діх і свиді́тельствовах, я́ко Сей єсть Син Бо́жий». Ми же сему́ богооткрове́нному свиді́тельству вне́млюще, прославля́єм Богоявле́ніє Твоє́, Христе́, пою́ще Тебі́ такова́я:","Сла́ва Тебі́, Бо́же Предві́чний, явле́нієм Свята́го Ду́ха свиді́тельствованний с небесе́;","сла́ва Тебі́, А́гнче Непоро́чний, гла́сом Предте́чі пропові́данний на землі́.","Сла́ва Тебі́, Крі́посте Височа́йшая, отве́рзстими над Іорда́ном небе́сними врати́ затворе́нний рай нам откри́вшему;","сла́ва Тебі́, Ми́лосте Предві́чная, Креще́нієм Твої́м но́вий мир от вод Іорда́нських челові́ком яви́вшему.","Сла́ва Тебі́, Царю́ ми́ра, мир і спасе́ніє на землі́ возвісти́вшему;","сла́ва Тебі́, Со́лнце Пра́вди, світ пра́вди Твоєя́ в душа́х на́ших возсія́вшему.","Сла́ва Тебі́, Свята́го Ду́ха в Твоє́м Богоявле́нії яви́вшему, да чи́стим ду́хом в небе́сний черто́г Твой совни́дем;","сла́ва Тебі́, Небе́снаго Отця́ в Креще́нії Твоє́м нам показа́вшему, да всі пра́во в Тя ві́рующії си́нове Єго́ бу́дем.","Сла́ва Тебі́, в Ду́сі і огні́, очерні́вшеє гріхо́м єстество́ на́ше пресла́вно просвіща́ющему;","сла́ва Тебі́, водо́ю і Ду́хом істлі́вшеє страстьми́ неможе́ніє на́ше пресві́тло очища́ющему.","Сла́ва Тебі́, Бо́гу я́вльшемуся пло́тію, весь мир в струя́х Іорда́нських обнови́вшему;","сла́ва Тебі́, взе́мльшему на себі́ гріхи́ ми́ра, прароди́тельський гріх во вода́х Креще́нія потопи́вшему.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся, і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й па́дшеє і обнища́вшеє єстество́ на́ше, Христе́ Спа́се, на Іорда́нськую ріку́ прише́л єси́ ко грі́шником і митаре́м і восприя́л єси́ креще́ніє от Іоа́нна, єгда́ крести́шася всі лю́діє, да во́зьмеши на Себі́ вся, погруже́нния та́мо во вода́х, челові́ков гріхи́, я́ко А́гнець Бо́жий і да гото́в бу́деши отсе́лі во́лею на закла́ніє тещи́ іскупи́ти всего́ ми́ра гріхи́ драгоце́нною кро́вію Твоє́ю. Сего́ ра́ди і погрузи́лся єси́ в Іорда́нськія струї́, да спогре́бшися та́мо, ко сме́ртному креще́нію Себі́ угото́виши, о не́мже рекл єси́ ко страда́нію Гряди́й: «Креще́нієм і́мам крести́тися і ка́ко томлю́ся, до́ндеже істя́жуть». Сего́ ра́ди благода́рственно поє́м Тебе́: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чний Христе́ Ісу́се! Ти прише́л єси́ на Іорда́н во явле́ніє всему́ ми́ру, да разріши́ши осужде́ніє Ада́ма первозда́ннаго, я́ко Судія́ Всеми́лостивий, Єди́н сердца́ всіх іспиту́яй, і да пода́си но́вую жизнь челові́ком. Сего́ ра́ди чисти́тельную лопа́ту руко́ю приє́м, всеми́рноє гумно́ всему́дре очи́стил єси́, разлуча́я, я́ко Па́стир, о́вці от ко́злищ. Сподо́би і нам, во і́м'я Пресвяти́я Тро́йці креще́нним, десни́я ча́сти спаса́ємих в жи́зні сей всемі́рно іска́ти, да уго́дно Тебі́ бу́деть на́ше глаше́ніє Тебі́ сицево́є:","Сла́ва Тебі́, Архієре́ю, небеса́ проше́дий, в Креще́нії Твоє́м всю зе́млю онебеси́вий;","сла́ва Тебі́, Па́стирю овця́м Вели́кий, ко ста́ду Твоєму́ на Іорда́н прише́дий.","Сла́ва Тебі́, зе́млю на вода́х основа́вий, всю зе́млю на́шу на вода́х Іорда́нських благода́тію Ду́ха обнови́вий;","сла́ва Тебі́, над вода́ми не́бо утвержде́й второ́є, но́воє не́бо Це́рков Твою́ вода́ми Креще́нія сотвори́вий.","Сла́ва Тебі́, Істо́чниче жи́зні на́шея, на істо́чники спасе́нія жа́ждущия лю́ди Твоя́ призва́вий;","сла́ва Тебі́, Пропові́дниче пра́вди ві́чния, духо́вную жа́жду на́шу без ціни́ і сребра́ утоли́вий.","Сла́ва Тебі́, я́ко бога́т Сий в ми́лості, за премно́гую любо́в нас возлюби́л єси́;","сла́ва Тебі́, я́ко ме́ртвих нас су́щих гріхми́, вода́ми креще́нія оживотвори́л єси́.","Сла́ва Тебі́, струя́м Іорда́нським спогре́бшемуся, да і ми в креще́нії в смерть і воскресе́ніє Тебі́ спогребе́мся;","сла́ва Тебі́, вода́ми Іорда́нськими, я́ко ри́зою обле́кшемуся, да і ми в сві́тлия ри́зи пра́вди і чистоти́ Тобо́ю облече́мся.","Сла́ва Тебі́, средості́ніє вражди́ Пло́тію Твоє́ю разруши́вшему, да і нас, дале́че в мо́ре су́щих, близ Себе́ устро́їши;","сла́ва Тебі́, твої́х челові́к во єди́нім Ті́лі Твоє́м примири́вшему, да і нас стра́нних і прише́льцев во єди́ную Це́рков Бо́жию сози́ждеши.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 11","ps":["Пі́ніє новолі́пноє да поє́ть Тебі́, Христе́, вся твар, от Ді́ви ро́ждшемуся і днесь во Іорда́ні крести́вшемуся, лю́діє же всі духо́вно да возвеселя́ться, прославля́юще сві́тлоє просвіще́нія на́шего торжество́ і с боже́ственним Григо́рієм да воспою́ть, глаго́люще: «Возрожде́нія вре́м'я — возроді́мся сви́ше, возсозда́нія день — облеце́мся в Но́ваго Ада́ма, просвіще́нія пра́здник — просвіті́мся боже́ственне», да во обновле́нії ду́ха ходи́ти начне́м, ви́ну со А́нгели пою́ще небе́сную піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлий і Самосія́нний Сві́ті, Христе́, Соприсносу́щний Сві́те Єдиносу́щнаго Отця́! Возже́г посреди́ Іорда́на, я́ко Твою́, світи́льник, пречи́стую Плоть Твою́, Ти возсія́л єси́, я́ко Со́лнце і дарова́л єси́ вселе́нній в Креще́нії Твоє́м ве́лій і незри́мий світ Твоєя́ благода́ті і і́стини, просвіща́яй вся́каго челові́ка гряду́щаго в мир, да лю́діє седя́щиє во тьмі і сі́ні сме́ртной у́зрять світ ве́лій і по́йдуть по нему́. Просвіти́ у́бо во вели́кий день Сві́тов і нас во тьмі гріха́ єще́ блужда́ющих, да просветля́яся, обновля́яся і возвиша́яся го́ре, воспоє́м Тебі́ такова́я:","Сла́ва Тебі́, Просвіти́телю ми́ра, Ду́хом Святи́м і огне́м крести́ти прише́дшему;","сла́ва Тебі́, Спаси́телю грі́шних, із глубини́ гріха́ нас воздви́гнути восхоті́вшему.","Сла́ва тебі́, Безнача́льний і Присносу́щний Сві́те, скве́рну душ на́ших вода́ми креще́нія очища́яй;","сла́ва Тебі́, Сві́те преви́сший всіх сві́тлостей, во сві́тлостіх святи́х Твої́х ві́рния озаря́яй.","Сла́ва Тебі́, Сла́ви О́тчія Сія́ніє, тьму неві́дінія явле́нієм Твої́м разгна́вшему;","сла́ва Тебі́, во Сві́ті живи́й непристу́пнім, Світ богові́дінія Креще́нієм Твої́м возсія́вшему.","Сла́ва Тебі́, Сві́те от Сві́та во тьмі возсія́вий, от тьми гріхо́в очи́сти нас;","сла́ва Тебі́, Со́лнце Пра́вди, у́тро спасе́нія возвіща́ющеє, во сві́ті до́брих діл наста́ви нас.","Сла́ва Тебі́, Невече́рній Сві́те, во Іорда́ні возсія́вий, во Сві́ті Твоє́м Світ незаходи́мий Пресвяти́я Тро́йці облиста́й нам;","сла́ва Тебі́, о́бразе Пресві́тлий Іпоста́си О́тчія, к чу́дному нестарі́ємому животу́ ба́нею пакибитія́ приведи́ нас.","Сла́ва Тебі́, сме́рти Низложи́телю, от ві́чния сме́рти ізба́ви нас;","сла́ва Тебі́, живота́ Нача́льниче, к ві́чній жи́зні наста́ви нас.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия спаси́тельная всім челові́ком яви́ся днесь во Твоє́м Креще́нії, Христе́ Спа́се: прише́л бо єси́ на Іорда́н, Єди́не Чи́стий, очи́стити челові́чеськая согріше́нія і сокруши́ти глави́ гніздя́щихся та́мо змі́єв, да да́руєши благода́ть креще́нія ріши́тельную душ і тіле́с на́ших. Сего́ ра́ди с благоче́стієм притеце́м прилі́жно к пречи́стим істо́чником, да почерпе́м с весе́лієм во́ду жи́зні, благода́ть бо Ду́ха неви́димо подає́ться всім ві́рно почерпа́ющим ю, і та́йная дарова́нія і Дух позна́нія, Спа́се, та всі благода́рственно воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще, Христе́, Твоє́ спаси́тельноє Богоявле́ніє, прославля́єм всі во Іорда́нських вода́х от Іоа́нна Боже́ственноє Креще́ніє Твоє́, поклоня́ємся неізрече́нному к па́дшим челові́ком снисхожде́нію Твоєму́ і ві́руєм со Предте́чею, я́ко Ти воі́стину — А́гнець Бо́жий, Взе́мляй на Себі́ от вод Іорда́нських гріхи́ всего́ ми́ра, да оми́єши і іску́пиши їх Пречи́стою Кро́вію Твоє́ю. Сего́ ра́ди мо́лим Тя: понеси́ і на́ші безчи́сленния гріхопаде́нія і не лиши́ нас во вели́кий день Сві́тов благода́тного возрожде́нія Твоєго́, да чи́стим се́рдцем благода́рственно вопіє́м Тебі́ си́це:","Сла́ва Тебі́, Си́не Бо́жий, ве́лій світ к просвіще́нію всего́ ми́ра во вода́х Іорда́нських возсія́вшему;","сла́ва Тебі́, Предві́чний Бо́же, ве́лію благода́ть і человіколю́біє в Креще́нії Твоє́м всім челові́ком яви́вшему.","Сла́ва Тебі́, Спаси́телю заблу́ждших, заблу́ждшия безпу́тієм челові́ки ко Іорда́нським струя́м іска́ти прише́дшему;","сла́ва Тебі́, Побіди́телю жи́зні, но́вую чи́стую жизнь не по пло́ті, но во обновле́ніє ду́ха дарова́ти благоволи́вшему.","Сла́ва Тебі́, Влади́ко Живота́ і сме́рті, жа́ло сме́рти притупи́вшему і нетлі́нную жизнь явле́нієм свої́м возсія́вшему;","сла́ва Тебі́, Тво́рче не́ба і землі́, го́рнєє не́бо і зе́млю на брега́х Іорда́на в Креще́нії Твоє́м возвесели́вшему.","Сла́ва Тебі́, Царю́ ца́рствующих, я́ко ца́рство ми́ра сего́ отсе́лі в Ца́рство Твоє́ начина́єть прелага́тися;","сла́ва Тебі́, Го́споди госпо́дствующих, я́ко днесь всім хотя́щим спасти́ся небеса́ отверза́ються і все єстество́ на́ше начина́єть убеля́тися.","Сла́ва Тебі́, Спа́се наш, на Іорда́н прише́дий, спаси́ нас не от діл пра́ведности, но по вели́цій Твоє́й ми́лості;","сла́ва Тебі́, Христе́ Бо́же, водно́є єстество́ освяти́вий, жа́ждущую ду́шу мою́ благоче́стія напо́й вода́ми по неізрече́нній Твоє́й бла́гості.","Сла́ва Тебі́, Єдиноро́дний Си́не і Сло́ве Бо́жий, напита́й се́рдце моє́ явле́нієм слове́с Твої́х;","сла́ва Тебі́, Всеси́льний Бо́же, Творя́й чудеса́ Єди́н, согрі́й хла́дную ду́шу мою́ разумі́нієм чуде́с Твої́х.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 13","ps":["О, Ісу́се Христе́, А́гнче Бо́жий, прише́дий на Іорда́н под'я́ти всего́ ми́ра гріхи́! Прийми́ ма́лоє сіє́ от всея́ душі́ приноси́моє Тебі́ моле́ніє на́ше, і просвіти́ нас во тьмі гріхо́в сідя́щих спаси́тельним Твої́м от Іоа́нна Креще́нієм, да іскупле́ннії Тобо́ю от болі́зней душе́вних і тіле́сних, во обновле́нії жи́зні пра́во ходи́ти начне́м і со всі́ми святи́ми да воспоє́м Тебі́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськия днесь предгряді́те си́ли, Влади́ку Христа́ зря́ще, ко Іорда́нським струя́м гряду́ща Ада́мов гріх очи́стити, і смотря́ще толи́коє Бо́жиє та́їнство, со стра́хом просла́віте ве́ліє снисхожде́ніє Єго́, я́ко Бог челові́ком уподо́бися і отню́дь не ві́дий гріха́ прихо́дить, я́ко А́гнець Бо́жий взя́ти всего́ ми́ра гріхи́. Сего́ ра́ди прославля́юще Боже́ственноє явле́ніє Христо́во, воспо́йте Єму́ я́коже і во Вифлеє́мі славосло́вія сицева́я:","Сла́ва Тебі́, Си́не Бо́жий, от Отця́ с небесе́ в мир сей прише́дий;","сла́ва Тебі́, Преви́шній Бо́же, да́же до ра́бія зра́ка снизше́дий.","Сла́ва Тебі́, Спаси́телю ми́ра, я́ко челові́ко ко Іоа́нну крести́тися гряди́й;","сла́ва Тебі́, Просвіти́телю тва́рі, я́ко нов Ада́м па́дшаго Ада́ма гріхи́ на Себі́ понеси́й.","Сла́ва Тебі́, Безнача́льний Сві́те, ве́лію зарю́ просвіще́нія всему́ ми́ру на Іорда́ні возсія́ти восхоті́вий;","сла́ва Тебі́, Со́лнце Пра́вди, світоно́сноє у́тро благода́ті челові́ком в Богоявле́нії Твоє́м дарова́ти возжела́вий.","Сла́ва Тебі́, мир от дре́внія пре́лести оми́ти прише́дшему;","сла́ва Тебі́, ве́ліє благоче́стія та́їнство нам показа́вшему.","Сла́ва Тебі́, чудеса́ ве́лія нам вода́ми мно́гими сотвори́вшему;","сла́ва Тебі́, небеса́ і всю зе́млю сві́том ра́зума просвіти́вшему.","Сла́ва Тебі́, фарао́на ми́сленнаго в струя́х Іорда́нських потопи́вшему;","сла́ва Тебі́, но́вия лю́ди во вода́х креще́нія к ві́чной жи́зні приве́дшему.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні Крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до, Царю́ не́ба і землі́, Тебі́ Просвіти́теля на́шего зря́ще во Іорда́ні от раба́ креща́єма, небеса́ ужасо́шася, і вся земля́ вострепета́, А́нгели же удиви́шася і вся твар возра́довася. Ми же недосто́йнії благода́рственно Тебі́ вопіє́м: ко грі́шником і митаре́м яви́лся єси́, да вода́ми оми́єши челові́ков гріхи́.","Сла́ва Тебі́, Си́не Бо́жий, во Іорда́ні Крести́вийся і весь мир просвіще́й, сла́ва Тебі́."]},{"h":"Молитва","ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий Єдиноро́дний, от Отця́ пре́жде всіх вік рожде́нний, Сві́те от Сві́та, просвіща́яй вся́чеськая, в послі́дняя же літа́ от Пресвяти́я Ді́ви Марі́ї нетлі́нно воплоще́нний і в мир сей на спасе́ніє на́ше прише́дий! Ти бо не потерпі́л єси́ ви́діти от дия́вола му́чима ро́да челові́ча і сего́ ра́ди в пресві́тлий день Богоявле́нія Твоєго́ прише́л єси́ на Іорда́н ко грі́шником і митаре́м крести́тися от Іоа́нна, безгрі́шен сий, да іспо́лниши вся́кую пра́вду і да во́зьмеши во вода́х Іорда́нських гріхи́ всего́ ми́ра, я́ко А́гнець Бо́жий, во є́же понести́ я на Себі́ і іскупи́ти Креще́нієм кре́стним, пречи́стою Кро́вію Твоє́ю. Сего́ ра́ди погрузи́вшуся Тебі́ во вода́х, отверзо́шася Тебі́ небеса́ Ада́мом заключе́нная і Дух Святи́й сни́де на Тя во ви́ді голуби́ні, просвіще́ніє і обоже́ніє нося́й єстеству́ на́шему, і Пребоже́ственний Оте́ць Твой возвісти́ Тебі́ небе́сним гла́сом благоволе́ніє Своє́, зане́ сотвори́л єси́ во́лю Єго́ і челові́ко гріхи́ восприя́л єси́ і Себе́ на закла́ніє уже́ предугото́вал єси́, я́коже Сам рекл єси́: «Сего́ ра́ди лю́бить М'я Оте́ць, я́ко Аз ду́шу Мою́ полага́ю, да па́ки прийму́ ю», і та́ко во всесві́тлий день сей, Ти, Го́споди, положи́л єси́ нача́ло іскупле́нія на́шего от гріхопаде́нія прароди́тельськаго. Сего́ ра́ди вся си́ли небе́сния ра́дуються і вся твар весели́ться, ча́юще свобожде́ніє своє́ от рабо́ти істлі́нія, глаго́люще: Приї́де просвіще́ніє, благода́ть яви́ся, ізбавле́ніє наста́, мир просвіти́ся і лю́діє ра́достію ісполня́ються. Да весели́ться ни́ні не́бо і земля́ і мир весь да ігра́єть; рі́ки да пле́щуть; істо́чници і єзе́ра, бе́здни і моря́ да сра́дуються, я́ко Боже́ственним Креще́нієм освяти́ся днесь єстество́ їх. Да ра́дуються днесь і челові́ков собо́ри, я́ко єстество́ їх взи́де ни́ні па́ки к пе́рвому благоро́дію і всі с ра́достію да пою́ть: Богоявле́нія вре́м'я. Прийді́те ми́сленно на Іорда́н, виді́ніє ве́ліє в нем у́зрим: Христо́с ко Креще́нію гряде́ть. Христо́с ко Іорда́ну прихо́дить. Христо́с на́ші во воді́ погреба́єть гріхи́. Христо́с овча́ похище́ннаго і заблу́ждшаго прихо́дить іска́ти і обрі́т є вво́дить в рай.","Сего́ Боже́ственнаго та́їнства воспомина́ніє пра́зднующе, усе́рдно мо́лимся Тебі́, Человіколю́бче Го́споди: сподо́би нам жа́ждущим по гла́су Твоєму́ прийти́ к Тебі́, Істо́чнику присноживо́тния води́, да почерпе́м во́ду благода́ті Твоєя́ і оставле́нія гріхо́в на́ших і да отве́ргшеся нече́стія і мирськи́х по́хотей; цілому́дренно і ді́вственно, і пра́ведно і благоче́стно поживе́м в ни́нішнем ві́ці, жду́ще блаже́ннаго упова́нія і явле́нія сла́ви Твоєя́, Вели́каго Бо́га і Спа́са на́шего, да не от діл на́ших спасе́ши нас, но по Твоє́й ми́лості і по обновле́нію Свята́го Ду́ха Твоєго́ ба́нею пакибитія́, Єго́же оби́льно ізлія́л єси́, да оправди́вшеся благода́тію Єго́, наслі́дници бу́дем ві́чния жи́зні во Ца́рствії Твоє́м, іді́же со всі́ми святи́ми сподо́би нам просла́вити всесвято́є І́м'я Твоє́ со Безнача́льним Твої́м Отце́м і со Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Во Іорда́ні креща́ющуся Тебі́, Го́споди, / Тро́йчеськоє яви́ся поклоне́ніє: / Роди́телев бо глас свиді́тельствоваше Тебі́, / возлю́бленнаго Тя Си́на імену́я, / і Дух во ви́ді голуби́ні, / ізві́ствоваше словесе́ утвержде́ніє. / Явле́йся Христе́ Бо́же, // і мир просвіще́й, сла́ва Тебі́."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ днесь вселе́нній, / і світ Твой, Го́споди, зна́менася на нас, / в ра́зумі пою́щих Тя: / прише́л єси́, і яви́лся єси́, // Світ Непристу́пний."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / нас ра́ди ни́ні пло́тію крести́вшагося / от Іоа́нна // во вода́х Іорда́нських."]},{"h":"Задостойник","ps":["Велича́й, душе́ моя́, / Честні́йшую Го́рніх Во́їнств, // Ді́ву Пречи́стую Богоро́дицю.","Недоумі́єть всяк язи́к благохвали́ти по достоя́нію, / ізуміва́єть же ум і преми́рний пі́ти Тя, Богоро́дице; / оба́че Блага́я су́щи, ві́ру прийми́, / і́бо любо́во ві́си Боже́ственную на́шу: // Ти бо христия́н єси́ Предста́тельниця, Тя велича́єм."]}],"notes":[]},{"u":"Акафіст Введенню в храм Пресвятої Богородиці","e":"Akathist to the Entry of the Theotokos into the Temple","secs":[{"h":"Кондак 1","ps":["Ізбра́нній Предві́чним Царе́м Богоотрокови́це Марі́ї, А́нгелов і челові́ков Цари́це, прише́дшей іногда́ в храм Госпо́день во Свята́я Святи́х, на обруче́ніє ді́вства Своєго́ Жениху́ Небе́сному воспита́тися в Бо́жиє Жили́ще, досто́йноє поклоне́ніє усе́рдно Тебі́ прино́сим, Ти же я́ко многомо́щная Засту́пниця на́ша, от вся́ких нас бід і скорбе́й свободи́, да с любо́вію і умиле́нієм Тебі́ вопіє́м:","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов ли́ки от небе́сних висо́т стеко́шася ви́діти пресла́вноє Твоє́, о Богома́ти, во храм Госпо́день Введе́ніє і вку́пі с земни́м ли́ком чи́стих дів неви́димий лик безпло́тних умо́в с весе́лієм ідя́ше, Тя, Пречи́стая Ді́во, провожда́юще і я́ко сосу́д ізбра́нний Бо́гу повелі́нієм Госпо́днім окружа́юще, і я́ко Госпоже́ своє́й служа́ще, а́ще не ви́дісте та́йни Твоєя́ си́лу, ви́дяще же Тя небе́сния чистоти́ неізрече́нно іспо́лнену, і вся би́вшая о Тебі́ зря́ще, ужаса́хуся і со стра́хом мно́гим воспі́ша Тебі́ та́ко:","Ра́дуйся, прера́дованная Ді́во, Ма́ти Царе́ва іму́щая би́ти.","Ра́дуйся, предпочте́нная Цари́це, в храм Царе́в гряду́щая жи́ти.","Ра́дуйся, Бо́га Отця́ Дщер ізбра́нная і превознесе́нная.","Ра́дуйся, Бо́га Си́на Ма́тер от ві́ка предрече́нная.","Ра́дуйся, Бо́гу Ду́ху Всесвято́му Неві́сто неіскусобра́чная.","Ра́дуйся, всея́ Тва́рі ви́димия і неви́димия Влади́чиця превожделе́нная.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 2","ps":["Ви́дяще пра́веднії роди́телі Твоя́, Пресвята́я Ді́во, я́ко три лі́та іспо́лнишася от рождества́ Твоєго́, восхоте́ста соверши́ти ді́лом обітова́ніє своє́, є́же пе́рвіє словеси́ ізреко́ша, да принесу́ть Тя в дар Бо́гу, сего́ ра́ди созва́ша в Назаре́т вся сро́дники своя́ от ца́рськаго і архієре́йського ро́да, і свяще́нники мно́гія, пригла́сиша же і лик чи́стих дів, да со свіщи́ горя́щими провожда́ють Тя, я́ко же предрече́ Писа́ніє: «приведу́ться Царю́ ді́ви в слід Єя́, і́скреннія Єя́ приведу́ться Тебі́, приведу́ться во весе́лії і ра́дованії, введу́ться в храм Царе́в». І та́ко совоку́пльшеся всі і помоли́вшеся о Тебі́ Бо́гу, воспі́ша Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Небе́сний открива́я, Богоотрокови́це, благоволи́ла єси́, я́ко да не в нище́тних ру́бищах предста́неши ко хра́му Царю́ Небе́сному, сего́ ра́ди преоде́яна била́ єси́ со сла́вою і красото́ю мно́гою, да іспо́лниться на Тебі́ Дави́да пра́отця Твоєго́ предрече́ніє: «Предста́ Цари́ця одесну́ю Тебе́, в ри́зах позлаще́нних оді́яна, преіспещре́на». Єгда́ же, я́ко Неві́ста Бо́жия преукра́шена била́ єси́ і вся ко всечестно́му Введе́нію Твоєму́ досто́йна устро́їшася, поведо́ста Тя роди́телі Твоя́, я́ко трехле́тнюю а́гницю во Ієрусали́м, воспі́вше Тебі́ та́ко:","Ра́дуйся, преоде́янная в ря́сни злати́я ді́вства і чистоти́.","Ра́дуйся, преукра́шенная во вся добро́ти небе́сния красоти́.","Ра́дуйся, Дщи Царе́ва всю сла́ву ді́вственную внутр Себі́ іму́щая.","Ра́дуйся, Неві́сто Бо́жия, предста́ти одесну́ю Небе́сному Жениху́ гряду́щая.","Ра́дуйся, одушевле́нний Киво́те Бо́жий, посреді́ дів тимпа́нниць ше́ствія своя́ устроя́яй.","Ра́дуйся, пречи́стий Храм Спа́сов, ко хра́му зако́нному путі́ Своя́ направля́яй.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Тя і Дух Святи́й на́йде на Тя і бисть Предводи́тель Твой, єгда́ по тріє́х днех путі́ дости́гла єси́ гра́да Ієрусали́ма, і я́ко Киво́т Бо́жий ведо́ма била́ єси́ ко хра́му Госпо́дню, Богоро́дице Ді́во, да сбу́деться сло́во псало́мськоє, глаго́лющеє: «Ви́діна би́ша ше́ствія Твоя́, Бо́же, ше́ствія Бо́га моєго́ Царя́, і́же во Святі́м». І та́ко за премно́гую небе́сную чистоту́ Твою́, храм Бо́жий удосто́їлася єси́ би́ти, іді́же Дух Святи́й хотя́ше жи́ти да соді́лаєть Тя Жили́ще Своє́, селе́ніє небе́сноє, да па́ки іспо́лниться на Тебі́ друго́є Писа́ніє, глаго́лющеє: «Освяти́л єси́ Селе́ніє Своє́, Ви́шній, Свят храм Твой, Го́споди, ди́вен в пра́вді», сего́ ра́ди да воспої́м всі о Тебі́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще лі́ти три, Пресвята́я Ді́во, приведе́на била́ єси́ ко хра́му, святи́я же роди́телі Твоя́, ов от єди́ния страни́, о́ва же от други́я, взе́мше за ру́ки Тя, Богодарова́нную їм Дщер свою́, кро́тко і че́стно ведо́ша Тя ко хра́му, глаго́люще: «Начні́те Ді́ви свіщено́сния, предше́ствуйте пред Богоотрокови́цей». Все же мно́жество сро́дник і сосі́дов зна́ємих і свяще́нник с весе́лієм послі́доваху, свіщи́ в рука́х держа́ще, і окружа́юще Тя, я́коже зві́зди луну́ сві́тлую. Стече́ся же і весь Ієрусали́м, но́воє сіє́ превожде́ніє со удивле́нієм зря́ще, Отрокови́цю трехле́тнюю толи́кою сла́вою облача́ємую і такови́м светоноше́нієм почита́ємую і воспі́ша Тебі́ такова́я:","Ра́дуйся, трилі́тствующая ті́лом, не́ба небесі́ ши́ршая.","Ра́дуйся, многолі́тствующая ду́хом, го́рніх сил преви́сшая.","Ра́дуйся, А́гнице Непоро́чная, ді́вство Своє́ Бо́гу в же́ртву чи́сту прине́сшая.","Ра́дуйся, Голуби́це Нескве́рная, чистото́ю Своє́ю А́нгели удиви́вшая.","Ра́дуйся, с ді́вственними ли́ки ко Го́споду приведе́нная.","Ра́дуйся, с горя́щими світи́льники ко хра́му препровожде́нная.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній сумни́тельних, Первосвяще́нник Заха́рія см'яте́ся, зря Твоє́, Пречи́стая, ко хра́му Госпо́дню со сла́вою мно́гою превожде́ніє і ко врато́м на восто́ки зря́щим затворе́нним су́щим приближе́ніє. Єгда́ же воспом'яну́ Ієзекії́ля предрече́ніє дре́внєє: «Врата́ сія́ затворе́на бу́дуть і нікто́же про́йдеть сквозі́ їх, я́ко Госпо́дь Бог про́йдеть і́ми, і бу́дуть заключе́на» іспо́лнися Ду́ха Свята́го і открове́ніє сви́ше получи́в, да отве́рзеть приведе́нной Богоотрокови́це заключе́нная врата́, возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["«Сли́ши, Дщи, і виждь, і приклони́ у́хо Твоє́, і забу́ди лю́ди Твоя́ і дом отця́ Твоєго́, і возжела́єть Цар добро́ти Твоєя́». Та́ко глаго́лаху Тебі́, Пресвята́я Ді́во, роди́телі Твоя́, єгда́ приведе́на била́ єси́ ко хра́му Госпо́дню. Свяще́нници же, слу́жби соверша́ющия, ви́діша прише́ствіє Твоє́, ізидо́ша во срі́теніє сла́вному введе́нію Твоєму́, і с пі́сньми прия́ша Тя, я́ко Ма́тер іму́щую би́ти Архієре́я Вели́каго Небеса́ Проше́дшаго, глаго́люще:","Ра́дуйся, благоволе́нія Бо́жия предображе́ніє, проро́ки предвозвіще́нная.","Ра́дуйся, челові́ков спасе́нія пропові́даніє, нам ни́ні явле́нная.","Ра́дуйся, А́нгели Небе́сними со сла́вою провожда́ємая.","Ра́дуйся, ієре́ї Бо́жиїми с ра́достію срета́ємая.","Ра́дуйся, дом Отця́ Твоєго́ і лю́ди Твоя́ оста́вльшая.","Ра́дуйся, дом Бо́жий явле́нієм Свої́м освяти́вшая.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 5","ps":["Боговмісти́мий храм би́вши, Богоро́дице Ді́во, ко хра́му зако́нному со сла́вою мно́гою провожде́на била́ єси́, да іспо́лниться Агге́я проро́ка предрече́ніє: «І іспо́лню храм сей сла́вою, зане́ ве́лія бу́деть сла́ва хра́ма сего́ послі́дняго па́че пе́рваго, глаго́леть Госпо́дь Вседержи́тель». Ма́ти же Твоя́ приведе́ Тя к церко́вному вхо́ду, глаго́лющи: Гряди́, Дщи, ко І́же Тебе́ мні Дарова́вшему. Гряди́, Киво́те освяще́нія, к благоутро́бному Влади́ці. Гряди́, Две́ре Жи́зні, к Милосе́рдому Да́телю. Гряди́, Киво́те Сло́ва, ко хра́му Госпо́дню. Вни́ди в Це́рков Госпо́дню, ми́ра ра́досте і весе́ліє, да воспою́ о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши Ма́ти Твоя́, Богоро́дице Ді́во, ієре́ї Бо́жії із хра́ма ізше́дшия, і Святи́теля вели́каго Заха́рію, во срі́теніє Твоє́ гряду́щаго, рече́ к нему́: «Прийми́, Заха́ріє, Сінь Нескве́рную; прийми́, свяще́нниче, Непоро́чний Ковче́г; прийми́, проро́че, Кади́льницю невеще́ственнаго У́гля; прийми́, пра́ведниче, Кади́ло Духо́вноє. Прийми́, о проро́че, Бо́гом дарова́нную Дщер мою́ і введи́ в храм Зи́ждителя твоєго́, і введ, насади́ Ю в горі́ святи́ні, в гото́вом жили́ще Бо́жиєм, нічто́же іспиту́я, Тоя́ бо ра́ди бу́деть ізбавле́ніє», с не́ю же і ми возопіє́м Тебі́ такова́я:","Ра́дуйся, небе́сния ли́ки возвесели́вшая Твої́м вхожде́нієм.","Ра́дуйся, ієре́ї Бо́жії обра́довавшая Твої́м явле́нієм.","Ра́дуйся, Селе́ніє Небе́сноє, храм зако́нний па́че пе́рваго освяти́вшая благода́тію.","Ра́дуйся, Не́бо земно́є, Сама́ Себе́ в жили́ще Христо́во приугото́вившая чистото́ю.","Ра́дуйся, Неві́сто Бо́жия, я́ко вели́ко і ди́вно предше́ствіє Твоє́.","Ра́дуйся, Ді́во Чи́стая, я́ко стра́шно і пресла́вно во хра́мі обита́ніє Твоє́.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 6","ps":["Пропові́дник вхожде́нія Твоєго́ во храм Госпо́день пра́ведний Заха́рія удиви́ся зіло́, ви́дів Твоє́, Богоро́дице Ді́во, по лі́ствице церко́вній, п'ятна́десять сте́пень іму́щей, ди́вноє восхожде́ніє: поста́влена би́вши роди́телі Твої́ми на пе́рвом сте́пені, Ти а́біє Сама́ о себі́ потекла́ єси́ на про́чія сте́пені ско́ро зіло́, ники́мже поддержи́мая, і на височа́йший сте́пень восте́кши, ста́ла єси́, укріпля́єма неви́димою си́лою Бо́жиєю; святи́й же Заха́рія, ви́дів сіє́, об'я́т бі Ду́хом Бо́жиїм і рече́ ма́тері Твоє́й: «Благослове́н Плод чре́ва твоєго́, о же́но, пресла́вно приведе́ніє твоє́: Жи́зні бо Ма́тер і́стинную вво́диши, ка́ко храм вмісти́ть Ю?» Ті́мже благодаря́ще Бо́га, воспі́л Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ра́дость ве́лія всім хра́му зако́нному предстоя́щим, єгда́ Святи́тель вели́кий Заха́рія, Ду́ха Свята́го іспо́лненний, прия́т Тя, о Богома́ти, пред врати́ церко́вними, рука́ма свої́ма держа́, і вводя́ Тя во Свята́я, віща́ше к Тебі́ та́ко: О, Отрокови́ці Нескве́рная! О, Ді́во Небла́зная! О, Діви́ці Прекра́сная! О, жена́м украше́ніє! О, дще́рям удобре́ніє! Ти Благослове́нная в жена́х, Ти препросла́вленная чистото́ю, Ти запечатле́нная ді́вством, Ти Ада́мови кля́тви разріше́ніє. Гряди́, ісполне́ніє моєго́ проро́чества. Гряди́, соверше́ніє обітова́ній Госпо́дніх. Гряди́, печа́те Того́ заві́та. Гряди́, із'явле́ніє Того́ сові́та. Гряди́, ісполне́ніє Того́ та́їнств. Гряди́, проро́ков всіх Зерца́ло. Гряди́, обновле́ніє обветша́вших. Гряди́, Сві́те во тьмі лежа́щих. Гряди́, дарова́ніє нові́йшеє і Боже́ственнійшеє. Вни́ди в ра́дость в Це́рков Го́спода Твоєго́, ни́ні у́бо в до́льнюю, челові́ки входну́ю, не по мно́зі же в го́рнюю і непристу́пную». С ним же і ми воспоє́м Тебі́ си́це:","Ра́дуйся, Лі́ствице одушевле́нная, ко хра́му Госпо́дню по степе́нем лі́ствиці висо́кия восте́кшая.","Ра́дуйся, Две́ре, непроходи́мая челові́чеськими по́мисли, во две́рі хра́ма воше́дшая.","Ра́дуйся, я́ко по степе́нем доброді́телей возви́силася єси́ до висоти́ Небе́снаго Алтаря́.","Ра́дуйся, я́ко на крилеіх ді́вства і чистоти́ дости́гла єси́ Гра́да Вели́каго Царя́.","Ра́дуйся, Дом Бо́жий на версі́ го́ри дости́гшая.","Ра́дуйся, врата́ заключе́нная проше́дшая.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отверза́ющая."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь спасти́ род челові́ч, ізбра́ Тебе́ єди́ну в Ма́тер Себе́ і введе́ Тя во святи́й храм Свой, да та́мо в уєдине́нії і тишині́ глубо́цій дале́че от собла́знов ми́ра сего́ воспита́єшися во святи́ні Госпо́дней в Бо́жиє жили́ще. Ти же, ігра́ющи і зіло́ ра́дующися, я́ко в черто́зі, в дому́ Госпо́дні ше́ствовала єси́, а́ще і ма́ла била́ єси́ во́зрастом, тріє́х літ су́щи, оба́че соверше́нна била́ єси́ благода́тію, я́ко предуве́денная і предизбра́нная от Бо́га пре́жде сложе́нія ми́ра, і та́мо воспіва́ла єси́ Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая, ди́вная і ужа́сная сотвори́ о Тебі́ Госпо́дь, Богоблагода́тная, єгда́ Святи́тель вели́кий Заха́рія, вні себі́ бив, по та́їнственному открове́нію Бо́жию введе́ Тя па́че зако́на за втору́ю заві́су, во вну́треннюю ски́нію, глаго́лемую Свята́я Святи́х, іді́же не то́чію же́нському по́лу, но ніже́ свяще́нником подоба́ше входи́ти, но то́чію єди́ному Архієре́ю єди́ною в лі́то; подоба́ше бо Тебі́, я́ко Одушевле́нному Бо́жию Киво́ту, єще́ пре́жде зача́тія па́че вся́каго єстества́ преіспо́лненней чистоти́, ста́ти на мі́сті зако́ннаго Киво́та Бо́жия, Ієремі́єм сокрове́ннаго, да іспо́лниться па́ки сла́вою храм Госпо́день. Сіє́ пречу́дноє вхожде́ніє Твоє́ зря́ще, вопіє́м Тебі́ такова́я:","Ра́дуйся, во Свята́я Святи́х, я́ко на не́бо земно́є взоше́дшая.","Ра́дуйся, Свята́я Святи́х бо́льшая, я́ко к Престо́лу Бо́жию предста́вшая.","Ра́дуйся, А́нгели удиви́вшая, ка́ко во Свята́я Святи́х пресла́вно взошла́ єси́.","Ра́дуйся, челові́ки возвесели́вшая, я́ко храм Госпо́день сла́вою іспо́лнила єси́.","Ра́дуйся, Черто́же Красні́йшій, в не́мже жили́ще Святи́я Тро́йці содіва́єть Пресу́щественний.","Ра́дуйся, Престо́ле Святі́йший, на не́мже гото́виться сі́сти пло́тію Пребоже́ственний.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 8","ps":["Стра́нно Твоє́ зача́тіє і рождество́. Стра́нен о́браз возраста́нія Твоєго́. Стра́нно і пресла́вно, Богоневі́сто, Твоє́ є́же внутр Святи́лища Введе́ніє, і на моли́тві пребива́ніє при́сноє, і вся, я́же суть Твоя́: от у́тра бо да́же до тре́тьяго ча́са стоя́ла єси́ по вся дні на моли́тві внутр Святи́лища, посе́м с про́чими ді́ви в притво́рі в рукоді́лії упражня́лася єси́, от дев'я́таго же ча́са па́ки в хра́мі во Свята́я Святи́х предстоя́ла єси́ Бо́гу на моли́тві, в Богоми́слії і в поуче́нії Боже́ственних Писа́ній, до́ндеже А́нгел Госпо́день я́вльшеся препита́ти Тя небе́сною пи́щею. Таково́му равноа́нгельському житію́ Твоєму́ чудя́щеся, вопіє́м та́ко благоволи́вшему о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всю Тебі́ освяти́ Всесвяти́й Дух, внутр хра́ма пребива́ющую, Пресвята́я Ді́во. Сего́ ра́ди да не косне́ться Ті нічто́ от земни́я скве́рни, небе́сною і нетлі́нною пита́єма била́ єси́ пи́щею, подава́ємую же земну́ю пи́щу раздава́ла єси́ ни́щим і стра́нним. І та́ко приє́млющи по вся дні от А́нгела хліб небе́сний, преуспева́ла єси́ му́дростію і благода́тію, ті́лом і ду́хом ра́дующися, да невмісти́моє Сло́во Бо́жиє непоро́чно вмести́ши. І бі Арха́нгел Гавриї́л неотсту́пний храни́тель ді́вственния чистоти́ Твоєя́ і со іни́ми А́нгели Бо́жиїми ча́сто Тебі́ явля́шеся, укріпля́ше Тя в по́двизіх духо́вних, в моли́тві і по́сте, в кро́тости і смире́нії і любе́зно бесі́доваше с Тобо́ю, Преві́чний Сові́т Ви́шняго о Тебі́ раскрива́я, да бу́деши гото́ва к прия́тію Бо́жию, вопія́ к Тебі́ такова́я:","Ра́дуйся, неізрече́нних тайн Бо́жиїх преди́вноє ісполне́ніє.","Ра́дуйся, Предві́чнаго Сові́та Ви́шняго всечу́дноє соверше́ніє.","Ра́дуйся, небе́сним хлі́бом от А́нгела неізрече́нно воспита́нная.","Ра́дуйся, благода́тію Бо́жієй с небесе́ несказа́нно укрепле́нная.","Ра́дуйся, Ю́же во Свято́є Святи́х сріта́ють многоочи́тії Херуви́ми.","Ра́дуйся, с Не́юже непреста́нно собесі́дують шестокрила́тії Серафи́ми.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся о превели́цей красоті́ ді́вства Твоєго́, Всесвята́я Ді́во. Ти бо со А́нгели во Свята́я Святи́х пребива́ющи, Сама́ вожделі́ла єси́ в чистоті́ А́нгельськой і неврежде́нном Своє́м ді́встві ві́чно жи́ти. Сего́ ра́ди пе́рвая в ми́рі дала́ єси́ обі́т ді́вства і обручи́ла єси́ Себ'я́ на при́сноє служе́ніє Бо́гу в чистоті́ діви́честій, і уневі́стилася єси́ Єму́, да Ду́хом Святи́м приугото́вана бу́деши в чи́стоє і нетлі́нноє Селе́ніє Сло́ву Бо́жию, пою́щи Єму́ день і нощ: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї богоглаго́ливия не мо́гуть глаго́лати, во є́же ізрещи́ та́йну житія́ Твоєго́ в чистоті́ ді́вства во хра́мі. Богоро́дице. Расту́щей Тебі́ лі́ти, Ти бо день от дне укрепля́лася єси́ ду́хом і подви́жнейшеє растя́ше житіє́ Твоє́: с трудолю́бієм бо умножа́ла єси́ моли́тву, іду́щи от си́ли в си́лу, до́ндеже Си́ла Ви́шняго осіни́ Тя. Растя́ху же в Тебі́ і да́ри Свята́го Ду́ха: єгда́ бо в бо́льшій приходи́ла єси́ во́зраст, бо́ліє упражня́лася єси́ в моли́тві, не́же в рукоді́лії, но́щі же ці́лия в моли́тві со А́нгели проводи́ла єси́ за второ́ю заві́сою; сего́ ра́ди со удивле́нієм зове́м Тебі́ такова́я:","Ра́дуйся, Свята́я Святи́х Святі́йшая Ді́во, в же́ртву чи́стую ді́вство Своє́ Бо́гу прине́сшая.","Ра́дуйся, чисті́йшая Свята́го Ду́ха Пала́то, в Жили́ще Христо́во Себі́ воспита́вшая.","Ра́дуйся, Две́рі Небе́сная, в хра́мі, я́ко на небесі́ преби́вшая.","Ра́дуйся, Горо́ Усире́нная Ду́хом, во Святи́лище всі́ми доброді́тельми процві́тшая.","Ра́дуйся, Ю́же А́нгели Бо́жії дорино́сять ві́рно.","Ра́дуйся, Ю́же всі ві́рнії благода́рственно славосло́в'ять при́сно.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 10","ps":["Спасе́нія на́шего весна́ ра́достная возсія́ всім конце́м землі́ пресла́внаго Твоєго́ ра́ди Введе́нія во храм Богоро́дице. Писа́ніє мимоі́де і оскуді́ зако́н, я́ко же сінь, вше́дшей же Тебі́ во храм Бо́жий, Ді́во Чи́стая, лучі́ благода́ті всім возсія́ша, просвіща́юще ду́ші і помишле́нія всіх во тьмі неві́дінія сідя́щих. Сего́ ра́ди да ра́дується не́бо і земля́, не́бо У́мноє Гряду́щеє зря́ще і А́нгелов чи́ни і челові́ков мно́жество да вопію́ть: в храм вво́диться ра́дость і ізбавле́ніє всім вопію́щим: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам в чистоті́ ді́вства во оби́теліх подвиза́ющимся, Богоро́дице Ді́во, поне́же, да́вши во хра́мі обі́т ді́вства Бо́гу, Ти ди́вно сохрани́ла єси́ єго́ і дости́гши літ двуна́десяти, єгда́ про́чія ді́ви, при хра́мі живу́щия, сочетова́хуся супру́жества по оби́чаю подзако́нному, Ти откри́ла єси́ та́йну обітова́нія Твоєго́, чесо́ ра́ди отдана́ била́ єси́ на хране́ніє ді́вства ста́рцю Іо́сифу, Бо́гом ука́занному возлете́нієм голуби́ці от же́зла єго́. І та́ко во всеці́лую добро́ту ді́вства обле́кшися, я́ко Неві́ста Бо́жия, Ти всім подає́ши в чистоті́ служе́ніє своє́ соверша́ющим дарова́нія кро́ткаго Твоєго́ і молчали́ваго ду́ха, Твою́ тишину́, смире́ніє і неізглаго́ланную чистоту́, да всі Тобо́ю спаса́ємії со благодаре́нієм воспою́ть Тебі́ си́це:","Ра́дуйся, в моли́твах во хра́мі Госпо́днем неусипа́ющая, не даждь нам во гріхі́ усну́ти.","Ра́дуйся, в безмо́лвії во Свята́я Святи́х пребива́ющая, сподо́би нас в тишині́ живо́тній пожи́ти.","Ра́дуйся, со А́нгели во Святи́лище при́сно собесі́днице, научи́ нас безпло́тних глаго́лам внима́ти.","Ра́дуйся, с чи́стими ді́ви при хра́мі сожи́тельнице, помози́ нам в ді́встві і чистоті́ житіє́ своє́ соверша́ти.","Ра́дуйся, Одушевле́нний Храм Бо́га Жива́го, хра́ми Ду́ха Свята́го нас сотвори́.","Ра́дуйся, Черто́же Вседраги́й вся́каго доброде́ланія, во всіх Да́рах Ду́ха Свята́го нас утверди́.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 11","ps":["Пі́нія всеумиле́нния от неземни́х мусики́й приноша́ху Тебі́, Пресвята́я Ді́во, Святі́ї А́нгели, деви́чеському Введе́нію Твоєму́ служа́ще і весе́ліє творя́ше і небе́снії припева́ху гла́си, Тебі́ на слу́жбу Бо́жию входя́щей, с ни́миже на землі́ от пі́сней челові́чеських ді́вственнії ли́ци Го́сподеві пою́ть, псало́мськи воспіва́юще і чту́ще Тебе́ Ма́тер Єго́. С ни́ми же і нас сподо́би чи́стими уми́ і нескве́рними усти́ воспі́ти о честні́м Введе́нії Твоє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная нам возсія́ла єси́ свіща́, Богоро́дице, во храм Госпо́день прише́дши, ра́дость велича́йшую та́мо світя́щи і на моли́тві во Свята́я Святи́х горя́щи, отону́доже і облиста́ла єси́ небе́сною чистото́ю всему́ ми́ру, во тьмі гріхо́вній пребива́ющему, да і ми со свещено́сними ді́вами, Тя ко хра́му Госпо́дню сві́тло со сла́вою ді́вственною проводи́вшими, узря́щем Тя ра́достно, во сві́ті чистоти́ душе́вния і тіле́сния сія́ющу, і воспоє́м Тебі́ похвали́ такови́я:","Ра́дуйся, Свіще́ Неугаси́мая, во Святи́лище возже́нная, свещено́сними ді́вами провожда́ємая.","Ра́дуйся, Заре́ Незаходи́мая, весь мир облиста́вшая, сві́тлими А́нгели во хра́мі срета́ємая.","Ра́дуйся, Світи́льниче Небе́сния сла́ви, Сві́те неле́стний во хра́мі всім возсія́вший.","Ра́дуйся, Черто́же Бо́жия благода́ті, Хлі́бе слове́сний із руки́ А́нгела прия́вший.","Ра́дуйся, Ма́ти Сві́та гряду́щая би́ти, сві́том чистоти́ Твоєя́ всіх просвіща́ющая.","Ра́дуйся, Ма́ти Сві́та Ти́хаго Сія́ніє, теплото́ю моли́тв Твої́х всіх утіша́ющая.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия но́вий і одушевле́нний Киво́т су́щи, Богоро́дице Ді́во, в не́мже вмі́сто ма́нни чу́вственния і веще́ственних скрижа́лей вмеща́ються невеще́ственния неістощи́мия дарова́нія Бо́жия, досто́йно введе́на била́ єси́ во Свята́я Святи́х, я́ко вмісти́ти іму́щая пло́тськи Безнача́льноє Сло́во Бо́жиє, іді́же Си́ли Небе́сния служа́ху Тебі́, стра́шнії Херуви́ми і пламене́ющії любо́вію Серафи́ми осіни́ша Тя крили́ свої́ми, Престо́ли і Госпо́дствія, Нача́ла, Си́ли і Вла́сті припадо́ша к Тебі́ со Арха́нгели і А́нгели, вопію́ще о Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пречестно́є Твоє́ во храм Госпо́день Введе́ніє, хва́лим всі Твоє́ пречу́дноє во Свята́я Святи́х со А́нгели спребива́ніє і небе́сним хлі́бом пита́ніє, поклоня́ємся равноа́нгельськой ді́вственной чистоті́ Твоє́й, Богоро́дице, і ві́руєм, я́ко пришла́ єси́ от земна́го до́ма в Дом Бо́жий, я́ко же́ртва чи́стая, я́ко дар освяще́н на обруче́ніє ді́вства Твоєго́ Жениху́ Небе́сному, да угото́ваєшися досто́йно к нетлі́нному і чи́стому Рождеству́ Христо́ву в Бо́жиє Жили́ще. Ті́мже та́ко ві́рующе, возглаго́лем Тебі́ си́це:","Ра́дуйся, храм Госпо́день Пречи́стих ног Твої́х стопа́ми освяти́вшая.","Ра́дуйся, жили́ще Бо́жиє от оскверне́нія грі́шних отми́вшая.","Ра́дуйся, во Свято́м хра́мі, я́ко на небесі́, поклоне́ніє Го́рніх Сил приє́мшая.","Ра́дуйся, во Свята́я Святи́х, я́ко на небесі́, Престо́лу Бо́жию предста́вшая.","Ра́дуйся, Прекра́сная Діви́це, ізше́ствієм Твої́м із до́му о́тчаго во храм мир всему́ ми́ру Прине́сшая.","Ра́дуйся, Но́вая Голуби́це, вхожде́нієм во храм пра́ведним в преіспо́дней наде́жду вперви́є дарова́вшая.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Богоотрокови́це, Прише́дшая во храм Госпо́день воспита́тися во Свята́я Святи́х в Бо́жиє Жили́ще, ни́нішнєє на́ше о всечестні́м Введе́нії Твоє́м приє́мши приноше́нія, ізба́ви нас от вся́кия ско́рби і напа́сти і іскуше́ній вра́жеських, очи́сти ни от вся́кия скве́рни пло́ті і ду́ха і сохрани́ нас до сконча́нія на́шего в цілому́дрії і чистоті́, да освяще́ннії Тобо́ю досто́йни бу́дем введе́нія во оби́телі ра́йськия с му́дрими ді́вами, с ни́миже да воспоє́м о Тебі́ Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов ли́ки от небе́сних висо́т стеко́шася ви́діти пресла́вноє Твоє́, о Богома́ти, во храм Госпо́день Введе́ніє і вку́пі с земни́м ли́ком чи́стих дів неви́димий лик безпло́тних умо́в с весе́лієм ідя́ше, Тя, Пречи́стая Ді́во, провожда́юще і я́ко сосу́д ізбра́нний Бо́гу повелі́нієм Госпо́днім окружа́юще, і я́ко Госпоже́ своє́й служа́ще, а́ще не ви́дісте та́йни Твоєя́ си́лу, ви́дяще же Тя небе́сния чистоти́ неізрече́нно іспо́лнену, і вся би́вшая о Тебі́ зря́ще, ужаса́хуся і со стра́хом мно́гим воспі́ша Тебі́ та́ко:","Ра́дуйся, прера́дованная Ді́во, Ма́ти Царе́ва іму́щая би́ти.","Ра́дуйся, предпочте́нная Цари́це, в храм Царе́в гряду́щая жи́ти.","Ра́дуйся, Бо́га Отця́ Дщер ізбра́нная і превознесе́нная.","Ра́дуйся, Бо́га Си́на Ма́тер от ві́ка предрече́нная.","Ра́дуйся, Бо́гу Ду́ху Всесвято́му Неві́сто неіскусобра́чная.","Ра́дуйся, всея́ Тва́рі ви́димия і неви́димия Влади́чиця превожделе́нная.","Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Кондак 1","ps":["Ізбра́нній Предві́чним Царе́м Богоотрокови́це Марі́ї, А́нгелов і челові́ков Цари́це, прише́дшей іногда́ в храм Госпо́день во Свята́я Святи́х, на обруче́ніє ді́вства Своєго́ Жениху́ Небе́сному воспита́тися в Бо́жиє Жили́ще, досто́йноє поклоне́ніє усе́рдно Тебі́ прино́сим, Ти же я́ко многомо́щная Засту́пниця на́ша, от вся́ких нас бід і скорбе́й свободи́, да с любо́вію і умиле́нієм Тебі́ вопіє́м: Ра́дуйся, Богоізбра́нная Отрокови́це, вхожде́нієм во храм две́рі ра́йськія нам отве́рзшая."]},{"h":"Молитва Введенню в храм Пресвятої Богородиці","ps":["О, Пресвята́я Ді́во, Цари́ця Небесі́ і землі́, пре́жде вік ізбра́нная Неві́сто Бо́жія, в послі́дняя же времена́ прише́дшая в храм зако́нний на обруче́ніє Жениху́ Небе́сному! Ти оста́вила єси́ лю́ди Твоя́ і дом отця́ Твоєго́, во є́же принести́ Себі́ в же́ртву чи́стую і непоро́чную Бо́гові, і пе́рвая дала́ єси́ обі́т всегда́шняго ді́вства. Да́руй же і нам соблюда́ти себі́ в цілому́дрії і чистоті́ і в стра́хі Бо́жиєм во вся дні живота́ на́шего, да бу́дем хра́ми Ду́ха Свята́го, найпа́че помози́ всім в подража́ніє Твоє́ во оби́теліх живу́щим і обручи́вшим себе́ на служе́ніє Бо́гові в чистоті́ ді́вства провожда́ти житіє́ своє́ і от ю́ности нести́ і́го Христо́во благо́є і ле́гкоє, свя́то храня́ще обі́ти своя́. Ти провела́ єси́, Всечи́стая, вся дні ю́ности Твоєя́ во хра́мі Госпо́днем вдали́ от собла́знов ми́ра сего́, в при́сном бо́дрствованії моли́твенном і во вся́ком воздержа́нії душе́вном же і тіле́снім, помози́ і нам отража́ти вся іскуше́нія вра́жеськия от пло́ті, ми́ра і дия́вола находя́щих на ни от ю́ности на́шея, і побіжда́ти о́ния моли́твою і посто́м. Ти во хра́мі Госпо́днем со А́нгели пребива́ющи, укра́силася єси́ всі́ми доброді́тельми, найпа́че же смире́нієм, чистото́ю і любо́вію і досто́йно воспита́лася єси́, да гото́ва бу́деши вмісти́ти пло́тію Невмісти́моє Сло́во Бо́жиє. Сподо́би же і нам, одержи́мим го́рдостію, невоздержа́нієм і лі́ностію, облещи́ся во вся́коє соверше́нство духо́вноє, да угото́ваєть ки́йждо от нас с по́мощію Твоє́ю одія́ніє бра́чноє душі́ своєя́ і єле́й доброде́ланія, да не на́зі і негото́ві яви́мся во срі́теніє Безсме́ртному Жениху́ на́шему і Си́ну Твоєму́, Христу́ Спаси́телю і Бо́гу на́шему, но да при́йметь ни с му́дрими ді́вами во оби́телі ра́йськия, іді́же со всі́ми святи́ми сподо́би нас ви́ну сла́вити і прославля́ти всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха і Твоє́ ми́лостивоє заступле́ніє всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва в празник Введення в храм Пресвятої Богородиці","ps":["Ко кому́ возопію́, Влади́чице, ко кому́ прибі́гну в го́ресті моє́й, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач мой усли́шить і воздиха́ніє при́йметь, а́ще не Ти, Пренепоро́чная, Наде́жда христия́н і Прибі́жище нам, грі́шним? Кто па́че Тебі́ в несча́стіях защити́ть? Усли́ши стена́ніє моє́ і приклони́ у́хо Твоє́ ко мні, Влади́чице і Ма́ти Бо́га моєго́! Не пре́зри і́щущаго Твоєя́ по́мощі і не отри́ни мене́ грі́шнаго, Цари́це Небе́сная! Научи́ мене́ ісполня́ти во́лю Си́на Твоєго́ і да́руй жела́ніє всегда́ слі́довати Єго́ святи́м за́повідям. За мой ро́пот в болі́зніх, труда́х і несча́стіях не отступи́ от мене́, но пребу́ди Ма́терію і Покрови́тельницею мене́ малоду́шнаго. Цари́це моя́ Преблага́я, Засту́пнице Усе́рдная! Твої́м хода́тайством прегріше́нія моя́ покри́й, от ви́димих і неви́димих враго́в защити́, сердца́ вражду́ющих про́тив мене́ см'ягчи́ і Христо́вою любо́вію согрі́й їх. Мні же немощно́му да́руй Твою́ всеси́льную по́мощ победи́та моя́ гріхо́вния приви́чки, даби́, очище́нний покая́нієм і после́дующею доброді́тельною жи́знію, в обще́нії со Свято́ю Це́рковію прове́л остальни́я дні земна́го стра́нствія. Предста́ни мні, Наде́ждо всіх христия́н, в час кончи́ни моєя́ і подкріпи́ мою́ ві́ру в сме́ртний тя́жкий час. Вознеси́ за мене́, многопрегреша́ющаго в жи́зні сей, Твоя́ всеси́льния моли́тви по отше́ствії моє́м, да оправда́єть мене́ Госпо́дь і соді́лаєть прича́стником Єго́ безконе́чних ра́достей. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь благоволе́нія Бо́жия предображе́ніє, / і челові́ков спасе́нія пропові́даніє, / в хра́мі Бо́жиї я́сно Ді́ва явля́ється, / і Христа́ всім предвозвіща́єть. / Той і ми велегла́сно возопії́м: // ра́дуйся, смотре́нія Зижди́телева ісполне́ніє."]},{"h":"Кондак, глас 4","ps":["Пречи́стий храм Спа́сов, / многоці́нний черто́г і Ді́ва, / свяще́нноє сокро́вище сла́ви Бо́жия, / днесь вво́диться в дом Госпо́день, благода́ть совводя́щи, / Я́же в Ду́сі Боже́ственном, / Ю́же воспіва́ють А́нгели Бо́жії: // Сія́ єсть селе́ніє Небе́сноє."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим є́же в храм Госпо́день // вхожде́ніє Твоє́."]},{"h":"Задостойник","ps":["А́нгели, вхожде́ніє Пречи́стия зря́ще, удиви́шася, / ка́ко Ді́ва вни́де во свята́я святи́х.","Я́ко одушевле́нному Бо́жию киво́ту, / да ніка́коже ко́снеться рука́ скве́рних, / устні́ же ві́рних Богоро́дице немо́лчно, / глас А́нгела воспіва́юще, с ра́достію да вопію́ть: / і́стинно ви́шши всіх єси́, Ді́во Чи́стая."]}],"notes":[]},{"u":"Акафіст Вознесінню Господньому","e":"Akathist to the Ascension of the Lord","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до, Тво́рче не́ба і землі́! Побіди́телю сме́рти похва́льноє прино́сим пі́ніє, я́ко по пресві́тлом Твоє́м із ме́ртвих Воскресе́нії на небеса́ со сла́вою возне́слся єси́ і с пречи́стою пло́тію Твоє́ю одесну́ю Бо́га і Отця́ возсі́л єси́, да і на́ше па́дшеє єстество́ совознесе́ши с Собо́ю, і от гріхо́в і от ві́чния сме́рти свободи́ши на ві́ки. Ми же Боже́ственноє Твоє́ Вознесе́ніє пра́зднующе со ученики́ Твої́ми от душі́ Тебі́ вопіє́м:","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов ли́ки сопредста́ша Тебі́, Царю́ всіх, на Єлео́нстій горі́, со стра́хом ви́дівше Тя на висоту́ небе́сную взе́млема с пло́тію, і прославля́ху вели́чіє человіколю́бія Твоєго́, пою́ще Тебі́ та́ко:","Ісу́се, Царю́ Сла́ви, взи́ди на небеса́ во воскликнове́нії во гла́сі тру́бні.","Ісу́се, Го́споди Сил, взи́ди на херуви́ми і возлети́ на крилу́ ві́треню.","Ісу́се, Преві́чний Бо́же, даждь гла́су Своєму́ глас си́ли, да тре́петна бу́деть ни́ні вся земля́.","Ісу́се, Преви́шній Сві́те, яви́ Си́лу Твою́ на о́блаціх, і огнь от Лиця́ Твоєго́ да воспла́мениться.","Ісу́се, Іскупи́телю тва́рі, угото́ві на небесі́х Престо́л Твой і Ца́рствію Твоєму́ да не бу́деть конця́.","Ісу́се, Тво́рче не́бу і землі́, сіди́ одесну́ю Отця́ Твоєго́, да бу́деть Бог вся́чеськая во всіх.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 2","ps":["Ви́дівше Апо́столи Тя із ме́ртвих возста́вша, Влади́ко Го́споди, єгда́ во днех чети́редесятих явля́л єси́ Себе́ їм, глаго́люще о та́йнах Ца́рствія Бо́жия, і восприя́вше от Тебе́ за́повідь от Ієрусали́ма не отлуча́тися, но ча́яти обітова́нія О́тча, до́ндеже облеку́ться си́лою сви́ше, соше́дшеся, пребива́ху єдиноду́шно вку́пі на моли́тві пою́ще Тебі́ єди́ними усти́ і єди́ним се́рдцем: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственнаго смотре́нія открива́я, Всеблаги́й Ісу́се, ізве́л єси́ ученики́ Твоя́ вон до Вифа́нії, і возве́д їх на го́ру Єлео́нськую, нача́ть к вели́кому Твоєго́ Вознесе́нія на не́бо та́їнству гото́вити, глаго́люще: Прибли́жися, о дру́зі Мої́, восхожде́нія вре́м'я, ше́дше у́бо научі́те вся язи́ки сло́ву, є́же сли́шасте от гла́са Моєго́, крестя́ще їх во і́м'я Отця́ і Си́на і Свята́го Ду́ха. Ті́ї же, єще́ земна́я му́дрствующе, вопроша́ху, не в сіє́ ли лі́то устро́їши Ца́рствіє Ізра́їлево. Оба́че Ти рекл єси́ їм: «ність ва́ше разумі́ти времена́ і лі́та, я́же Оте́ць положи́ во Своє́й вла́сті», да ви́ну гото́ві бу́дуть ко срі́тенію Своєго́ Жениха́ Небе́снаго, вопію́ще:","Ісу́се, Па́стирю До́брий, не разлуча́йся нікогда́же от нас, но пребу́ди с на́ми неотсту́пно.","Ісу́се, Учи́телю Благи́й, Свята́го Уті́шителя Ду́ха ниспосли́ нам, да пребу́деть с на́ми неізмі́нно.","Ісу́се, Просвіти́телю наш, просвіти́ ду́ші на́ші Твої́м к Небе́сному Отцю́ Вознесе́нієм.","Ісу́се, Спаси́телю наш, спаси́ нас от малоду́шія і бу́ри Твої́м заступле́нієм.","Ісу́се, Наста́вниче наш, сло́вом уст Твої́х наста́ви нас на Твоє́ служе́ніє.","Ісу́се, Помо́щниче наш, Ду́хом Твої́м Святи́м воспом'яни́ нам Твоє́ Открове́ніє.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 3","ps":["Си́лою сви́ше Апо́столи облещи́ хотя́й, Ісу́се, єгда́ на горі́ Єлео́нстій обітова́л єси́ їм Ду́ха Свята́го соше́ствіє. Ти повелі́л єси́ їм, да свиді́теліє Твої́ бу́дуть во Ієрусали́мі і во всей Іуде́ї, і да́же до послі́дніх землі́, глаго́люще: Прийді́те і вни́діте врати́ Мої́ми, угото́віте путь Мой і путь творі́те лю́дем Мої́м і ка́менія от путі́ размещі́те, вознесі́те зна́меніє на язи́ки, да всі ві́рнії воспою́ть с ва́ми: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я бе́здну милосе́рдія, Сладча́йший Ісу́се, ученики́ Твоя́ і жени́ Тебі́ после́дствовавшия і найпа́че Ро́ждшую Тя Ма́тер Твою́ ра́дости безчи́сленния іспо́лнил єси́ во Твоє́ Вознесе́ніє, єгда́ уже́ отступи́в от них, распросте́рл єси́ ру́ці Твої́ і благослови́л єси́, глаго́люще: «Се Аз с ва́ми єсьм во вся дні до сконча́нія ві́ка», ті́ї же, стра́хом іспо́лнені, прославля́ху Твоє́ ми́лостивноє снисхожде́ніє, глаго́люще:","Ісу́се, ми́лости Пода́телю, поми́ловати род челові́чеський на Єлео́н прише́дий.","Ісу́се, ско́рбних Увесели́телю, су́щия с Тобо́ю дру́ги Твоя́ уті́шити восхоті́вий.","Ісу́се, Наде́ждо безнаде́жних, Твої́м благослове́нієм при отше́ствії на не́бо нас от уни́нія сохрани́вий.","Ісу́се, Прибі́жище безприю́тних, Твої́м Вознесе́нієм восхо́д к Отцю́ Небе́сному і нам дарова́вий.","Ісу́се, Уті́шителю Благи́й, Уті́шителя Іна́го от Отця́ посла́ти нам обіща́вий.","Ісу́се, Па́стирю овця́м Вели́кий, Твоєму́ ві́рному ста́ду разсі́ятися не благоволи́вий.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 4","ps":["Бу́рю внутр недоумі́нія і печа́лі мно́гія іму́ще, Апо́столи рида́нієм слез іспо́лнишася, єгда́ уви́діша Тя, Христе́, на о́блаціх возноси́ма і пла́чуще глаго́лаху: Влади́ко, ка́ко ни́ні оставля́єши раби́ Твоя́, їх же за милосе́рдіє Твоє́ возлюби́л єси́, ка́мо і́деши, рука́ми содержа́й конці́? Ми же оста́вивше вся, Тебі́ Бо́гу послі́довахом, ра́дующеся, во ві́ки с Тобо́ю наде́жду іму́ще би́ти. Не оста́ви нас си́рих, я́коже обіща́лся єси́, не разлучи́ся от нас, Па́стирю наш До́брий, но посли́ нам Пресвята́го Ду́ха Твоєго́, наставля́юща, просвіща́юща і освяща́юща ду́ші на́ша, да благода́рственно воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша рида́нія учени́к Твої́х, Влади́ко Го́споди, о разлуче́нії скорб'я́щих, Ти соверше́ннійшеє благослове́ніє препода́л єси́ друго́м Твої́м, глаго́люще: не пла́чіте возлю́бленнії, і сі́тованіє все отри́ніте, поле́зно вам єсть, да Аз іду́ ко Отцю́ Моєму́, а́ще бо не іду́, Уті́шитель не при́йдеть. Вас ра́ди с небесе́ снидо́х і вас ра́ди па́ки восхожду́ на не́бо угото́вати мі́сто вам, не оста́влю бо ове́ць Мої́х, я́же собра́х, не забу́ду, ї́хже возлюби́х. Ті́ї же Боже́ственними словеси́ си́ми уті́шени би́вше, со умиле́нієм возопи́ша Тебе́:","Ісу́се Всеблаги́й, печа́ль і сле́зи на́ші на ра́дость преложиви́й, не лиши́ нас і ві́чния ра́дости во Ца́рствії Твоє́м.","Ісу́се Всеще́дрий, ра́достію іспо́лнивий нас во Твоє́м Вознесе́нії, сохрани́ дух наш в при́сном ра́дованії і во стра́нствії земно́м.","Ісу́се, я́коже ко́кош собра́вий птенці́ своя́, не попусти́ нам по сто́гнам ми́ра сего́ разлучи́тися.","Ісу́се, сою́зом любве́ нас на Ве́чері связа́вий, не даждь нам по ді́йству сатанину́, я́ко пшени́ці разсі́ятися.","Ісу́се, мир Твой нам в наслі́діє оста́вивий, соблюди́ нас в єдиноми́слії і любві́ Твоє́й.","Ісу́се, оби́телі мно́зі в раї́ устро́ївий, угото́ві мі́сто нам в Небе́сній Оби́телі Твоє́й.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 5","ps":["Боготе́чний о́блак пресві́тел зіло́ под'я́ть Тя, Жизнода́вче Го́споди, ученико́м зря́щим, єгда́ отступи́в от них, благослови́л єси́, і та́ко со сла́вою мно́гою, я́ко на крилеіх херуви́мських носи́мий, преди́вний восхо́д Твой ко Отцю́ Твоєму́ соверши́л єси́ на не́бо, є́же пре́жде непроходи́мо бисть от духо́в зло́би поднебе́сних і от князе́й вла́сті возду́шния, ни́ні же внутр Тебі́ прия́т, да от всей тва́рі ви́димия і неви́димия усли́шиши А́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше пресла́вноє Твоє́ с пло́тію на небеса́ Восхожде́ніє, Царю́ тва́рі, чи́ни А́нгельськия, до́лу су́щия, ужа́сшеся, глаго́лаху си́лам го́рнійшим: Возьмі́те врата́ ві́чная, я́ко гряде́ть Цар Сла́ви, отве́рзітеся небеса́ і ви небеса́ небе́с, восприймі́те Го́спода сил і поклоні́теся Єму́, вопію́ще:","Ісу́се, Сла́ви О́тчія сія́ніє, просвіти́ нас сві́том Лиця́ Твоєго́.","Ісу́се, го́рніх умо́в облиста́ніє, облиста́й нас в невече́рнім дні Ца́рствія Твоєго́.","Ісу́се, прише́дий я́ві во огні́ і бу́рі зі́льній, у́мноє Твоє́ не́бо сви́ше призови́.","Ісу́се, Ве́лій і Хва́льний зіло́ в горі́ Твоє́й Святі́й, пра́вду Твою́ в небесі́х возвісти́.","Ісу́се, возвели́чивий до небе́с ми́лость Твою́, яви́ сла́ву Твою́ по всей землі́.","Ісу́се, возше́дий на не́бо небесі́ на восто́кі, во вік Сло́во Твоє́ да пребу́деть на небесі́.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 6","ps":["Пропові́дници Боже́ственния Сла́ви, нача́льнейшия чи́ни А́нгельськия, су́щия на висоті́ небе́сній Госпо́дствія, Престо́ли, многоочи́тії Херуви́ми і шестокрила́тії Серафи́ми, отверзо́ша вку́пі вся висоти́ небе́сния, сріта́юще Тя, Влади́ко Вся́чеських, і ви́дяще Тя Возне́сшагося во пло́ті, друг ко дру́гу со удивле́нієм вопія́ху: Кто Сей, прише́дий із Єдо́ма, Держа́вний і Си́льний во бра́ні? Кто Сей, прише́дий от Васо́ра, є́же єсть от пло́ті? Почто́ червле́ни ри́зи Єго́, я́ко от омоче́нія кро́вію, віне́ць терно́вен нося́й? Сей єсть воі́стину Цар Сла́ви, А́гнець Бо́жий за спасе́ніє ми́ра закла́нний і воскреси́й, во пло́ті ни́ні гряди́й сі́сти одесну́ю Отця́, Єму́же ви́ну воспіва́ти бу́дем: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ Боже́ственною сла́вою, Ісу́се, єгда́ єстество́ челові́чеськоє, в него́же обле́кся єси́, ми́лостивно возне́сл єси́, Отцю́ спосади́л єси́, і обожи́л єси́ є. Ті́мже небе́снії безпло́тнії чи́нове, чудеси́ удивля́ющеся, ужаса́хуся, у́жасом і тре́петом содержи́мії, Твоє́ человіколю́біє велича́ху. С ни́миже і ми земні́ї Твоє́ нас ра́ди снисхожде́ніє і є́же от нас на небеса́ Вознесе́ніє славосло́в'яще, мо́лимся, глаго́люще:","Ісу́се, струя́ Сий жи́зні, Твої́м на не́бо Вознесе́нієм нам стра́нником землі́ путь жи́зні ві́чния во Ви́шній Ієрусали́м указа́вий.","Ісу́се, бе́здна Сий ми́лости, Твої́м одесну́ю Отця́ сіді́нієм плотсько́є на́ше восприя́тіє обожи́вий.","Ісу́се, взе́мий на ра́мо заблу́ждшеє єстество́ на́ше, возьми́ на Себі́ і моя́ тя́жкия прегріше́нія.","Ісу́се, возше́дий Пло́тію ко Безпло́тному Отцю́, возведи́ го́ре моя́ до́лу пони́кшия помишле́нія.","Ісу́се, от землі́ одесну́ю Бо́га і Отця́ на го́рняя возше́дий, да́руй мі десну́ю часть спаса́ємих ове́ць получи́ти.","Ісу́се, от Сіо́на благолі́піє красоти́ Твоєя́ яви́вий, сподо́би м'я прича́стником ві́чнаго блаже́нства Твоєго́ би́ти.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 7","ps":["Хотя́й вознести́ і просла́вити па́дшеє во Ада́мі єстество́ челові́чеськоє, Ти, я́ко втори́й Ада́м, возше́д на висоту́ небе́сную, угото́вал єси́ Престо́л Твой во вік ві́ка, і сел єси́ одесну́ю Бо́га і Отця́, Божество́м Твої́м ніка́коже разлучи́вийся Оте́чеських нідр. Прийді́те у́бо обнища́вшему нас ра́ди і возше́дшему одесну́ю Отця́ Ісу́су поклоні́мся, дади́м вели́чія Єму́, і воспоє́м із глубини́ душі́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і чи́стоє жи́тельство откри́л єси́, Го́споди, єгда́ с Пло́тію Твоє́ю возше́л єси́ на небеса́, да состарі́вшийся мно́гими гріха́ми мир обнови́ши возста́нієм Твої́м і на небеса́ Вознесе́нієм, показу́я нам я́вственно, я́коже Боже́ственний Па́вел глаго́леть, я́ко жи́тельство на́ше на небесі́х єсть. Сего́ ра́ди устрані́мся су́єтнаго ми́ра, ум на небеса́ преложи́ша, і вопію́ще Тебі́ такова́я:","Ісу́се, со А́нгели небе́сними Божество́м Свої́м на небеса́ возше́ствієм нас к небе́сному жи́тельству подвиза́тися призва́вий.","Ісу́се, с челові́ки — земни́й Пло́тію, Свої́м от землі́ отше́ствієм нас от земни́х пристра́стій отвраща́тися научи́вий.","Ісу́се, взиска́ти прише́дий заблу́ждшеє овча́, к незаблу́ждшим Твої́м овця́м возведи́ нас на небеса́.","Ісу́се, совокупи́ти соше́дий растоя́щаяся єстества́, я́же на землі́ соєдини́ небе́сним у Ви́шняго Отця́.","Ісу́се, во о́блаці ле́гці возше́дий на небеса́, сподо́би нас, земна́я оста́вльше, при́сно взира́ти на небе́сная врата́.","Ісу́се, сідя́й во сла́ві на Престо́лі Божества́, даждь нам, отве́рзше о́чі, от Зако́на разумі́ти Твоя́ чудеса́.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 8","ps":["Стра́нно і ди́вно Твоє́ Воскресе́ніє, стра́нно і стра́шно Твоє́, Жизнода́вче Христе́, є́же от святи́я гори́ Боже́ственноє Вознесе́ніє, непостижи́мо і па́че ума́ Твоє́ є́же одесну́ю Отця́ во Пло́ті сиді́ніє, о не́мже Дави́д ду́хом глаго́ла: «Рече́ Госпо́дь Го́сподеві Моєму́: сіди́ одесну́ю Мене́, до́ндеже положу́ враги́ Твої́ подно́жіє ног Твої́х». Сего́ ра́ди вся си́ли небе́сния, зря́ще Твоє́ на небеса́ возше́ствіє, воі́стину покори́шася под но́зі Твої́, пою́ще а́нгельськими язи́ки Херуви́мськую піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі во Ви́шніх, Сладча́йший Ісу́се, єгда́ во́лею нас ра́ди возне́слся єси́ со сла́вою на небеса́ і одесну́ю сел єси́ Бо́га і Отця́, но і ни́жніх ніка́коже отлучи́лся єси́, зане́ обітова́л єси́ пребива́ти неотсту́пно в Це́ркві і вопія́л єси́ лю́б'ящим Тя: «Аз єсьм с ва́ми і нікто́же на ви». Сіє́ ми́лостивоє обітова́ніє Твоє́ ви́ну по́мняще і храня́ще в се́рдці, с любо́вію вопіє́м Тебі́ такова́я:","Ісу́се, вся́ку власть на небесі́ і на землі́ по Вознесе́нії Твоє́м восприя́вий, восприйми́ нас в Твоє́ ві́чноє наслі́діє.","Ісу́се, вся́кия ра́дости ученики́ Твоя́ обітова́нієм Свята́го Ду́ха іспо́лнивий, іспо́лни нас Того́ благода́ті прише́ствієм.","Ісу́се, приклони́вий схожде́нієм небеса́, приклони́ пред вели́чієм сла́ви Твоєя́ до́лу прикло́ньшуюся мою́ горди́ню.","Ісу́се, превозне́сши Возше́ствієм Твої́м всю твар, превознеси́ го́ре мою́ ду́шу воспіва́ти со А́нгели Твою́ Святи́ню.","Ісу́се, Бо́жий Сло́ве, Сло́вом Твої́м небеса́ утверди́вий, утверди́ в се́рдці моє́м словеса́ Твоя́, я́ко да не согрішу́ Тебе́.","Ісу́се, Си́не Оте́чь, Ду́хом уст Твої́м всю си́лу Твою́ с небе́с яви́вий, обнови́ Дух пра́вий во утро́бі моє́й, я́ко да не оскверню́ себі́.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 9","ps":["Все єстество́ па́дшеє челові́чеськоє, до́лу пони́кшеє і гріхми́ істлі́вшеє, взял єси́ на ра́мо Своє́, Влади́ко Го́споди, новосотвори́вий Собо́ю, і преви́ше вся́каго нача́ла і вла́сті возве́л єси́ днесь і Бо́гу і Отцю́ приве́л єси́, і с Собо́ю спосади́л єси́ на Престо́лі Небе́снім, да освяти́ши є, і спросла́виши, і обожи́ши. Безпло́тнії же, удивля́ющеся, глаго́лаху: Кто Сей Кра́сний Муж, но не Челові́к то́чію, но вку́пі Бог і Челові́к, Єму́же да поє́м ви́ну: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї Боже́ственнії, ученици́ Твої́, Спа́се, Твоєму́ пресла́вному Восхожде́нію удивля́ющеся, на не́бо взира́ху, скорб'я́ще, Тебі́ возне́сшуся, і се два А́нгела предста́ста пред ни́ми во оде́жди білі́, і реко́ста їм во утіше́ніє: «Му́жіє Галиле́йстії, что стоїте́, зря́ще на не́бо? Сей Ісу́с, вознеси́йся от вас на не́бо, та́кожде при́йдеть, і́мже о́бразом ви́діста Єго́ іду́ща на не́бо». Сіє́ а́нгельськоє благові́стіє о Второ́м Прише́ствії Твоє́м, Го́споди, ученици́ Твої́ сли́шавше, в ра́достний тре́петь прийдо́ша, с ни́миже і ми ра́достно да воспоє́м Тебі́ такова́я:","Ісу́се, Вознеси́йся от нас во всей сла́ві Твоє́й, єй, гряди́ ско́ро со А́нгели святи́ми Твої́ми.","Ісу́се, імі́яй па́ки прийти́ сотвори́ти суд прав, єй, гряди́ со сла́вою во сві́тлості святи́х Твої́х.","Ісу́се, ве́лій і стра́шний зіло́ над всі́ми окре́стними, поми́луй і защити́ тогда́ вся кро́ткия землі́.","Ісу́се, прославля́ємий в Сові́ті Святи́х Твої́х, Сам нас спросла́ви во Ца́рствії Твоє́м на небесі́.","Ісу́се, проше́дий небеса́ Пло́тію, благоволи́ провести́ ду́шу по мита́рствам возду́шним і улицезре́ти Тя.","Ісу́се, Вознеси́йся на о́блаціх небе́сних, сподо́би нам с весе́лієм і со дерзнове́нієм в послі́дній день на о́блаціх усрі́сти Тя.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ су́щия с Тобо́ю ученики́, Христе́ Спа́се, і вся ве́рующия словесі́ їх ра́ди в Тя, і по Тебі́ после́довавшая, возше́л єси́ на небеса́, да угото́виши мі́сто їм, я́ко в дому́ Отця́ Твоєго́ оби́телі мно́гі суть, я́коже Сам рекл єси́ ко стра́сті гряди́й, глаго́ля: «А́ще угото́влю мі́сто вам, па́ки прийду́ і пойму́ ви к Себі́, да іді́же єсьм Аз, і ви бу́дете». Сего́ ра́ди сподо́би і нам, Го́споди, по сме́ртнім вознесе́нії на́шем обрісти́ хра́мину нерукотворе́ну, ві́чну на небесі́х, угото́ванную не от дре́ва, іли́ сі́на іли́ тро́стія пло́тських діл на́ших ра́ди, я́же во огні́ не устоя́ть, но от зла́та іли́ сребра́ іли́ ка́меней драги́х на Твоє́м основа́нії назда́нную, іді́же ви́ну бу́дем Тебе́ сла́вити і воспіва́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Предві́чний, Ісу́се Христе́, на небеса́ возше́дий с Пречи́стою Твоє́ю Пло́тію і всіх нас в небе́сноє на́ше Оте́чество призва́вий, возведи́ нас до́лу пове́рженних от мирськи́х пристра́стій і плотськи́х мудрова́ній к висоті́ небе́сній і да́руй нам єще́ во дні пло́ті на́шея чи́стим свиді́тельством со́вісти причасти́тися небе́сния жи́зні і ви́ну вкуша́ти в та́їнстві Боже́ственния Євхари́стії небе́сную пи́щу, да от чи́стаго се́рдця і ду́ха пра́ваго воспоє́м Тебі́ такова́я:","Ісу́се, Вели́кий Архієре́ю гряду́щих благ, во Вознесе́ніє Своє́ проше́дий небеса́ Пло́тію і возше́дий не в рукотворе́нний храм, но в са́моє не́бо, да Ли́ку Бо́жию от нас предста́неши.","Ісу́се, Небе́сний Архите́ктоне, ски́нію нерукотворе́нную на небесі́х сооруди́вий і єди́ною вше́дий во Свята́я Святи́х ко Отцю́ со Своє́ю Кро́вію, да ві́чноє іскупле́ніє соверши́ши.","Ісу́се, Непоро́чний А́гнче Бо́жий, єди́ною за гріхи́ ми́ра закла́нний, «во є́же вознести́ гріхи́ мно́гих», вознеси́ к Престо́лу Бо́жию моя́ о грісі́х приноше́нія.","Ісу́се, Но́ваго Заві́та Хода́таю, єди́ною на небеса́ ко Отцю́ возше́дий, во є́же откри́ти путь в Небе́сную Ски́нію, восприйми́ о нечистоті́ моє́й воздиха́нія.","Ісу́се, Возлю́бленний Женише́ наш, Светосія́нний Черто́г на небесі́ угото́вавий, угото́ві та́мо мі́сто Тебі́ Єди́ному служи́ти восхоте́вшим.","Ісу́се, До́брий Па́стирю Твої́х ове́ць, небе́сная па́стбища в раї́ Твоєму́ ста́ду проізрасти́вий, да́руй нам вінці́, Тебі́ Єди́ному послі́довати возжела́вшим.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приноша́ше Боже́ственному Вознесе́нію Твоєму́, Сло́ве, ро́ждшая Тя Всенепоро́чная Ма́ти Твоя́. Та бо во стра́сті Твоє́й ма́терськи па́че всіх болі́зноваше о Тебі́, сего́ ра́ди подоба́ше Той в прославле́ніє Пло́ті Твоєя́ премно́жайшия наслади́тися ра́дости, і с се́ю ра́достію вели́кою сни́де с Єлео́нськия гори́ со апо́столи, і возврати́шася всі во Ієрусали́м і взидо́ша в го́рницю, і бя́ху всі Апо́столи, терп'я́ще єдиноду́шно вку́пі в моли́тві, моле́нії і поще́нії с жена́ми і Марі́єю Ма́терію Ісу́совой, і с бра́тією Єго́, ча́юще Соше́ствія Свята́го Ду́ха, хва́ляще і благослов'я́ще Бо́га, і воспіва́юще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ ві́чний і нетлі́нний возсія́ всему́ ми́ру от Святи́я гори́ Єлео́нськия, іді́же стоя́сте пречи́стия но́зі Твої́, Христе́ Спа́се, єгда́ возне́слся єси́ со сла́вою на небеса́, зане́ проше́д небеса́ с Пло́тію, Ти отве́рзл єси́ врата́ небе́сная, паде́нієм Ада́мовим заключе́нная, і Сам сий Путь, І́стина і Живо́т, откри́л єси́ путь вся́кой пло́ті во оби́телі Отця́ Твоєго́ Небе́снаго, я́коже і предре́кл єси́ Твої́м ученико́м, глаго́ля: «Отсе́лі у́зріте не́бо отве́рсто і А́нгели Бо́жії восходя́щия і нисходя́щия над Си́на Челові́чеськаго». Сего́ ра́ди ві́дуще путь Твой, я́ко нікто́же при́йдеть ко Отцю́, то́кмо Тобо́ю, поє́м Тебі́ си́це:","Ісу́се, на о́блаціх сві́та возше́дий ко Отцю́, уга́сший світи́льник душі́ моєя́ просвіти́.","Ісу́се, во сві́тлостіх святи́х Твої́х вознеси́йся го́ре, животворя́щий огнь Твой в се́рдці моє́м воспламени́.","Ісу́се, па́че Со́лнця Возсія́вий на висоті́ небе́сній во Вознесе́нії Твоє́м, теплото́ю Ду́ха Твоєго́ хлад душі́ моєя́ разжени́.","Ісу́се, Світ от Сві́та Божества́ Твоєго́ возсія́вий ми́ру от Отця́, сві́том слове́с Твої́х в но́щі гріха́ нас спя́щих просвіти́.","Ісу́се, Со́лнце Пра́вди, імі́яй от кра́я небесе́ Восхо́д Твой і Срі́теніє Твоє́ — да́же до кра́я небесе́, во всю зе́млю віща́ніє Твоє́ возвіща́й нам всегда́.","Ісу́се, Невече́рній Сві́те, імі́яй па́ки в Прише́ствіє Твоє́ ісхо́д Твой, я́ко мо́лнію от восто́к і да́же до за́пад явле́ніє Твоє́, огне́м гні́ва Твоєго́ не попали́ нас тогда́.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 12","ps":["Благода́ть но́вую препода́л єси́, Сладча́йший Ісу́се, к соверше́нію святи́х і в созида́ніє Це́ркві Святи́я Твоєя́, єгда́ на небеса́ с Пречи́стою Твоє́ю Пло́тію возше́л єси́ і одесну́ю Бо́га і Отця́ сел єси́, я́коже пи́сано єсть: «Сше́дий пре́жде в до́льнійшия страни́ землі́ спасе́нія на́шего ра́ди», Ти ни́ні возше́л єси́ на висоту́ преви́ше всіх небе́с, да іспо́лниши вся́чеськая к соверше́нію святи́х, в созида́ніє Ті́ла Христо́ва, сего́ ра́ди пліни́л єси́ плін, і пода́л єси́ дая́нія челові́ком, до́ндеже дости́гнем всі в соєдине́ніє ві́ри і позна́нія Тебі́, Си́на Бо́жия, в му́жа соверше́нна, в мі́ру во́зраста ісполне́нія Твоєго́, да та́ко, спасе́ніє улучи́вше, благода́рственно воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ во́льноє на небеса́ со сла́вою Вознесе́ніє, поклоня́ємся Твоєму́, Влади́ко Христе́, одесну́ю Бо́га і Отця́ соседе́нію, сла́вим Твоє́ на небесі́ і на землі́ воцаре́ніє і ві́руєм со Апо́столи Твої́ми, я́ко воі́стину, і́мже о́бразом возше́л єси́ на не́бо, та́кожде па́ки приі́деши на о́блаціх со сла́вою і си́лою мно́гою. Тогда́ у́бо не посрами́ нас Тебі́ ві́рующих і та́ко вопію́щих:","Ісу́се, со Отце́м Твої́м на Престо́лі Божества́ при́сно сосідя́й, сподо́би побежда́ющим мир с по́мощію Твоє́ю сі́сти с Тобо́ю во Ца́рствії Твоє́м.","Ісу́се, со Святи́м Уті́шителем Ду́хом Твої́м ви́ну споклоня́ємий, не лиши́ нас по обітова́нію Твоєму́ Того́ Соше́ствія во служе́нії Твоє́м.","Ісу́се, с Херуви́ми і Серафи́ми і с ли́ки святи́х по Вознесе́нії Твоє́м на небесі́ спребива́яй, пода́ждь нам зді на моли́тву во І́м'я Твоє́ собра́нним прису́тствіє Твоє́ ощуща́ти.","Ісу́се, Святи́я хра́ми Твоя́ по отше́ствії Твоє́м на не́бо пра́во в Тя ві́рующим дарова́вий, помоги́ нам во хра́мі стоя́щим себе́ на небесе́ би́ти помишля́ти.","Ісу́се, Пречи́стую Ма́тер Твою́ со Апо́столи во Вознесе́ніє Твоє́ на моли́тву за весь мир по Себі́ оста́вивий, не оста́ви нас без предста́тельства Святи́х Твої́х.","Ісу́се, Це́рков, Неві́сту Твою́ на землі́ по Вознесе́нії Твоє́м до сконча́нія ві́ка оста́вивий, не лиши́ нас чад Тоя́ благода́тних даро́в Твої́х.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 13","ps":["О Пресла́дкий і Всеще́дрий Ісу́се, вознеси́йся от нас на не́бо і сіді́нієм одесну́ю Бо́га і Отця́ поми́ловавий і обожи́вий па́дшеє єстество́ на́ше! При́зри с висоти́ небе́сния на немощни́я і к землі́ пове́рженния раби́ Твоя́ і да́руй нам си́лу сви́ше побіжда́ти вся іскуше́нія от пло́ті, ми́ра і дия́вола находя́щия на ни, да го́рняя бу́дем му́дрствовати, а не земна́я. І сохрани́ нас от всіх враго́во ви́димих і неви́димих возстаю́щих на нас. По кончи́ні же земни́я жи́зні на́шея вознеси́ ду́ші на́ша в небе́сния оби́телі, іді́же со всі́ми святи́ми ви́ну воспіва́ти бу́дем: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов ли́ки сопредста́ша Тебі́, Царю́ всіх, на Єлео́нстій горі́, со стра́хом ви́дівше Тя на висоту́ небе́сную взе́млема с пло́тію, і прославля́ху вели́чіє человіколю́бія Твоєго́, пою́ще Тебі́ та́ко:","Ісу́се, Царю́ Сла́ви, взи́ди на небеса́ во воскликнове́нії во гла́сі тру́бні.","Ісу́се, Го́споди Сил, взи́ди на херуви́ми і возлети́ на крилу́ ві́треню.","Ісу́се, Преві́чний Бо́же, даждь гла́су Своєму́ глас си́ли, да тре́петна бу́деть ни́ні вся земля́.","Ісу́се, Преви́шній Сві́те, яви́ Си́лу Твою́ на о́блаціх, і огнь от Лиця́ Твоєго́ да воспла́мениться.","Ісу́се, Іскупи́телю тва́рі, угото́ві на небесі́х Престо́л Твой і Ца́рствію Твоєму́ да не бу́деть конця́.","Ісу́се, Тво́рче не́бу і землі́, сіди́ одесну́ю Отця́ Твоєго́, да бу́деть Бог вся́чеськая во всіх.","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до, Тво́рче не́ба і землі́! Побіди́телю сме́рти похва́льноє прино́сим пі́ніє, я́ко по пресві́тлом Твоє́м із ме́ртвих Воскресе́нії на небеса́ со сла́вою возне́слся єси́ і с пречи́стою пло́тію Твоє́ю одесну́ю Бо́га і Отця́ возсі́л єси́, да і на́ше па́дшеє єстество́ совознесе́ши с Собо́ю, і от гріхо́в і от ві́чния сме́рти свободи́ши на ві́ки. Ми же Боже́ственноє Твоє́ Вознесе́ніє пра́зднующе со ученики́ Твої́ми от душі́ Тебі́ вопіє́м:","Ісу́се, вознеси́йся от нас на не́бо, не оста́ви нас си́рих."]},{"h":"Молитва","ps":["Го́споди Ісу́се Христе́, Бо́же наш, соше́дий с небе́сних висо́т спасе́нія на́шего ра́ди і напита́вий нас духо́вною ра́достію во святи́я і пресві́тлия дні Воскресе́нія Твоєго́, і па́ки по соверше́нії земна́го служе́нія Твоєго́ вознеси́йся от нас на Не́бо со сла́вою і возсі́дий одесну́ю Бо́га і Отця́! В сей я́сний і всесві́тлий день Боже́ственнаго на Небеса́ восхожде́нія Твоєго́ земля́ пра́зднуєть і лику́єть, ра́дується і не́бо вознесе́нієм днесь Творця́ тва́рі, челові́ци славосло́в'ять непреста́нно, зря́ще заблу́ждшеє і па́дшеє єстество́ своє́ на ра́мо Твоє́, Спа́се, взе́млемоє і на небеса́ вознесе́нноє, А́нгели же веселя́ться, глаго́люще: Кто Сей, прише́дий во сла́ві, си́лен во бра́ні? Сей воі́стину Цар Сла́ви. Сподо́би і нам немощни́м, земна́я єще́ му́дрствующим і плотоуго́дія, твори́ти не престаю́щим, восхо́д Твой на Не́бо стра́шний помишля́ющи і пра́зднующе, плотська́я і жите́йськая отложи́ти попече́нія і со апо́столи твої́ми на Не́бо ни́ні взира́ти всім се́рдцем свої́м і всі́ми помишле́ньми свої́ми, помина́юще, я́ко та́мо на Небесі́ го́ре жи́тельство на́ше єсть, здісь же на землі́ ми то́чію стра́нники і прише́льці єсьми́, отше́дшия із до́ма О́тча в страну́ дале́че гріха́. Сего́ ра́ди усе́рдно про́сим Тя, пресла́вним Вознесе́нієм Твої́м, Го́споди, оживи́ на́шу со́вість, єя́же ну́жнійши нічто́же єсть в ми́рі, возведи́ нас із плі́на сего́ гріхо́внаго пло́ті і ми́ра і сотвори́ нас го́рняя му́дрствовати, а не земна́я, я́ко да не ктому́ себі́ угожда́ти бу́дем і жи́ти, но Тебі́ Го́споду і Бо́гу на́шему служи́ти бу́дем і порабо́таєм, до́ндеже отріши́вшеся от уз пло́ті і проше́дши невозбра́нно возду́шния мита́рства, дости́гнем Небе́сних оби́телей Твої́х, іді́же, ста́вше одесну́ю вели́чествія Твоєго́, со Арха́нгели і А́нгели і всі́ми святи́ми прославля́ти бу́дем всесвято́є і́м'я Твоє́ со Безнача́льним Твої́м Отце́м і Пресвяти́м і Єдиносу́щним і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Возне́слся єси́ во сла́ві, Христе́ Бо́же наш, / ра́дость сотвори́вий ученико́м, / обітова́нієм Свята́го Ду́ха, / ізвіще́нним їм би́вшим благослове́нієм, // я́ко Ти єси́ Син Бо́жий, Ізба́витель ми́ра."]},{"h":"Кондак, глас 6","ps":["Є́же о нас іспо́лнив смотре́ніє, / і я́же на землі́ соєдини́в Небе́сним, / возне́слся єси́ во сла́ві, Христе́ Бо́же наш, / ніка́коже отлуча́яся, / но пребива́я неотсту́пний, / і вопія́ лю́б'ящим Тя: // Аз єсьм с ва́ми і нікто́же на ви."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і почита́єм є́же на Небеса́ / с пречи́стою Твоє́ю Пло́тію // Боже́ственноє вознесе́ніє."]},{"h":"Задостойник, глас 5","ps":["Велича́й, душе́ моя́, // возне́сшагося от землі́ на не́бо Христа́ Жизнода́вця.","Тя, па́че ума́ і словесе́ Ма́тер Бо́жию, / в лі́то Безлі́тнаго неізрече́нно ро́ждшую, // ві́рнії, єдиному́дренно велича́єм."]}],"notes":[]},{"u":"Акафіст Воскресінню Христовому","e":"Akathist to the Resurrection of Christ","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Го́споди, ві́чния сме́рти побіди́телю, я́ко ізба́влься от духо́внаго умерщвле́нія, похва́льная воспису́ю Ті, возсозда́нний Тобо́ю, раб Твой. Ти же, я́ко імі́яй побі́ду над сме́ртію, от сме́рти гріхо́вния свободи́ нас, зову́щих:","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Ікос 1","ps":["А́нгели воскресе́ніє Твоє́, Христе́ Спа́се, непреста́нно пою́ть на небесі́х, і нас на землі́ сподо́би чи́стим се́рдцем воспі́ти Тебі́ си́це:","Ісу́се непостижи́мий, всіх ві́рних просвіща́яй, просвіти́ і м'я заблу́ждшаго.","Ісу́се воскре́сший, всіх Собо́ю оживля́яй, оживи́ м'я уме́ршаго гріхми́.","Ісу́се, на не́бо вознеси́йся і вознося́й на Тя наді́ющихся, совознеси́ і м'я до́лу прекло́ннаго.","Ісу́се, сідя́й одесну́ю Отця́ і разділя́яй сла́ву с лю́б'ящими Тя, не лиши́ м'я сла́ви Твоєя́.","Ісу́се, хотя́й прийти́ суди́ти живи́м і ме́ртвим, не осуди́ м'я по діло́м мої́м, но сотвори́ со мно́ю по ми́лості Твоє́й.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 2","ps":["Ви́дя па́дших челові́ков, Го́споди, Ти вочелові́чився совоскреси́л єси́ всіх і, воскреси́в, дарова́л вся потре́бная ко спасе́нію: си́це і мене́ умерщвле́ннаго гріхми́ оживи́, зову́ща: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум не постига́єть та́йни Боже́ственния, ка́ко Істо́чник жи́зні воскреса́єть, умерщвля́я смерть? Сего́ ра́ди, то́чію се́рдцем іспиту́юще ра́дость воскресе́нія і то́ю просвіща́ємі, со гла́сом весе́лія духо́внаго взива́єм Ті си́це:","Ісу́се, входя́й две́рем заключе́нним, вни́ди в дом душі́ моєя́.","Ісу́се, срі́тивий ученики́ на путі́, сря́щи і м'я на путі́ сей жи́зні.","Ісу́се, воспламени́вий сердця́ їх Твої́ми словеси́, воспламени́ і моє́ хла́дноє се́рдце.","Ісу́се, да́вий Себі́ позна́ти в преломле́нії хлі́ба, даждь мі позна́ти Тя в Боже́ственній Євхари́стії.","Ісу́се, обіща́вий Ду́ха Свята́го ученико́м Твої́м, ниспосли́ і мні Сего́ Ду́ха Уті́шителя от Отця́.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною воскреси́вий Ла́заря, воскреси́ і мене́ істлі́вшаго страстьми́ і многолі́тно лежа́щаго во гро́бі нераска́янія, да возста́в по гла́су Твоєму́, воспою́ спаса́ємий: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй власть над сме́ртію, із а́да ду́ші воззва́л єси́, Ісу́се. Воззови́ і мене́ із глубини́ гріхо́вния, да і аз, очи́стив чу́вствія, блиста́ющу Ті во сві́ті непристу́пнім, ра́достно воспою́ побі́дную піснь та́ко:","Ісу́се, сме́рти побіди́телю, побіди́ моя́ зли́я стра́сті.","Ісу́се, жи́зні пода́телю, даждь мі жизнь спаси́тельную.","Ісу́се, істо́чниче ра́дости, возвесели́ се́рдце моє́ во і́стині Твоє́й.","Ісу́се, п'ятію́ хлі́би п'ять ти́сящ наси́тивий, хлі́бом небе́сним напита́й м'я.","Ісу́се, наде́ждо па́дших, ізми́ м'я із ро́ва зол мої́х.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 4","ps":["Бу́ря страсте́й смуща́єть і потопля́єть м'я, но молю́ Тя Ісу́се, я́ко Петру́, простри́ мі ру́ку по́мощі і, си́лою воскресе́нія Твоєго́ воздви́гнув м'я, научи́ воспіва́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще ра́достную вість воскресе́нія Твоєго́, Ісу́се, небеса́ досто́йно веселя́ться, земля́ же ра́дується; і ми пра́зднующе ві́чноє весе́ліє, дерза́єм взива́ти Тебі́ си́це:","Ісу́се, сідя́й во сві́ті непристу́пнім, бу́ди досту́пен всім по милосе́рдію Твоєму́.","Ісу́се, люб'я́й созда́нія Твоя́, не забу́ди і мене́ послі́дняго.","Ісу́се, влеки́й к Себі́ сердца́, см'ягчи́ і моє́ окая́нноє се́рдце.","Ісу́се, вся блага́я проше́нія ісполня́яй, іспо́лни і моє́ проше́ніє, во є́же па́че всего́ люби́ти Тя.","Ісу́се, вся́ку ка́плю сле́зную приє́мляй, не отри́ни і мої́х моле́нії.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 5","ps":["Богоприя́тная жизнь істоча́ється от Тебе́, о Ісу́се Си́не Бо́га жива́го! Сего́ ра́ди молю́ Тя, да не погуби́ть м'я человікоуби́йця і да не загради́ть уста́ моя́, вопію́щая Тебі́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше ду́хом воскре́сшаго Го́спода, прийді́те, пи́во піє́м но́воє, не от ка́мене істе́кшеє, но от істо́чника нетлі́ннаго і живоно́снаго гро́ба Спаси́теля, і́мже безпло́дную зе́млю душ на́ших одожди́в, научи́ всіх пі́ти Єму́ си́це:","Ісу́се, напая́яй нас Своє́ю Кро́вію, да́руй мні неоску́дно прийма́ти пречестну́ю Кров сію́.","Ісу́се, ниспосила́яй дождь на пра́ведния і грі́шния, ороси́ і м'я к плодоноше́нію духо́вному.","Ісу́се, не возгнуша́вийся грі́шници пока́явшіяся, даждь і мні но́зі Твої́ оми́ти слеза́ми благодаре́нія.","Ісу́се, реки́й Фомі́: «блаже́нні не ви́дівшії, но ві́ровавшії», даждь мі ві́ру нелицемі́рную.","Ісу́се, реки́й: «іщі́те і обря́щете», да́руй мі обрісти́ Тя єди́наго на потре́бу.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 6","ps":["Пропові́дуяй в ду́сі неумолка́ющаго ра́дованія Твоє́ живоно́сноє воскресе́ніє, Ісу́се Бо́же мой, да бу́ду і аз грі́шний прича́стник сего́ воскресе́нія, поя́ Тебі́ непреста́нно в го́рнем Ієрусали́ме: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий всему́ ми́ру воскресе́нієм Свої́м Госпо́дь Ісу́с Христо́с, ни́ні вся ісполня́єть сві́та, не́бо же і зе́млю і преіспо́дняя; да пра́зднуєть у́бо вся твар Христо́во воста́ніє, в не́мже утвержда́єми вопіє́м си́це:","Ісу́се, вся ісполня́яй сві́том Твої́м, просвіти́ і мої́ омраче́нния о́чі.","Ісу́се, не́бо і зе́млю сочета́вий, возведи́ м'я от землі́ на не́бо.","Ісу́се, снизше́дий сві́том Божества́ в преіспо́дняя, сни́ди в преіспо́днюю душі́ моєя́.","Ісу́се, ізведи́й із темни́ць а́дових ожида́вшия Тя ду́ші, ізведи́ і м'я грі́шнаго із мра́ка уни́нія, я́ко живо́т мой а́ду прибли́жися.","Ісу́се, всім простира́яй пречи́стії ру́ці Твої́, обими́ і м'я окая́ннаго.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 7","ps":["Хотя́й откри́ти си́лу Божества́ Своєго́, Госпо́дь покрива́ється печа́тію Кая́фи, да не нару́шив о́ния пред стрегу́щими, побідоно́сно воста́неть і научи́ть пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно і непости́жно єсть, ка́ко вчера́ спогреби́йся Тебі́, Христе́, днесь совостаю́ ду́хом, Тебі́ воскре́сшему, і воспіва́ю та́ко:","Ісу́се воскре́сший, всім ту́не жизнь подава́яй, окрили́ ум мой, да Тебі́ послі́дствуєть.","Ісу́се, освяти́вий зе́млю Твої́ми стопа́ми, освяти́ мисль мою́, к Тебі́ вознося́щуюся.","Ісу́се, не возбрани́вий начерта́ти пречи́стий о́браз Твой, даждь і мні імі́ти ви́ну в душі́ моє́й о́браз Твоєго́ воскресе́нія.","Ісу́се, прия́вий дві ле́пті вдови́ці, прийми́ от мене́ піснь сію́.","Ісу́се, не осуди́вий блудни́ці, но на путь і́стини наста́вивий ю, не осуди́ і мої́х нечи́стих уст, в піснопі́нії Тя лобиза́ющих.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 8","ps":["Стра́нно Бо́га вочелові́чшася і воскре́сша ми́сленно ви́дяще, вся́коє жите́йськоє отложі́м попече́ніє, я́ко да Царя́ всіх поди́мем і воспоє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ любо́в к па́дшим челові́ком, о Ісу́сі, і поста́вил єси́ на боже́ственній стра́жі богоглаго́ливаго Авваку́ма, да пока́жеть світоно́сна а́нгела, я́сно глаго́люща о воскресе́нії Твоє́м. Ті́мже і ми зове́м Тебі́ си́це:","Ісу́се, стрего́мий во́їнами, посли́ па́ки а́нгела храни́теля на стра́жу душі́ моєя́, єго́же аз отгоня́ю гріхи́ мої́ми.","Ісу́се, ослепи́вий о́чі стрегу́щим Тя блиста́нієм Божества́, отврати́ о́чі мої́ от суєти́ і просвіти́ к позна́нію і́стини.","Ісу́се, вопроша́вий апо́стола Петра́, «лю́биши ли М'я?», даждь мні імі́ти о́браз любве́ єго́.","Ісу́се, прости́вий тому́ апо́столу отрече́ніє, прости́ і мні єжеча́сния отрече́нія от повелі́ній Твої́х.","Ісу́се, да́вий власть в'яза́ти і ріши́ти, разріши́ м'я от непра́вд мої́х.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 9","ps":["Все єстество́ челові́чеськоє Тобо́ю восприя́тоє просла́вися воскресе́нієм Твої́м, Ісу́се, і сего́ ра́ди да́руєши тілесе́м нетлі́ніє. Ті́мже ми, ви́дяще сіє́ зна́меніє в оста́нціх святи́х, вопіє́м со умиле́нієм: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї богоглаго́ливії у́тренюють ду́хом, сріта́я Тя ісходя́ща із гро́ба, і вмі́сто ми́ра прино́сять Ті піснь я́ко Со́лнцю пра́вди і Влади́ці, с ни́ми же на́ша моли́тви прийми́ сицеви́я:","Ісу́се, приє́мий ми́ро на Тя ізлія́нноє, прийми́ і мно́ю ізлія́нная славосло́вія.","Ісу́се, Со́лнце і́стини, просвіти́ ду́шу мою́.","Ісу́се, ри́бари соді́лавий ловці́ челові́ков, улови́ і мою́ злу́ю во́лю в Твоє́ послуша́ніє.","Ісу́се, із Са́вла соді́лавий первоверхо́внаго апо́стола, вразуми́ і м'я заблужда́ющаго.","Ісу́се, моли́твами апо́стола сего́ і всіх святи́х Твої́х, пощади́ м'я грі́шнаго.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й род челові́чеський Ісу́се, снизше́л єси́ на зе́млю і Бог сий восприя́л єси́ не́мощі на́ша, да і в них яви́ться си́ла Твоя́, подвиза́ющая пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ воскре́сший, Ісу́се Христе́, Спаси́телю наш! Ти, снизше́дий в преіспо́дняя землі́ і сокруши́вий вереї́ ві́чния, содержа́щия св'я́занния ду́ші, свободи́ і мене́ от уз гріха́, взива́юща Тебі́ си́це:","Ісу́се, вручи́вий возлю́бленнаго ученика́ Ма́тері Твоє́й, вручи́ і м'я спаси́тельному Єя́ смотре́нію.","Ісу́се, страда́нія Ма́тере Твоєя́ обрати́вий в ра́дость, даждь і мні окая́нному терпіли́во понести́ крест мой.","Ісу́се, да́вий ми́рові засту́пницю Ма́тер Твою́, даждь і мні грі́шному би́ти под кро́вом Єя́.","Ісу́се, младе́нцем невозбрани́вий прикаса́тися к Тебі́, да́руй мні їх незло́біє.","Ісу́се, реки́й блудни́це: «іди́, і отсе́лі не согріша́й», даждь мі ктому́ не прогнівля́ти Тя.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє о воскресе́нії Твоє́м да́руй мні принести́ Тебі́, о Спаси́телю мой! І в нем да при́йметь душа́ моя́ єле́й ісціле́нія от душевре́дних мечта́ній, і да поє́ть ви́ну Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприї́мно от воскресе́нія Твоєго́ восприя́вше лучі́ благода́ті, і чрез них я́ко в зерца́лі ви́дяще духо́вно Твоє́ живоно́сноє воста́ніє, поклана́ємся Кресту́ Твоєму́ Честно́му, і Свято́є Воскресе́ніє Твоє́ поє́м і сла́вим си́це:","Ісу́се, преклони́вий небеса́, прийми́ поклоне́ніє на́ше благоутро́бно.","Ісу́се, усну́вий пло́тію я́ко мертв, умертви́ на́ша плотські́я по́хоті.","Ісу́се, всего́ Себе́ да́вий на спасе́ніє челові́ков, даждь і мні всеці́ло преда́тися Тебе́.","Ісу́се, возше́дий на небеса́ угото́вати мі́сто лю́б'ящим Тя, всели́ і м'я во оби́телі Твоя́.","Ісу́се, сіди́й одесну́ю Отця́, десни́м овця́м сопричти́ м'я.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 12","ps":["Благода́ть даждь і мні, всіх возлюби́вий Ісу́се, і прийми́ моє́ моле́ніє я́ко дань приноси́мую Тебі́, і отжени́ от душі́ моєя́ вся лука́вая помишле́нія, да неосужде́нно воспою́ Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ всесла́вноє воскресе́ніє, велича́єм Тя, о Ісу́се Христе́ Бо́же наш! І ві́руєм, я́ко да́руєши всім живо́т ві́чний. Того́ ра́ди в сей нарече́нний і святи́й день, я́ко бра́тія друг дру́га оби́мем, ненави́дящим нас прості́м вся воскресе́нієм, і єди́ними усти́ і єди́нім се́рдцем возопії́м Тебі́ та́ко:","Ісу́се, благословля́яй благословля́ющия Тя, благослови́ і ни́ні поси́льний труд мой.","Ісу́се, освяща́яй на Тя упова́ющия, освяти́ жела́нія і намі́ренія моя́.","Ісу́се, обіща́вий би́ти с ві́рними до сконча́нія ві́ка, пребу́ди неотлу́чно і со мно́ю грі́шним.","Ісу́се, Сло́во Іпоста́си О́тчей, очи́сти недосто́йноє моє́ сло́во к Твоєму́ піснопі́нію.","Ісу́се, Па́сха спаси́тельная, от сме́рти к жи́зні приводя́щая, всели́ м'я в черто́г Твой, просвіти́в одія́ніє душі́ моєя́.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 13","ps":["О, Ісу́се Христе́, сме́ртію смерть попра́вий і су́щим во гробі́х живо́т дарова́вий! Прийми́ во воню́ благоуха́нія духо́внаго сіє́ ма́лоє моле́ніє на́ше і су́щим нам во гробі́х нераде́нія да́руй живо́т ві́чний, да поє́м Тебе́. Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели воскресе́ніє Твоє́, Христе́ Спа́се, непреста́нно пою́ть на небесі́х, і нас на землі́ сподо́би чи́стим се́рдцем воспі́ти Тебі́ си́це:","Ісу́се непостижи́мий, всіх ві́рних просвіща́яй, просвіти́ і м'я заблу́ждшаго.","Ісу́се воскре́сший, всіх Собо́ю оживля́яй, оживи́ м'я уме́ршаго гріхми́.","Ісу́се, на не́бо вознеси́йся і вознося́й на Тя наді́ющихся, совознеси́ і м'я до́лу прекло́ннаго.","Ісу́се, сідя́й одесну́ю Отця́ і разділя́яй сла́ву с лю́б'ящими Тя, не лиши́ м'я сла́ви Твоєя́.","Ісу́се, хотя́й прийти́ суди́ти живи́м і ме́ртвим, не осуди́ м'я по діло́м мої́м, но сотвори́ со мно́ю по ми́лості Твоє́й.","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Го́споди, ві́чния сме́рти побіди́телю, я́ко ізба́влься от духо́внаго умерщвле́нія, похва́льная воспису́ю Ті, возсозда́нний Тобо́ю, раб Твой. Ти же, я́ко імі́яй побі́ду над сме́ртію, от сме́рти гріхо́вния свободи́ нас, зову́щих:","Ісу́се воскре́сший, воскреси́ ду́ші на́ша."]},{"h":"Молитва до Господа Ісуса, що воскрес","ps":["Сла́ва Тебі́, Го́споди Ісу́се Христе́, Бо́же мой, я́ко па́ки сподо́бил м'я єси́ недосто́йнаго, преше́дши по́прище свята́го поста́, поклони́тися Боже́ственним Страсте́м Твої́м і ви́діти всера́достний день пресла́внаго із гро́ба Воскресе́нія Твоєго́, в о́ньже свободи́л єси́ су́щия во а́ді от вік св'я́занния ду́ші пра́ведних. Тоя́ Боже́ственния свобо́ди ду́ха і пло́ті, дража́йший Спаси́телю мой, і аз жела́ю, да разріши́ши м'я, свя́зана су́ща мно́гими гріхи́, і да сотвори́ши возсія́ти живоно́сному сві́ту Воскресе́нія Твоєго́ во мра́чній душі́ моє́й. Ви́жду бо безчи́сленния щедро́ти і неізрече́нноє человіколю́біє Твоє́, я́ко не то́чію от небитія́ в битіє́ м'я приве́л єси́, і о́браза Твоєго́ подо́бієм украси́в, всея́ до́льній тва́рі влади́ку поста́вил м'я єси́, но і посе́м па́дша с висоти́ і врагу́ порабо́тившася, не оста́вил єси́, но, іскупи́в м'я безці́нною Кро́вію Твоє́ю, благода́тію креще́нія снабди́л м'я єси́, да востеку́ на пе́рвоє достоя́ніє. Аз же, окая́нний, зап'я́т бив умо́м плотськи́м, обрати́хся всп'ять і па́ки раб сотвори́хся гріха́ і страсте́й, доне́ліже єди́н по єди́ному погуби́х все да́ри благода́ті Твоєя́. І ни́ні у́бо, что сотворю́, не вім; оба́че пом'яну́в глаго́ли пречи́стих уст Твої́х, я́ко не прише́л єси́ призва́ти пра́ведники, но грі́шники в покая́ніє, і аз, я́ко єди́н от сих, с ві́рою і смире́нієм прихожду́ к живоно́сному гро́бу Твоєму́, не арома́ти і воню́ ми́ра нося́й, (наг бо єсьм і пуст благи́х діл,) но па́че наде́жду іми́й обрісти́ в нем проще́ніє гріха́м мої́м і обновле́ніє нечи́стому житію́ моєму́. При́зри у́бо на м'я, ка́ющася і служи́ти Тебі́ хотя́ща, і не отри́ни от благода́ті Воскресе́нія Твоєго́! Живоно́сною сме́ртію Твоє́ю і погребе́нієм умертви́ моя́ лю́тия стра́сті, да, я́ко мертв і погребе́н, живу́ в ми́рі сем. Пресла́вним воста́нієм Твої́м воздви́гни мою́ ду́шу, умерщвле́нную гріхми́, і оживи́ со́вість, єя́же нічто́же в ми́рі ну́жнійши єсть. Вознесе́нієм Твої́м отто́ргни м'я от су́єтних і душетлі́нних благ земни́х, і сотвори́ м'я го́рняя му́дрствовати, я́ко да не ктому́ себі́ жив'я́ і угожда́я, но Тебі́, Го́споду і Бо́гу моєму́, служа́ і рабо́тая, я́коже сподо́бихся поклони́тися Воскресе́нію Твоєму́ на землі́, та́ко сподо́блен бу́ду ви́діти Тебе́, дража́йшаго Іскупи́теля моєго́, і на небесі́, за прия́тіє сме́рті кре́стния сла́вою і че́стію вінча́нна, і став одесну́ю вели́чествія Твоєго́, со арха́нгели і а́нгели, і со всі́ми іскупле́нними Тобо́ю бра́тіями мої́ми, во ві́ки віко́в пою́ Тебі́: Аллилу́я! Амі́нь."]},{"h":"Тропар, глас 5","ps":["Христо́с воскре́се із ме́ртвих, / сме́ртію смерть попра́в, // і су́щим во гробі́х живо́т дарова́в."]},{"h":"Кондак, глас 8","ps":["А́ще і во гроб снизше́л єси́ Безсме́ртне, / но а́дову разруши́л єси́ си́лу, і воскре́сл єси́ я́ко побіди́тель Христе́ Бо́же, / жена́м мироно́сицям віща́вий, ра́дуйтеся: / і Твої́м апо́столом мир да́руяй, // па́дшим подая́й воскресе́ніє."]},{"h":"Задостойник, глас 1","ps":["А́нгел вопія́ше Благода́тній: Чи́стая Ді́во, ра́дуйся! І па́ки реку́: ра́дуйся! Твой Син воскре́се тридне́вен от гро́ба, і ме́ртвия воздви́гнувий: лю́діє, веселі́теся.","Світи́ся, світи́ся, но́вий Ієрусали́ме: сла́ва бо Госпо́дня на тебі́ возсія́. Лику́й ни́ні і весели́ся, Сіо́не. Ти же, Чи́стая, красу́йся, Богоро́дице, о воста́нії Рождества́ Твоєго́."]}],"notes":[]},{"u":"Акафіст Входу Господньому в Єрусалим","e":"Akathist to the Entry of the Lord into Jerusalem","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Царю́ Го́рняго Сіо́на, Кро́ткий, спаса́яй і Пра́ведний Ізба́вителю наш, Тебі́, во ви́шніх на Херуви́міх носи́маго і піва́ємаго от Серафи́м, зрим ни́ні на жреб'я́ возше́дшаго і в Ієрусали́м к во́льній стра́сті гряду́щаго. Сего́ ра́ди покланя́ємся неізрече́нному снисхожде́нію Твоєму́, і с ва́ями і ві́твми умиле́нно сріта́єм Тя, да і с ді́ти євре́йськими воззове́м Тебі́:","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов ли́ки со стра́хом і с тре́петом взира́ху с небе́сних висо́т на Твоє́, Христе́ Спа́се, во Ієрусали́м к во́льной стра́сті вхожде́ніє і со Апо́столи незри́мо сопровождаху Тя Царя́ Своєго́ і с ді́ти євре́йськими «оса́нна во ви́шніх» Тебі́ приноша́ху і воспіва́ху піснопі́нія сицеви́я:","Благослове́н єси́, Го́споди Бо́же наш, я́ко посіти́л і сотвори́л єси́ ізбавле́ніє лю́дем Свої́м.","Благослове́н єси́, Влади́ко Христе́, я́ко прише́л і дарова́л єси́ Кресто́м спасе́ніє ча́дом Свої́м.","Благослове́н єси́, гряди́й Ада́ма із глубини́ а́да воззва́ти.","Благослове́н єси́, прише́дий Є́ві от дре́внія печа́лі свобо́ду дарова́ти.","Благослове́н єси́, благовіству́яй мир на Ізра́їля і спасе́ніє язи́ков.","Благослове́н єси́, возвіща́яй Заві́т Нов в кропле́нії кро́ві Своєя́.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 2","ps":["Ви́дів Тя, Ісу́се, Ма́рфа і Марі́я па́ки во Вифа́нію прише́дша пре́жде шести́ дній битія́ Па́схи, сотво́рша Тебі́ ве́черю ту, і бі Ла́зар єди́н от возлежа́щих, Ма́рфа с усе́рдієм служа́ше Тебі́, Пода́телю вся́чеських, Марі́я же благу́ю часть ізбра́, благодарна су́щи о воскреше́нії бра́та своєго́, і приє́мши ли́тру ми́ра на́рда чи́ста, многоці́нна, пома́за пречи́стия но́зі Твої́ і отре́ власи́ свої́ми, с любо́вію от ізби́тка се́рдця, вопію́ще Тебі́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума неуразуменна во́льнаго Твоєго́ на страда́нія прише́ствія не разумі́в Іу́да, і́же хотя́ше уже́ преда́ти Тя, смути́ся, зря́ще Марі́їно ми́ром пома́заніє но́гу Твоє́ю, Го́споди, і рече́: «Чесо́ ра́ди ми́ро сіє́ не про́дано бисть на тріє́х стіх пі́нязь і дано́ ни́щим?» Сіє́ же рече́ не я́ко о ни́щих печа́шеся, но я́ко тать бі. Ти же, Го́споди, ві́дий, я́ко надлежи́ть Ті ско́ро смерть претерпі́ти, оправда́л єси́ святу́ю жену́ сію́, глаго́люще: «Не ді́йте єя́, да в день погребе́нія Моєго́ соблюде́ть є». Сего́ ра́ди почита́юще во́льноє ко стра́сті прише́ствіє Твоє́, вопіє́м Тебі́ си́це:","Благослове́н єси́, Го́споди, Марі́єю на ве́чері на погребе́ніє приуготованний.","Благослове́н єси́, Ісу́се, Іу́дою в душе́ єще́ во Вифа́нії на смерть уже́ осужде́нний.","Благослове́н єси́, во Вифа́нію прише́дий, в дом ми́ра, да любо́в і ми́ром пома́заніє от Марі́ї приє́млеши.","Благослове́н єси́, во Ієрусали́м гряди́й на во́льную страсть, да па́ки любо́в от святи́х жен мироно́сиць всему́ ми́ру возвісти́ши.","Благослове́н єси́, Ла́заря із ме́ртвих воздви́гнувий, да бу́деть с крі́постію прише́ствіє Твоє́.","Благослове́н єси́, Себе́ Самаго́ от гро́ба возста́вити гряди́й, да бу́деть со вла́стію вхожде́ніє Твоє́.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 3","ps":["Імі́яй власть воі́стину Боже́ственную, Влади́ко Христе́, Ти во у́трій день ізше́д із Вифа́нії зіло́ зау́тра і приближася во Виффагію, посла́л єси́ дво́їцю от учени́к Твої́х, глаго́люще і́ма: «Іди́та во весь, я́же пря́мо ва́ма: і а́біє обря́щета осля́ прив'я́зано, і жреб'я́ с ним, на не́же нікто́же ніколи́же всі́де от челові́к, і отріши́вша я, приведі́те Мі. І си́це кто рече́ть вам, что твори́ти, рці́те, я́ко Госпо́дь тре́буєть я». Ті́їже сія́ слишаші, зіло́ дивля́хуся, возопили Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Ізше́дша же ученика́, приведо́ста осля́ і жреб'я́, і возложи́ша на не ри́зи своя́. Ти же, Бог Сий, на Херуви́міх носи́мий, я́ко челові́к на жреб'я́ мла́до возсі́л єси́ нас ра́ди, да я́ко Цар кро́ток, в мир сотвори́ши вхожде́ніє Твоє́, во град отця́ Твоєго́ Дави́да. Сего́ ра́ди сріта́єм Тя сицеви́ми похвали́:","Благослове́н єси́, во Ви́шніх со Отце́м на Престо́лі сідя́й, на жреб'я́ті о́сли сі́сти ізво́ливий.","Благослове́н єси́, на небесі́х от Го́рних Сил покланя́ємий, от діте́й на землі́ поклоне́ніє прия́вий.","Благослове́н єси́, крі́постію ца́рствуяй ві́ки, со сла́вою во Ієрусали́м гряди́й.","Благослове́н єси́, на смире́нния призира́яй, с кро́тостію во своя́ прише́дий.","Благослове́н єси́, на жреб'яті безслове́сном возсі́дий, дре́внєє безслове́сіє разріши́ти хотя́й.","Благослове́н єси́, стра́нноє обнищаніє до́лу приє́мий, на небесі́ го́ре Отцю́ і Ду́ху сосідя́й.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть мі ум, ка́ко досто́йно воспою́ ве́ліє снисхожде́нія Твоєго́ та́їнство, Го́споди, я́ко імі́я престо́л — не́бо, Ти на жреб'я́ ху́до возше́л єси́ челові́ка взиску́я, хотя́ разріши́ти єго́ дре́вняго безслове́сія, да сбу́деться рече́нноє Заха́рією проро́ком глаго́лющим: «Ра́дуйся зіло́, дщи Сіо́ня, пропові́дуй дщи Ієрусали́мля. Се Цар Твой гряде́ть к Тебі́ Пра́веден і Спаса́яй, Той Кро́ток всід на под'яремника і жребця́ ю́на». Сего́ ра́ди прославля́єм с ми́ром на жреб'яті ше́ствіє Твоє́ во Ієрусали́м, із глубини́ душі́ вопію́ще Тебі́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше наро́д мног прише́дий на пра́здник, я́ко гряде́ши Го́споди во Ієрусали́м, собра́шася вку́пі во мно́жестві і постила́ху ри́зи своя́ по путі́, друзі́ї же рі́заху ві́тві от древ і постила́ху по путі́, і предходя́щії і вслід гряду́щії вопія́ху Тебі́, глаго́люще: «Оса́нна Си́ну Дави́дову! Благослове́н гряди́й во і́м'я Госпо́днє! Благослове́нно гряду́щеє Ца́рство во і́м'я Го́спода отця́ на́шего Дави́да! Оса́нна во ви́шніх!» Сего́ ра́ди і ми в предпра́зднственний день сей, нося́ще воскресе́нія зна́менія ві́тві древе́с, Тебі́, я́ко Побіди́телю сме́рти вопіє́м:","Благослове́н єси́, Царю́ Ізра́їлев, Ца́рство не от ми́ра сего́ взиска́ти прише́дий.","Благослове́н єси́, Си́не Дави́дов, тро́сти сокруше́нния преломи́ти не восхоті́вий.","Благослове́н єси́, Па́стирю До́брий, заблудшеє овча́ обрісти́ гряди́й.","Благослове́н єси́, А́гнче незло́бивий, Себі́ Самаго́ в же́ртву принести́ хотя́й.","Благослове́н, єси́ Влади́ко тва́рі, от тва́рі Твоєя́ с любо́вію сретаємий і с ві́твми ублажа́ємий.","Благослове́н єси́, Царю́ Сла́ви, со сла́вою ца́рською от учени́к провождаємий і от діте́й прославля́ємий.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 5","ps":["Богосві́тлою красото́ю і крі́постію облече́н бив от ві́ка, Го́споди, гряде́ши со сла́вою в Сіо́н, восхо́д на Єлео́нськую го́ру соверша́я, да іспо́лниться Нау́ма проро́ка предрече́ніє: «Се на гора́х но́ги Благовіству́ющаго і Возвіща́ющаго мир. Пра́зднуй Іу́до пра́здники твоя́, возда́ждь обі́ти твоя́». І па́ки іспо́лнися Дави́да пра́отця Твоєго́ друго́є предрече́ніє: «Ви́діна би́ти ше́ствія Твоя́, Бо́же, ше́ствія Бо́га моєго́, і́же во святі́м». Єгда́ же прибли́зился єси́ уже́ к нисхожденію с гори́ Єлео́нськия, все мно́жество ученико́в нача́ша ра́дующеся хвали́ти Бо́га гла́сом ве́ліїм, сугу́бо прославля́юще Тя о всіх чудесі́х, я́же ви́діша от Тебе́, глаго́люще: Благослове́н гряди́й Цар во і́м'я Госпо́днє! Мир на землі́ і сла́ва во ви́шніх! Сего́ ра́ди і ми днесь Но́вий Ізра́їль, я́же от язи́к Це́рков, ра́дующеся возопіє́м Тебі́ с ни́ми: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше фарисе́ї от наро́да су́щії, я́ко ликованії народния зіло́ умножа́ються, Тебі́, Го́споди, с гори́ нисходящу, і я́ко гла́си ученико́в Твої́х зіло́ ве́лії суть, вознегодоваша і ре́кша Тебі́: «Учи́телю, запрети́ ученико́м Твої́м.» Ти же, Го́споди, возгласи́л єси́ їм: «а́ще сі́ї умо́лкнуть, ка́мни возопію́ть, я́коже предрече́ Авваку́м проро́к, глаго́ля: “ка́меніє із стін возопію́ть, дре́во же отвіща́ти бу́дуть їм”». Сего́ ра́ди і ми, а́ще душа́ми і се́рдці хладні єсьми́, я́коже ка́меніє, оба́че по сло́ву Твоєму́ не умолчи́м хвали́ Тебі́ возсила́ти сицеви́я:","Благослове́н єси́, Го́споди Бо́же наш, я́ко прише́л єси́ во Ієрусали́м грі́шния спасти́.","Благослове́н єси́, Христе́ Спа́се наш, я́ко возвісти́л єси́ ві́рним Твої́м, я́ко близь к нам єси́.","Благослове́н єси́, Си́не Оте́чь, я́ко гряде́ши Кро́вію Креста́ Твоєго́ небе́сная і земна́я примири́ти.","Благослове́н єси́, Си́не Челові́ч, я́ко і́деши ве́лію любо́в Отця́ Небе́снаго всему́ ми́ру возвісти́ти.","Благослове́н єси́, Царю́ Ца́рствующих, я́ко Ца́рство Твоє́ — Ца́рство всіх віко́в.","Благослове́н єси́, Влади́ко владі́ющих, я́ко Влади́чество Твоє́ — во вся́ком ро́ді і ро́ді.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 6","ps":["Пропові́дници Боже́ственния си́ли Твоєя́, Го́споди, би́ша су́щії с Тобо́ю во Вифа́нії іуде́ї, зане́ ті́ї свиді́тельствоваху во Ієрусали́мі, я́ко Ла́заря от гро́ба воздви́гл єси́. Сего́ ра́ди і сріта́я Тя наро́д, я́ко сли́шаща Тя сіє́ сотво́рша зна́меніє. І глаго́лаху друг ко дру́гу: чесо́ ждем і не ісхо́дим на срі́теніє Си́ну Дави́дову с ва́ями от фи́ник, да іспо́лниться Писа́ніє: «взи́ду на фи́ник, удержу́ ві́тві єго́», зане́ Той єсть фи́ник пра́вди, о Не́мже рече́ Дави́д: «Пра́ведник, я́ко фі́нікс процвіте́ть». Сего́ ра́ди с ві́твми воспіва́ху пе́рвіє Тебі́ наро́ди: Оса́нна, оба́че по́сліжде с дреколми ізидо́ша на Тя, я́ко на разбо́йника, не ві́дуще пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во всей сла́ві своє́й і красоті́ святи́й град Бо́жий Сіо́н, «град Вели́каго Царя́», єгда́ прибли́зился єси́ к нему́, Го́споди, і уви́діл єси́ с висоти гори́ Єліонськия вся зда́нія церко́вная і іна́я строє́нія гра́дськая зіло́ кра́сния. Тогда́, ви́дя святи́й град, Го́споди, восплакался єси́ о нем, я́ко оте́ць чадолюби́вий, і с пла́чем рекл єси́: «а́ще би разумі́л єси́ ти хотя́ в сей день твой, є́же к ми́ру твоєму́, оба́че сіє́ скри́ся от о́чію твоє́ю». І а́біє предре́кл єси́, я́ко при́йдуть дні́є, єгда́ обложа́ть святи́й град вразі́ і разбію́ть єго́, і ча́да єго́, і не оста́в'ять ка́мень на ка́мни в нем, поне́же не разумі́л вре́мені посіще́нія Твоєго́. Ми же ві́дуще Тя, я́ко До́браго Па́стиря, скорб'я́щаго об заблудших овця́х Свої́х, вопіє́м Ті:","Благослове́н єси́, Па́стирю овця́м Вели́кий, овча́ поги́бшеє взиска́ти прише́дий.","Благослове́н єси́, Архієре́ю гряду́щих благ, не́мощем на́шим спострада́ти восхоті́вий.","Благослове́н єси́, Но́ваго Заві́та Хода́таю, возжела́вий па́дшия лю́ди от ві́чния сме́рти спасти́.","Благослове́н єси́, Судіє́ Пра́веднійший, я́ко пра́веден єси́, і пра́ви суди́ о гра́ді Твоє́м.","Благослове́н єси́, Спа́се Всемилостивейший, я́ко ми́лостив бива́л єси́ і ми́лости Твоєя́ іспо́лнь вся земля́.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 7","ps":["Хотя́й ізба́вити род челові́ч от рабо́ти вра́жия, Ісу́се, прише́л єси́ во Ієрусали́м, да іспо́лниться Писа́ніє: «яви́ться Бог бого́во в Сіо́ні». Тебе́ та́мо, потрясе́ся весь град; єди́нії бо ізидо́ша на срі́теніє Тебі́, восклиця́юще велегла́сно: «Оса́нна Си́ну Дави́дову», друзі́ї же, удивля́хуся вопроша́юще: «Кто єсть Сей». О, безу́мнії ста́рці, лжеїменії учи́теліє! Вся сто́гна гра́да пропові́дують чудеса́ Твоя́. Вся Іудея іспо́лненна благодія́ньми Твої́ми, сі́ї же вопроша́ють: «Кто єсть?» Ла́зар єдва́ воскре́се, і не ві́дять, кто ісхити́ єго́ от сме́рти. От двора́ Іаї́рова єдва́ ісшел єси́, і не ві́дять, кто єсть оживи́вий дщер єго́? Ви́дять, оба́че не хотя́ть воспі́ти Тебі́, я́ко Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє показа́л єси́ смотре́ніє Твоє́, Ісу́се, єгда́ со сла́вою восше́л єси́ во Ієрусали́м і а́біє, я́ко Архієре́й, посіти́л єси́ святи́й храм согля́дати єго́. В дом Отця́ Твоєго́ прише́л єси́ со вла́стію, і іспо́лнися свята́го Авваку́ма проро́ка предрече́ніє: «Госпо́дь во Свято́м хра́мі Своє́м: да молчи́ть вся земля́ пред Лице́м Єго́». І а́біє ізгна́л єси́ вон вся су́щії та́мо продающия і куплющия, глаго́ля: «Храм Мой — храм моли́тви нарече́ться, ви же сотвори́сте єго́ верте́п разбо́йником». І та́ко іспо́лнися друго́є Писа́ніє: «Ре́вность до́ма Твоєго́ сніде́ М'я». Ми же, убоя́вшеся такова́го пра́веднаго гні́ва Твоєго́, Го́споди, єди́ноє про́сим от Тебе́, є́же жи́ти в до́му Твоє́м во вся дні живота́ на́шего, зрі́ти красоту́ Твою́ і посіща́ти храм святи́й Твой, да просла́вим Тебі́ си́це:","Благослове́н єси́, не в рукотворе́нних храмах живи́й на Небесі́, в храм земни́й со сла́вою возше́дий.","Благослове́н єси́, селе́ніє сла́ви Своєя́ возлюби́вий на землі́, дом моли́тви от жите́йських попече́ній оградивий.","Благослове́н єси́, Го́споди сил, я́ко возлю́бленна селе́нія Твоя́, па́че селе́ній грі́шничих.","Благослове́н єси́, Царю́ сла́ви, я́ко лу́чше день єди́н во дво́ріх Твої́х, па́че ти́сящ, во граді́х нечести́вих.","Благослове́н єси́, ве́лій в Сіо́ні, я́ко стра́шно і свя́то і́м'я Твоє́.","Благослове́н єси́, живи́й во Ієрусали́мі, я́ко свят храм Твой, ди́вен в пра́вді Твоє́й.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до сотвори́л єси́, Христе́, єгда́ «внеза́пу прише́л єси́ в Це́рков Свою́ і та́мо приступивших к Тебі́ хроми́х і сліпи́х ісціли́л єси́», я́ко Светлодавець, і Ми́лостивий Врач, я́ко «пра́вда пред Тобо́ю предидеть», я́коже рече́ Дави́д, і та́ко всім істочи́л єси́ во вели́кий і предпра́зднственний день сей ра́дость, і́стину, світ і живо́т, я́коже предрече́ Софонія проро́к, глаго́ля: «Ра́дуйся дщи Сіо́нова зіло́, отьять Госпо́дь непра́вди твоя́, воцари́ться Госпо́дь посреді́ тебі́ і не у́зриши зла ктому́, Госпо́дь Бог твой в тебі́ і обнови́ть тя в любві́ Своє́й тебе́ ра́ди, глаго́леть Госпо́дь: спа́су утесненную, і отринове́нную прийму́». Сего́ ра́ди і ми, веселя́щеся в день пра́здника посіще́нія Твоєго́, воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ любо́в, Сладча́йший Ісу́се, сего́ ра́ди хвалу́ Тебі́ прино́сить возлю́бленний Ізра́їль ізо уст ссу́щих і незло́бивих младе́нець: єгда́ ста́рці і учи́теліє їх богохульствують вопрощающе, кто єсть Сей, младе́нці богосло́вствують, вопію́ще Тебі́: «Оса́нна Си́ну Дави́дову», і с ва́її і с ветвми сріта́ють во хра́мі прише́ствіє Твоє́, предвозвіща́юще ско́роє Твоє́ із ме́ртвих воскресе́ніє. Сподо́би же і нам одержи́мим го́рдостію обрати́тися, я́ко незло́бивії ді́ти, такови́х бо єсть Ца́рствіє Небе́сноє, да от чи́стаго се́рдця ку́пно с ни́ми принесе́м Тебі́ такови́є похвали́:","Благослове́н єси́, во ви́шніх піва́ємий от Серафи́м, от незло́бивих младе́нець воспіва́ніє прия́вий.","Благослове́н єси́, в го́рніх носи́мий от Херуви́м, от чи́стих се́рдцем богоносно в се́рдці носи́мий.","Благослове́н єси́, ски́нію па́дшую Дави́дову возста́вити прише́дий, да на́шу вну́треннюю благообра́зную ски́нію па́ки просвіти́ши.","Благослове́н єси́, храм Твой — дом моли́тви сотвори́вий, да нас би́вших верте́п душетлі́нних разбо́йников па́ки дом чист Ду́ха Свята́го сотвори́ши.","Благослове́н єси́, Єму́же ти́сящи ти́сящ служа́ху на Небесі́ і тьми тім предстоя́ху пред Ним.","Благослове́н єси́, Єму́же со́нми діте́й воспіва́ху на землі́ і тьми народния сріта́ху Єго́.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 9","ps":["Все со́нмище Іуде́йськоє архієре́єв і кни́жников, ви́дівше чудеса́, я́же сотвори́л єси́ во хра́мі, Ісу́се, і о́троки зову́щия: «Оса́нна Си́ну Дави́дову», вознегодоваша і рі́ша Тебі́: «Сли́шиши ли, что сі́ї глаго́лють?» — Ти же рекл єси́ їм: «Ні́сте ли чли ніколи́же, я́ко ізо уст младе́нець і ссу́щих соверши́л єси́ хвалу́.» Ми же удивля́ющеся окамене́нію і жестосе́рдію серде́ць їх, зло́бою да младе́нчествуєм ни́ні, да в простоті́ серде́чной воспоє́м А́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї Боже́ственнії, а́ще і мно́го глаго́лють, но не возмо́гуть возда́ти досто́йнаго благодаре́нія неізрече́нному снисхожде́нію Твоєму́, Христе́, я́ко ни́ні во́лею прише́л єси́ во Ієрусали́м крест претерпі́ти, сего́ ра́ди утаї́л єси́ от прему́дрих і разу́мних Своє́ Божество́ і откри́л єси́ є младе́нцем, і́же чи́стим се́рдцем па́че оте́ць свої́х ощути́ша, я́ко Ти єси́ воі́стину Христо́с. Сподо́би і нам душа́ми чи́стими і нескве́рними усти́ іспові́дати Боже́ственную Сла́ву Твою́, пою́ще Тебі́ си́це:","Благослове́н єси́, явле́нієм слове́с Твої́х просвіща́яй і вразумля́яй младе́нці, просвіти́ і вразуми́ на́ші ми́слі і се́рдця.","Благослове́н єси́, творе́нієм чуде́с Твої́х свиді́тельствуяй Божество́ Своє́, откри́й о́чі мої́ уразумі́ти от зако́на Твоєго́ чудеса́.","Благослове́н єси́, паси́й Ізра́їля, паси́ м'я в кро́тості ду́ха на мі́сті зла́чні.","Благослове́н єси́, храня́й Іа́кова, всели́ м'я в чистоті́ се́рдця на воді́ поко́йні.","Благослове́н єси́, Царю́ ми́ра, да возсія́єть во днех Твої́х пра́вда, до́ндеже отиметься луна́.","Благослове́н єси́, Со́лнце Пра́вди, да просвіти́ться світ Твой во мно́жестві ми́ра, до́ндеже сія́єть со́лнце.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 10","ps":["Спасти́ хотя́й язи́ки, Христе́ Бо́же наш, Ти воздви́гл єси́ ні́циї от е́ллин, прише́дших поклони́тися в пра́здник, я́ко да ви́дять Тя. Сего́ ра́ди ті́ї приступи́ша к Фили́ппу, глаго́люще: «Хо́щем Ісу́са ви́діти». То́йже вку́пі с Андре́єм глаго́лаху Тебі́. Ти же отвещеваєши їм, я́ко ни́ні уже́ при́йде час, да просла́виться о сем Син Челові́чеський. Во своя́ бо прише́л єси́ і свої́ не прия́ша Тя, і на смерть осуди́ша. Сего́ ра́ди, я́ко зе́рно пшени́чноє не принесе́ть плода́, а́ще пад на зе́млю не у́мреть, та́ко же і Ти сме́ртію Своє́ю мног плод прине́сл єси́ во язи́ціх, да іспо́лниться Іса́її проро́ка предрече́ніє, я́ко явле́н бил єси́ не іщущим Тя, і обрі́тен бил єси́ не вопрошающими Тя. Сего́ ра́ди «прийді́те язи́ци і ви́діте днесь Царя́ Небе́снаго, я́ко на престо́лі висо́ці на жреб'яті ху́ді во Ієрусали́м входя́ща», да всі єди́ними усти́ і се́рдцем воспоє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чний, кро́ткий, пра́ведний і спаса́яй Уті́шителю наш! Ти кро́тко прише́л єси́ в день сей во Ієрусали́м на кротком жреб'я́ті о́сли сидя́, да ко́нськоє свирі́пство разріши́ши на землі́. Сего́ ра́ди кро́тость Твоя́ разу́мна да бу́деть всім челові́ком, і да ві́дають всі, я́ко Ти взира́єши то́кмо на кро́ткаго, молчали́ваго, трепе́щущаго слове́с Твої́х. Сего́ ра́ди «да раскую́ть мечі́ своя́ на ора́ла і ко́пія на серпи́, і да не нави́кнуть ктому́ ра́товатися». Ми же «кро́тці су́щи душе́ю і смире́нії нра́вом, благода́тію при́ймем кро́ткаго всіх Влади́ку, гряду́щаго горди́ню лука́ваго сокруши́ти», да в кро́тості ду́ха воспоє́м Єму́ си́це:","Благослове́н єси́, на го́ру Сіо́н возше́дий, да мир на Ізра́їля благовестиши.","Благослове́н єси́, Ієрусали́му пропові́дуяй, да спасе́ніє язи́ков возвісти́ши.","Благослове́н єси́, прише́дий благовісти́ти ни́щим лі́то Госпо́днє прия́тно, да вся сокруше́нния се́рдцем ісціли́ши.","Благослове́н єси́, восхоті́вий возвісти́ти пліне́нним отпуще́ніє, да вся уничиже́нния во отра́ду свободи́ши.","Благослове́н єси́, я́ко ко́кош птенці́ своя́ под крилі́ собира́яй, да вся обремене́нния гріхми́ Кресто́м іску́пиши.","Благослове́н єси́, я́ко зе́рно пшени́чноє в зе́млю па́дшеє, ко погребе́нію гряди́й, да вся до глубини́ а́да павшия Воскресе́нієм обнови́ши.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє принесе́м Тебі́, Христе́, вку́пі с незло́бивими младе́нці, «оса́нна» Тебі́ воспевшими, с ни́миже і ми Тебі́ вопіє́м: Бог Госпо́дь, і яви́ся нам, да с ва́її і ві́тві соста́вим Тебі́ пра́здник свят, чист і духо́вен, да па́ки сотвори́ши вход во вну́треннія хра́мини душ на́ших, я́коже обіща́лся єси́, глаго́ля: «не оста́влю вас си́ри, но па́ки прийду́ к вам. А́ще кто лю́бить М'я, возлюблю́ єго́, і явлю́ся єму́ Сам. І Оте́ць Мой возлю́бить єго́, і к нему́ при́йдем і оби́тель у него́ сотвори́м». Благослове́нно да бу́деть вхожде́ніє Твоє́! Прийди́ і возсяди па престо́ле ума́ на́шего, я́коже пре́жде на жреб'я́, і воцари́ся в сердця́х на́ших і разріши́ вся безслове́сія страсте́й на́ших, да с присноцветущими ва́ями чистоти́ па́ки я́коже дре́вле ді́ти воспоє́м Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том небе́сним просвіти́ся днесь святи́й храм, єгда́ посіти́л єси́ єго́, Ісу́се, і очи́стил єси́ єго́ от ку́плей земни́х, вку́пі же просвіти́ся с ним і весь святи́й град, я́коже предрече́ Іса́їя: «от Сіо́на бо ізи́де зако́н і сла́ва Госпо́дня із Ієрусали́ма», я́ко на страда́нія прише́л єси́, і світ, ра́дость і любо́в прине́сл єси́ кресто́м Твої́м. Сего́ ра́ди, рекл єси́ ученико́м пре́жде Своєго́ креста́: «Єще́ ма́ло вре́м'я світ во вас єсть, ході́те, до́ндеже світ і́мате, да тьма вас не і́меть. Ві́руйте во світ, да си́нове сві́та бу́дете». Сіє́ рекл єси́, Го́споди, да і во страда́ніях Твої́х світ ві́ри не уга́снеть ученико́м Твої́м, і да не по́йдуть во тьмі неві́рія, не ві́дуще, ка́мо і́дуть, да і всі пра́во в Тя ві́рующії с ві́рою возопію́ть Тебі́:","Благослове́н єси́, Христе́, Сві́те ми́ра, от ми́ра лука́ваго возненави́дінний.","Благослове́н єси́, Ісу́се, Со́лнце Пра́вди, от при́сних Твої́х присноблажимий і препросла́вленний.","Благослове́н єси́, Невече́рній і Ти́хий Сві́те, на захожденіє Своє́ во Ієрусали́м прише́дий.","Благослове́н єси́, живи́й во Сві́ті непристу́пнім, заре́ю Воскресе́нія весь мир просвіти́ти гряди́й.","Благослове́н єси́, сладча́йший і присноживо́тний Сві́те, в Сіо́ні явле́нний, да просвіти́ши душе́вную тьму мою́.","Благослове́н єси́, Світи́льниче світя́й і горя́й, во Ієрусали́мі возже́нний, да па́ки возжеши уга́сший світи́льник мой.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 12","ps":["Благода́ть Твою́ подажд нам, Ісу́се, я́ко же пре́жде отроко́м євре́йським оса́нна Тебі́ воспевшим і позна́вшим Твоє́ Божество́. І ни́ні в пречестниі дні сія́, Го́споди, па́ки к нам близ бу́ди, найпа́че же к призива́ющим і́м'я Твоє́ в ду́хі кро́тости і ми́ра, смире́нія і любве́, сподо́би же і нам ощути́ти благода́ть прише́ствія Твоєго́, да і мир Бо́жий превосходя́й всяк ум, да соблюде́ть се́рдця на́ша і вся разумі́нія на́ша о Тебі́, і та́ко просвіти́вши душі́ на́ші, во умиле́нії і с весе́лієм возопіє́м Тебі́, Заві́т нов завіща́ти пришедшаму нам кропле́нієм кро́ві Своєя́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ на во́льную страсть во Ієрусали́м прише́ствіє і неізрече́нноє снисхожде́ніє Твоє́, Христе́, поклоня́ємся предначатію Креста́ Твоєго́ і с ді́ти євре́йськими веселя́щеся, с ва́ями і ві́твми сріта́єм Тя, і соста́вльше пра́здник, прославля́єм Тя, я́ко Ти єси́ воі́стину Мессія Христо́с прише́дий і імі́яй па́ки со сла́вою прийти́ суди́ти живи́х і ме́ртвих, не на жреб'я́ті о́сли сідя́й, но я́ко Цар царе́м і Госпо́дь господствующим, Єму́же і́м'я — «Сло́во Бо́жиє», імі́яй вслід Себі́ не о́троки «оса́нна» поющиє, но вся во́їнства небе́сная вопію́щия гла́сом громо́в крі́пких: Аллилу́я, спасе́ніє, честь і сла́ва і си́ла Го́споду на́шему, я́ко воцари́ся Госпо́дь Вседержи́тель. Сіє́ вели́коє ше́ствіє Твоє́ в Сіо́н Го́рній нисходящ с Небесе́ от Бо́га с ві́рою ча́юще, прославля́єм в земни́й Сіо́н на всеми́рноє закла́ніє вхожде́ніє Твоє́, пою́ще Тебі́ си́це:","Благослове́н єси́, Си́не Оте́чь, сла́вою вінча́вий челові́ка, те́рнієм вінча́тися гряди́й, да терноно́сноє єстество́ на́ше плодоно́сно сотвори́ши.","Благослове́н єси́, А́гнче Бо́жий, взе́мляй гріхи́ ми́ра, да кро́вію Своє́ю нас па́дших па́че сні́га убелиши.","Благослове́н єси́, Женише́ душ і серде́ць на́ших, от Черто́га Твоєго́ ісходя́й, да нікто́же укри́ється от теплоти́ Твоєя́.","Благослове́н єси́, Па́стирю До́брий, входя́й ни́ні в твой о́вчий двор, да нікто́же похи́тить нас от руки́ Твоєя́.","Благослове́н єси́, Учи́телю наш, Сіо́на ра́ди не умолчавий до крестния Па́схи Твоєя́, да дру́ги своя́ до конця́ сло́вом і любо́вію на Ве́чері уті́шиши.","Благослове́н єси́, Спаси́телю наш, в червле́ни ри́зи напослі́док облещи́ся восхоті́вий, да нас я́ко неві́сту ри́зою спасе́нія і оде́ждею весе́лія украси́ши.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 13","ps":["О, Ісу́се Христе́, А́гнче Бо́жий, пре́жде вік на закла́ніє приуготованний, ни́ні же во Ієрусали́м на во́льную страсть гряди́й! Прийми́ ма́лоє сіє́ с ва́ями і ветвми приноси́моє Тебі́ моле́ніє на́ше, да в пречестниі дні сі́ї послі́дуєм стопа́м Твої́м в тишині́ і кро́тости ду́ха і во умиле́нії і чистоті́ се́рдця і та́ко да пребу́дем с Тобо́ю і во все вре́м'я земна́го стра́нствія на́шего. І сподо́би нам неосужде́нно причасти́тися Боже́ственния ра́дости Святи́я Па́схи Твоєя́ зді на землі́, да і по прише́ствії в Небе́сний Ієрусали́м на ві́ки соєдині́мся с Тобо́ю, со всі́ми святи́ми пою́ще А́нгельськую піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов ли́ки со стра́хом і с тре́петом взира́ху с небе́сних висо́т на Твоє́, Христе́ Спа́се, во Ієрусали́м к во́льной стра́сті вхожде́ніє і со Апо́столи незри́мо сопровождаху Тя Царя́ Своєго́ і с ді́ти євре́йськими «оса́нна во ви́шніх» Тебі́ приноша́ху і воспіва́ху піснопі́нія сицеви́я:","Благослове́н єси́, Го́споди Бо́же наш, я́ко посіти́л і сотвори́л єси́ ізбавле́ніє лю́дем Свої́м.","Благослове́н єси́, Влади́ко Христе́, я́ко прише́л і дарова́л єси́ Кресто́м спасе́ніє ча́дом Свої́м.","Благослове́н єси́, гряди́й Ада́ма із глубини́ а́да воззва́ти.","Благослове́н єси́, прише́дий Є́ві от дре́внія печа́лі свобо́ду дарова́ти.","Благослове́н єси́, благовіству́яй мир на Ізра́їля і спасе́ніє язи́ков.","Благослове́н єси́, возвіща́яй Заві́т Нов в кропле́нії кро́ві Своєя́.","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Кондак 1","ps":["Ізбра́нний Царю́ Го́рняго Сіо́на, Кро́ткий, спаса́яй і Пра́ведний Ізба́вителю наш, Тебі́, во ви́шніх на Херуви́міх носи́маго і піва́ємаго от Серафи́м, зрим ни́ні на жреб'я́ возше́дшаго і в Ієрусали́м к во́льній стра́сті гряду́щаго. Сего́ ра́ди покланя́ємся неізрече́нному снисхожде́нію Твоєму́, і с ва́ями і ві́твми умиле́нно сріта́єм Тя, да і с ді́ти євре́йськими воззове́м Тебі́:","Благослове́н Гряди́й во і́м'я Госпо́днє! Оса́нна во ви́шніх!"]},{"h":"Молитва Входу Господньому в Єрусалим","ps":["Го́споди Ісу́се Христе́ Бо́же наш, во ви́шніх со Отце́м на Престо́лі сідя́й, ви́ну на крилу от Херуви́м носи́мий і піва́ємий от Серафи́м, во днех же пло́ті Своєя́ на жреб'я́ті о́сли сі́сти ізво́ливий на́шего ра́ди спасе́нія, і от діте́й воспіва́ніє прия́вий і во Святи́й град Ієрусали́м пре́жде шести́ дній битія́ Па́схи на во́льную страсть прише́дий, да спасе́ши мир Кресто́м, погребе́нієм і Воскресе́нієм Твої́м! І я́коже тогда́ лю́діє, седящиє во тьмі і сі́ні сме́ртній, приє́мши ві́тві древе́с і ва́я от фи́ник, сріто́ша Тя; Си́на Дави́дова Тя іспові́дуя, та́кожде і нас ни́ні в предпра́зднственний день сей в подража́ніє о́ніх ва́я і ві́тві в рука́х нося́щих соблюди́ і сохрани́. І я́коже о́нії наро́ди і ді́ти «оса́нна» Тебі́ приноша́ху, сподо́би і нам во псалмі́х і пі́ніїх духо́вних душа́ми чи́стими, і нескве́рними усти́ просла́вити вся вели́чія Твоя́ в пра́здник сей, і во всю седьми́цю стра́сті Твоєя́, і неосужде́нно дости́гнути і причасти́тися Боже́ственния ра́дости Святи́я Па́схи в пресветлиі дні Живоно́снаго Воскресе́нія Твоєго́, да воспоє́м і просла́вим Твоє́ Божество́ вку́пі со Безнача́льним Твої́м Отце́м і Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["О́бщеє воскресе́ніє / пре́жде Твоєя́ стра́сти увіря́я / із ме́ртвих воздви́гл єси́ Ла́заря, Христе́ Бо́же. / Ті́мже і ми, я́ко о́троци побі́ди зна́менія нося́ще, / Тебі́ Побіди́телю сме́рти вопіє́м: / оса́нна во ви́шніх, // благослове́н Гряди́й во і́м'я Госпо́днє."]},{"h":"Інший тропар, глас 4","ps":["Спогре́бшеся Тебі́ креще́нієм, Христе́ Бо́же наш, / безсме́ртния жи́зні сподо́бихомся воскресе́нієм Твої́м, / і воспіва́юще зове́м: / оса́нна во ви́шніх, // благослове́н Гряди́й во і́м'я Госпо́днє."]},{"h":"Кондак, глас 6","ps":["На престо́лі на Небесі́, / на жреб'я́ті на землі́ носи́мий, Христе́ Бо́же, / А́нгелов хвале́ніє і діте́й воспіва́ніє / прия́л єси́ зову́щих Ті: // благослове́н єси́, гряди́й Ада́ма воззва́ти."]},{"h":"Величання","ps":["Велича́єм Тя, Живода́вче Христе́, Оса́нна во ви́шніх і ми Тебі́ вопіє́м Благослове́н Гряди́й во і́м'я Госпо́днє."]},{"h":"Задостойник, глас 4","ps":["Бог Госпо́дь, і яви́ся нам, соста́віте пра́здник, і веселя́щеся прийді́те, возвели́чим Христа́, с ва́їями і ві́твми, пі́сньми зову́ще: благослове́н Гряди́й во і́м'я Го́спода Спа́са на́шего."]}],"notes":[]},{"u":"Акафіст Живоносному Гробу і Воскресінню Господньому","e":"Akathist to the Life-giving Tomb and Resurrection of the Lord","secs":[{"h":"Кондак 1","ps":["Возбра́нному Воєво́ді, разруши́телю сме́рти і а́да, побі́дную піснь Тебі́, Всецарю́ Христе́, прино́сим, я́ко воста́л єси́, Всеси́льне, со сла́вою тридне́вен от гро́ба і вся уме́ршія от ві́ка совоскреси́л єси́; ми же, страда́нієм Твої́м ві́чния тлі ізба́вльшеся, к са́мому мі́сту погребе́нія Твоєго́ с весе́лієм і ра́достію зове́м:","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Ікос 1","ps":["А́нгел предста́тель с небесе́ низше́д, ка́мень от гро́ба Твоєго́ отвали́, Христе́ Бо́же, і мироно́сицям благовісти́ воста́ніє Твоє́, глаго́ля: «ше́дше, рці́те ученико́м Єго́, я́ко воста́ от ме́ртвих»; они́ же, вразумле́нниє чу́дним явле́нієм, зря́ще ко гро́бу Твоєму́, с ві́рою і любо́вію возглаша́ху:","Ра́дуйся, живоно́сний гро́бі, в не́мже Христо́с, я́ко челові́к, почи́, і я́ко Бог, воскре́се тридне́вен!","Ра́дуйся, я́ко із тебе́ Спас ми́ра, я́ко Жени́х із черто́га ізше́д, смерть попра́ і а́да пліни́л єсть!","Ра́дуйся, я́ко воста́нієм Того́, от ві́ка уме́ршії, в жизнь нестарі́ємую воста́ша!","Ра́дуйся, я́ко в тебі́ Христу́ возле́гшу, прокля́тая в ді́ліх челові́ка земля́ освяти́ся!","Ра́дуйся, я́ко тобо́ю первозда́нний Ада́м па́ки в ри́зу безсме́ртія облека́ється!","Ра́дуйся, я́ко в тебі́ о́браз всеми́рнаго воскресе́нія начертава́ється!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 2","ps":["Я́ко при́йде на гроб Марі́я Магдали́на і друга́я Марі́я пома́зати Ті́ло Твоє́, Христе́ Бо́же, обріто́ша а́нгела на ка́мені сідя́ща, і глаго́люща к ним: «не бо́йтеся! Вім бо, я́ко Ісу́са расп'я́таго і́щете; ність зді, но воста́, я́коже рече́ вам». Сія́ у́бо сли́шавше святи́я же́ни, те́кше всп'ять, благовісти́ша ученико́м о воста́нії Твоє́м, да всі, я́ко Творцю́ і воскре́сшему Влади́ці а́нгельськоє пі́ніє воспою́ть, глаго́люще: Аллилу́я!"]},{"h":"Ікос 2","ps":["Бу́рю внутр імі́яху сумни́тельних помишле́ній ученици́ Твої́, Христе́, в час сме́рти Твоєя́, не ві́дуще Писа́нія, я́ко подоба́єть Тебі́ із ме́ртвих воскре́снути; ті́мже Петр, вість приє́м о воста́нії Твоє́м, тече́ ко гро́бу, хотя́ ви́діти би́вшеє, прини́к же і ви́дів єди́ни ри́зи Твоя́ в нем лежа́ща, с ві́рою возгласи́:","Ра́дуйся, живоно́сний гро́бі, я́ко в тебі́, посреді́ землі́, всеми́рноє спасе́ніє соді́яся!","Ра́дуйся, я́ко Царю́ царе́й одр, і Влади́ке влади́к поко́їще бил єси́!","Ра́дуйся, я́ко тобо́ю беззако́нноє со́нмище іуде́йськоє всеконе́чні посрами́ся!","Ра́дуйся, я́ко пред тобо́ю є́ресь саддуке́єв, глаго́лющих не би́ти воскресе́нію, низложи́ся!","Ра́дуйся, гро́бі, па́че хра́ма Соломо́нова честні́йший!","Ра́дуйся, па́че ски́нії свиді́нія і ковче́га заві́та святі́йший!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 3","ps":["Сли́шавше, і́же от кустоді́ї, су́єтнії стра́жи гро́ба Твоєго́, Христе́, трус ве́лій би́вший, і ка́мень отвале́н і гроб пра́зден ви́дяще, от стра́ха би́ша я́ко ме́ртви, і те́кше во град, возвіща́ху архієре́єм і ста́рцем вся би́вшая; они́ же, пребеззако́ннії, а́ще і уми́слиша утаї́ти ве́ліє чу́до, но не возмого́ша сокри́ти і́стини, ніже́ восп'яти́ти ві́рующим пі́ти Тебі́: Аллилу́я!"]},{"h":"Ікос 3","ps":["І́же іногда́ стра́ха ра́ди іуде́йська потає́н сий учени́к Твой, Христе́, Іо́сиф, і́же от Аримафе́я, іспроси́ у Пила́та Боже́ственноє Ті́ло Твоє́ і с Никоди́мом, сміше́нієм сми́рни і ало́я пома́зав є і плащани́цею чи́стою обви́в, во гро́бі но́ві положи́, в не́мже нікто́же от челові́к погребе́н бисть, то́кмо Ти єди́н, да освяти́ши земно́є єстество́; уві́дів же по сих Твоє́ із ме́ртвих воскресе́ніє, прише́д ко гро́бу Твоєму́, со умиле́нієм возгласи́:","Ра́дуйся, живоно́сний гро́бі, не кустоді́єю, па́че же арха́нгелами і а́нгелами стрего́мий!","Ра́дуйся, я́ко от тебе́ Христо́с со сла́вою ізше́д, безу́мния стра́жи Пила́тови недоумі́нієм і у́жасом порази́!","Ра́дуйся, я́ко печа́тей гро́бних не вреди́в, богопроти́внаго Кая́фу посрами́!","Ра́дуйся, я́ко із тебе́ воскре́сшу Христу́, сві́тлий день всеми́рнаго Богові́дінія наста́!","Ра́дуйся, я́ко тобо́ю і́доли і куми́ри по всім конце́м землі́ сокруша́ться!","Ра́дуйся, я́ко на тебі́ хра́ми Бо́га і́стиннаго по всей вселе́нній утвердя́ться!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 4","ps":["Воспомина́юще ученици́ Твої́ пресла́дкоє обітова́ніє, є́же, гряди́й на во́льную страсть, провіща́л єси́ пред ни́ми, варя́ти їх по воскресе́нії в Галиле́ї, поспі́шшеся, ідо́ша в Галиле́ю, в го́ру, а́може повелі́л єси́, і ви́дівше Тя та́мо, Єго́же пре́жде обико́ша зрі́ти, і́стинна Челові́ка, не привиді́нієм, но са́мою ве́щію плоть на́шу нося́ща, с ві́рою і любо́вію, я́ко Бо́гу, поклони́шася, зову́ще: Аллилу́я!"]},{"h":"Ікос 4","ps":["Ра́зум неуразумі́нний бил єси́ іуде́ом, неразуме́вшим проро́чеських о Тебі́ сказа́ній, ніже́ іска́вшим позна́ти і́стину воскресе́нія Твоєго́, ка́ко печа́ти не руши́в, із гро́ба ізше́л єси́? Ті́мже безу́мне науща́ху кустоді́ю возвісти́ти лю́дем, Пречи́стоє Ті́ло Твоє́ укра́дено би́ти. Ми же, пресла́вному Воскресе́нію Твоєму́ див'я́щеся, похва́льная живоно́сному гро́бу Твоєму́ воспису́єм, глаго́люще:","Ра́дуйся, всебога́тий гро́бі, я́ко імі́л єси́ в тебі́ всім жизнь Подаю́щаго!","Ра́дуйся, я́ко оскверне́нная беззако́ніями челові́чеськими земля́ пречи́стою Пло́тію Христо́вою, в тебі́ возлежа́вшею, освяща́ється!","Ра́дуйся, я́ко Воскре́сший із тебе́ прия́ вся́ку власть на небесі́ і на землі́, да всіх і вся к Бо́гу Отцю́ приведе́ть!","Ра́дуйся, я́ко ка́меню от тебе́ а́нгелом отвале́ну би́вшу, святи́я же́ни мироно́сиці уразумі́ша Христо́во воскресе́ніє!","Ра́дуйся, я́ко Спа́су ми́ра із тебе́ воста́вшу, во всю зе́млю ізи́де апо́стольськоє віща́ніє!","Ра́дуйся, в не́мже благода́ть воскре́сшаго Жизнода́вця до днесь неви́димо почі́єть!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 5","ps":["По днех осми́х от воста́нія Твоєго́, Го́споди, прише́л єси́ ко ученико́м Твої́м, две́рем заключе́нним, дарова́ніє Свята́го Ду́ха подая́ їм. Тогда́ у́бо і Фомі́ рекл єси́: «прийди́, осяжи́ я́зви Моя́, і не бу́ди неві́рен, но ві́рен». Ті́мже позна́в Тебі́ і́стинно воскре́сша би́ти, с про́чими ученики́ ра́достні возопи́: Аллилу́я!"]},{"h":"Ікос 5","ps":["Віті́я суєму́дренния, кни́жники іуде́йстії, я́коже ри́би безгла́сния ви́дим, недоуме́ющия глаго́лати о пресла́вном воста́нії Твоє́м, Христе́, і неразуме́ющия, я́ко подоба́ше Тебі́ пострада́ти за род челові́ч і із ме́ртвих воскре́снути. Ми же, совоскре́сшиє Тебі́ ві́рою і любо́вію, с весе́лієм са́мому гро́бу Твоєму́ зове́м:","Ра́дуйся, живоно́сний гро́бі, я́ко тобо́ю жизнь ві́чная всім конце́м землі́ позна́ся!","Ра́дуйся, я́ко в тебі́ сме́ртію Нача́льника жи́зні сме́рти жа́ло і держа́ва сокруши́ся!","Ра́дуйся, я́ко от сі́вера і мо́ря к тебі́ приходя́ще, воскре́сшаго Жизнода́вця прославля́ють!","Ра́дуйся, я́ко от за́пада і восто́ка теку́ще, всі в тебі́ зало́г безсме́ртія обріта́ють!","Ра́дуйся, я́ко по о́бразу Твоєму́ все гро́би іздаду́ть свої́х мертвеце́во в день послі́дній!","Ра́дуйся, ві́ри христия́нськия утвержде́ніє і проро́чеських сказа́ній печа́те!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 6","ps":["Єгда́ по воскресе́нії Твоє́м, Христе́, яви́лся єси́ ученико́м Твої́м на мо́рі Тиверія́дстім, повеліва́я воврещи́ мре́жу одесну́ю корабля́, тогда́ возлю́бленний учени́к Твой, позна́в Тя от лови́тви риб, Петро́ві глаго́лаше: «Госпо́дь єсть!» Ізше́дше у́бо на зе́млю, обріто́ша огнь і ри́бу лежа́щу і хліб, от ни́хже вкуси́вше і позна́вше в Тебі́ своєго́ Учи́теля і Го́спода, єди́німи усти́ і єди́нім се́рдцем возопи́ша: Аллилу́я!"]},{"h":"Ікос 6","ps":["У́тру су́щу глубоку́, же́ни прийдо́ша на гроб Твой, Ісу́се, но жела́ємаго Ті́ла Твоєго́ не обрі́тше, недоумі́нієм і печа́лію одержи́ми бя́ху. Ти же, Уті́шителю скорб'я́щих, я́влься їм посреди́ вертогра́да, єди́ним гла́сом: «Марі́є!» плач їх на ра́дость преложи́л єси́, ті́мже позна́вше воскресе́ніє Твоє́, с весе́лієм восклиця́ху:","Ра́дуйся, живоно́сний гро́бі, в не́мже Христу́ все́льшуся, а́дова оскуді́ша ца́рствія!","Ра́дуйся, я́ко тебі́ от первосвяще́нников запечатлі́ну би́вшу, влади́ка сі́ні сме́ртния с тре́петом іздаде́ у́зники, я́же от ві́ка содержа́л єсть!","Ра́дуйся, я́ко в тру́сі, при воста́нії із тебе́ со сла́вою Іскупи́теля челові́ков, вся твар обрі́те ві́чноє успокоє́ніє!","Ра́дуйся, я́ко в тебі́ о́браз всеми́рнаго воскресе́нія Боголі́пно предизобрази́ся!","Ра́дуйся, я́ко тобо́ю лик апо́стольський во ві́рі і любві́ утверди́ся!","Ра́дуйся, і ти, Іо́сифе, толи́коє сокро́вище в твоє́м вертогра́ді стяжа́вий!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 7","ps":["В страда́нії Твоє́м, Христе́, не терп'я́ со́лнце беззако́нних неі́стовства, світ свой скри, і заві́са церко́вная раздра́ся; в живоно́сном же гро́бі Тебі́ положе́ну би́вшу, земля́ потрясе́ся, а́ки хотя́ поглоти́ти законопресту́пних; но Ти, я́ко Бог, воскре́с єси́ со сла́вою, і всеро́днаго Ада́ма воздви́гл єси́ с Тобо́ю, ті́мже досто́йно і пра́ведно воскресе́нію Твоєму́ зове́м: Аллилу́я!"]},{"h":"Ікос 7","ps":["По пресла́вном воста́нії Твоє́м, Христе́, Луці́ і Клео́пі яви́лся єси́, я́ко стра́нник, на путі́ в Еммау́с, і бесе́дующим їм о приклю́чшихся в Ієрусали́мі, зазира́єм бил єси́ от них, я́ко єди́н неві́дий би́вшаго. Ти же, я́ко Всеві́дущий, проро́чествія откри́в і неві́рствіє їх обличи́в, позна́лся єси́ і́ма в преломле́нії хлі́ба; ті́мже у́бо с ра́достію вели́кою возврати́вшеся во Ієрусали́м, і узрі́вше вертогра́д Іо́сифов, возгласи́ша:","Ра́дуйся, живоно́сний гро́бі, із него́же, я́ко Іо́на із чре́ва ки́това, Христо́с тридне́вен проізи́де!","Ра́дуйся, я́ко послі́днєє вита́лище бил єси́ Тому́, І́же на землі́ не імі́ гді главу́ подклони́ти!","Ра́дуйся, я́ко тобо́ю положи́ся преді́л во́льному уничиже́нію нас ра́ди Спаси́теля ми́ру!","Ра́дуйся, я́ко в тебі́ преднача́ся торжество́ Побіди́теля а́да і сме́рті!","Ра́дуйся, я́ко не ктому́ мо́гуть законопресту́пнії оклевета́ти лже́ю воста́ніє із гро́ба Си́на Челові́чеськаго!","Ра́дуйся, я́ко тобо́ю не́бо і земля́ і преіспо́дняя обріто́ша ра́дость!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 8","ps":["Все єстество́ а́нгельськоє і челові́чеськоє удиви́ся вели́кому Твоєму́, є́же о нас, смотре́нію: непристу́пнаго бо, я́ко Бо́га, зря́ще всім присту́пна Челові́ка, зрак раба́ приі́мша, расп'я́та же і погребе́нна, но воскре́сша в тре́тій день во сла́ві і возне́сшася с пло́тію на не́бо, тім у́бо я́ко Спаси́телю і Влади́ці воспіва́єм: Аллилу́я!"]},{"h":"Ікос 8","ps":["Но́воє і пресла́вноє чу́до показа́л єси́ воскресе́нієм Твої́м, Христе́ Бо́же наш, печа́ти гро́ба не вреди́в, я́коже і Ді́ви в рождестві́ Твоє́м, ті́мже почита́єм во́льная страда́нія Твоя́, славосло́вим Крест і погребе́ніє, і пресла́вному Воскресе́нію Твоєму́ покланя́ющеся, к живоно́сному гро́бу Твоєму́ с весе́лієм зове́м:","Ра́дуйся, всесвяти́й гро́бі, із него́же Христо́с, я́коже прорече́, воскре́се і Собо́ю весь мир обнови́!","Ра́дуйся, от него́же всезло́бний враг ро́да челові́чеськаго люті́йший уда́р во главу́ прия́!","Ра́дуйся, я́ко от тебе́ отвале́нний ка́мень а́дова врата́ сокруши́ і вереї́ желі́зния сотре́!","Ра́дуйся, я́ко із тебе́ всеми́рноє Со́лнце пра́вди возсія́ і мглу неві́рія разгна́!","Ра́дуйся, я́ко в тебі́ Христу́ возле́гшу, вся конці́ землі́ вони́ безсме́ртія іспо́лнишася!","Ра́дуйся, я́ко тебі́ откри́вшуся, істо́чник на́шего тлі́нія заключи́ся!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 9","ps":["Пропові́дници воста́нія Твоєго́, богоно́снії апо́столи, по́слани би́вше, от коне́ць до коне́ць землі́ пропові́даша Тебе́ і́стиннаго Бо́га, і́доли сокруши́ша, беззако́нниє оби́чаї язи́ческиє попра́ша, хра́ми і же́ртвенники Бо́гу і́стинну воздвиго́ша, і всіх ві́рних научи́ша воспіва́ти Тебі́: Аллилу́я!"]},{"h":"Ікос 9","ps":["По воста́нії Твоє́м із гро́ба, две́рем заключе́нним, ко ученико́м Твої́м вшел єси́, і вкуш от хлі́ба і со́та, Сла́дость церко́вная, не привиді́ніє пред ни́ми, но і́стиннаго їх Учи́теля і Го́спода би́ти уві́рил єси́, ті́мже, свобо́ждшеся от недоумі́ній і стра́ха, с ра́достію неізрече́нною посеща́ху мі́сто погребе́нія Твоєго́, глаго́люще:","Ра́дуйся, живоно́сний гро́бі, в не́мже Бог Сло́во, пло́тію усну́в, свяще́ннотайні тридне́внова!","Ра́дуйся, я́ко То́йже воста́нієм Свої́м вся от ві́ка усну́вшия возбуди́л єсть!","Ра́дуйся, я́ко в тебі́ Со́лнцю пра́вди, Христу́, заше́дшу, су́щим во а́ді і сі́ні сме́ртній Світ жи́зні возсія́!","Ра́дуйся, я́ко із тебе́ Проізше́дий, воскресе́ніє і живо́т ві́чний всім дарова́!","Ра́дуйся, я́ко а́нгелу о тебі́ благовіству́ющу, плач і рида́ніє Ада́мово преста́!","Ра́дуйся, я́ко ка́меню от тебе́ отпа́дшу, каменносерде́чнії язи́ци нави́кнуть ві́ровати в жизнь ві́чную!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 10","ps":["Земля́ убоя́ся і умолче́, Тебе́, Творця́ своєго́, зря́щи во гро́бі ма́лі положе́на; ад, вострепета́в от непристу́пния сла́ви Воскресе́нія Твоєго́, іздая́ше ме́ртвия, от ві́ка содержи́мия; небеса́ же восхо́д ко Отцю́ гото́в'яху, Єго́же ніколи́же отлуча́лся єси́. Ті́мже і ми, іску́пленнії Кресто́м Твої́м, всі Тебі́ зове́м: Аллилу́я!"]},{"h":"Ікос 10","ps":["Марі́я Магдали́на, я́ко теплі́йшая к Тебі́, Христу́ Бо́гу, ві́рою, зіло́ ра́но прише́дши на гроб Твой, сподо́бися узрі́ти Тя, Жизнода́вця, і жела́ше облобиза́ти пречи́стия но́зі Твої́, но Ти у́бо, я́ко Влади́ка вся́чеських, — «не прикаса́йся Мні», — рекл єси́, — «не у́бо взидо́х ко Отцю́ Моєму́, іди́ же к бра́тії Моє́й і рци їм о воста́нії Моє́м». Ті́мже, я́ко благові́стіє нося́щая, не́бо і зе́млю оглаша́ше, вопію́ще:","Ра́дуйся, живоно́сний гро́бі, в не́мже Христо́с Пречи́стою Пло́тію, усну́ і почи́ я́ко лев, ники́мже возбуди́мий!","Ра́дуйся, із него́же я́ко Бог, самовла́стні воста́, ничи́мже удержи́мий!","Ра́дуйся, я́ко о би́вшем в тебі́ ад нево́лею і́стинствуєть, глаго́ля: «у́не мні бя́ше, а́ще би от Марі́ї Ро́ждшагося не прия́л!»","Ра́дуйся, я́ко тобо́ю посра́млен, князь тьми рида́єть!","Ра́дуйся, я́ко тобо́ю обра́дован, лик а́нгельський торжеству́єть!","Ра́дуйся, но́вия благода́ті храни́лище і непрестаю́щих чуде́с істо́чниче!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 11","ps":["Предста́в, по воскресе́нії, ученико́м Твої́м, Христе́ Бо́же, мир Твой по́дал єси́ їм і власть отпуща́ти гріхи́, да пропові́дують воста́ніє Твоє́ от гро́ба, крестя́ще во і́м'я Отця́ і Си́на і Свята́го Ду́ха. Они́ же ізше́дше, я́ко облече́нниє си́лою сви́ше, научи́ша вся язи́ки воспіва́ти Тебі́, я́ко Бо́гу: Аллилу́я!"]},{"h":"Ікос 11","ps":["По воста́нії Твоє́м із ме́ртвих, явля́я Себі́ ученико́м Твої́м, Христе́, — «Си́моне Іо́нин, лю́биши ли М'я?» — рекл єси́ Петру́, і по трикра́тном любве́ єго́ к Тебі́ ізвіще́нії, Це́ркві Твоє́й па́ки того́ учи́теля і апо́стола дарова́л єси́; ми же, про́повідію єго́ науче́ннії, покланя́ющеся живоно́сному гро́бу Твоєму́, та́ко глаго́лем:","Ра́дуйся, всесвяти́й гро́бі, в не́мже, я́ко в ковче́зі Но́єві, от разлія́нія гріхо́внаго і тлі сме́ртния весь род челові́чеський спасе́ся!","Ра́дуйся, із него́же, я́ко із свята́го святи́х, мир і благослове́ніє всім па́дшим сина́м Ада́ма ізнесе́ся!","Ра́дуйся, любве́ Христо́ви к нам, во днех пло́ті Єго́, послі́дній кра́ю і преді́ле!","Ра́дуйся, і нас всіх бра́тію на́шу по пло́ті до сме́рти і гро́ба люби́ти научи́вий!","Ра́дуйся, мрак і стра́хи сі́ні сме́ртния для ві́рующих разгна́вий!","Ра́дуйся, стра́нником землі́ путь жи́зні ві́чния в небе́сний Ієрусали́м указа́вий!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 12","ps":["Боже́ственноє, є́же о нас, смотре́ніє Твоє́ сла́в'яще, стра́сті Твоя́ почита́єм, преди́вному воскресе́нію Твоєму́ покланя́ємся, і от землі́ к Небе́сному Роди́телю пресла́вноє вознесе́ніє воспіва́єм і мо́лимся: Пресвята́го Твоєго́ Ду́ха не отими́ от нас, да всі зове́м Тебі́ во ві́ки: Аллилу́я!"]},{"h":"Ікос 12","ps":["На го́ру Єлео́нськую єгда́ возше́л єси́, О́тчеє Сія́ніє, тогда́ пресві́тлий о́блак под'я́ть Тя, зря́щим ученико́м Твої́м, і а́нгели апо́столом глаго́лаху: «му́жіє Галиле́йстії, что стоїте́ зря́ще на не́бо? Се бо, Єго́же ви́діте вознося́щася, Той па́ки при́йдеть с пло́тію». Они́ же с ра́достію возврати́вшеся во Ієрусали́м, хва́ляху Тебе́, і́стиннаго Бо́га, і живоно́сному гро́бу Твоєму́, в не́мже тридне́вно положе́н бил єси́, с весе́лієм возглаша́ху:","Ра́дуйся, живоно́сний гро́бі, соби́вшимся в тебі́ всіх нас во ві́рі во Христа́ утверди́вий!","Ра́дуйся, пред мучи́телі і враги́ і́стини, наде́ждою воскресе́нія непобіди́ми нас сотвори́вий!","Ра́дуйся, в не́мже свяще́ннотайні, в купі́лі креще́нія, всі ві́рующії Христу́ спогреба́ються!","Ра́дуйся, із него́же креще́ннії, уме́рши гріху́, к но́вій жи́зні со Христо́м совостаю́ть!","Ра́дуйся, я́ко пред тобо́ю от благода́ті воскресе́нія, в тебі́ почі́ющей, вся крі́пость а́да ісчеза́єть!","Ра́дуйся, я́ко із тебе́, от полноти́ си́ли Бо́жієй, на тебі́ я́вльшейся, заря́ жи́зні ві́чния незаходи́мо сія́єть!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 13","ps":["О, пресвяти́й і живоно́сний гро́бі Христо́в, утіше́ніє ро́да челові́чеськаго і всея́ землі́ украше́ніє! Тебі́, я́ко черто́гу Царя́ сла́ви, ми́сленні с ві́рою предстоя́ще, мо́лимся к тридне́вно воскре́сшему із тебе́ Христу́ Бо́гу на́шему, во є́же ізба́витися нам от враг ви́димих і неви́димих, от бід вре́менних і ві́чних, па́че же от страсте́й і гріхо́в на́ших, да, совоскре́сше Єму́ покая́нієм, в обновле́нії пра́вия жи́зні ходи́ти на́чнем, благода́рні зову́ще: Аллилу́я!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с небесе́ низше́д, ка́мень от гро́ба Твоєго́ отвали́, Христе́ Бо́же, і мироно́сицям благовісти́ воста́ніє Твоє́, глаго́ля: «ше́дше, рці́те ученико́м Єго́, я́ко воста́ от ме́ртвих»; они́ же, вразумле́нниє чу́дним явле́нієм, зря́ще ко гро́бу Твоєму́, с ві́рою і любо́вію возглаша́ху:","Ра́дуйся, живоно́сний гро́бі, в не́мже Христо́с, я́ко челові́к, почи́, і я́ко Бог, воскре́се тридне́вен!","Ра́дуйся, я́ко із тебе́ Спас ми́ра, я́ко Жени́х із черто́га ізше́д, смерть попра́ і а́да пліни́л єсть!","Ра́дуйся, я́ко воста́нієм Того́, от ві́ка уме́ршії, в жизнь нестарі́ємую воста́ша!","Ра́дуйся, я́ко в тебі́ Христу́ возле́гшу, прокля́тая в ді́ліх челові́ка земля́ освяти́ся!","Ра́дуйся, я́ко тобо́ю первозда́нний Ада́м па́ки в ри́зу безсме́ртія облека́ється!","Ра́дуйся, я́ко в тебі́ о́браз всеми́рнаго воскресе́нія начертава́ється!","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Кондак 1","ps":["Возбра́нному Воєво́ді, разруши́телю сме́рти і а́да, побі́дную піснь Тебі́, Всецарю́ Христе́, прино́сим, я́ко воста́л єси́, Всеси́льне, со сла́вою тридне́вен от гро́ба і вся уме́ршія от ві́ка совоскреси́л єси́; ми же, страда́нієм Твої́м ві́чния тлі ізба́вльшеся, к са́мому мі́сту погребе́нія Твоєго́ с весе́лієм і ра́достію зове́м:","Ра́дуйся, живоно́сний гро́бі, із него́же Христо́с воскре́се!"]},{"h":"Молитва до Господа Ісуса, що воскрес","ps":["Сла́ва Тебі́, Го́споди Ісу́се Христе́, Бо́же мой, я́ко па́ки сподо́бил м'я єси́ недосто́йнаго, преше́дши по́прище свята́го поста́, поклони́тися Боже́ственним Страсте́м Твої́м і ви́діти всера́достний день пресла́внаго із гро́ба Воскресе́нія Твоєго́, в о́ньже свободи́л єси́ су́щия во а́ді от вік св'я́занния ду́ші пра́ведних. Тоя́ Боже́ственния свобо́ди ду́ха і пло́ті, дража́йший Спаси́телю мой, і аз жела́ю, да разріши́ши м'я, свя́зана су́ща мно́гими гріхи́, і да сотвори́ши возсія́ти живоно́сному сві́ту Воскресе́нія Твоєго́ во мра́чній душі́ моє́й. Ви́жду бо безчи́сленния щедро́ти і неізрече́нноє человіколю́біє Твоє́, я́ко не то́чію от небитія́ в битіє́ м'я приве́л єси́, і о́браза Твоєго́ подо́бієм украси́в, всея́ до́льній тва́рі влади́ку поста́вил м'я єси́, но і посе́м па́дша с висоти́ і врагу́ порабо́тившася, не оста́вил єси́, но, іскупи́в м'я безці́нною Кро́вію Твоє́ю, благода́тію креще́нія снабди́л м'я єси́, да востеку́ на пе́рвоє достоя́ніє. Аз же, окая́нний, зап'я́т бив умо́м плотськи́м, обрати́хся всп'ять і па́ки раб сотвори́хся гріха́ і страсте́й, доне́ліже єди́н по єди́ному погуби́х все да́ри благода́ті Твоєя́. І ни́ні у́бо, что сотворю́, не вім; оба́че пом'яну́в глаго́ли пречи́стих уст Твої́х, я́ко не прише́л єси́ призва́ти пра́ведники, но грі́шники в покая́ніє, і аз, я́ко єди́н от сих, с ві́рою і смире́нієм прихожду́ к живоно́сному гро́бу Твоєму́, не арома́ти і воню́ ми́ра нося́й, (наг бо єсьм і пуст благи́х діл,) но па́че наде́жду іми́й обрісти́ в нем проще́ніє гріха́м мої́м і обновле́ніє нечи́стому житію́ моєму́. При́зри у́бо на м'я, ка́ющася і служи́ти Тебі́ хотя́ща, і не отри́ни от благода́ті Воскресе́нія Твоєго́! Живоно́сною сме́ртію Твоє́ю і погребе́нієм умертви́ моя́ лю́тия стра́сті, да, я́ко мертв і погребе́н, живу́ в ми́рі сем. Пресла́вним воста́нієм Твої́м воздви́гни мою́ ду́шу, умерщвле́нную гріхми́, і оживи́ со́вість, єя́же нічто́же в ми́рі ну́жнійши єсть. Вознесе́нієм Твої́м отто́ргни м'я от су́єтних і душетлі́нних благ земни́х, і сотвори́ м'я го́рняя му́дрствовати, я́ко да не ктому́ себі́ жив'я́ і угожда́я, но Тебі́, Го́споду і Бо́гу моєму́, служа́ і рабо́тая, я́коже сподо́бихся поклони́тися Воскресе́нію Твоєму́ на землі́, та́ко сподо́блен бу́ду ви́діти Тебе́, дража́йшаго Іскупи́теля моєго́, і на небесі́, за прия́тіє сме́рті кре́стния сла́вою і че́стію вінча́нна, і став одесну́ю вели́чествія Твоєго́, со арха́нгели і а́нгели, і со всі́ми іскупле́нними Тобо́ю бра́тіями мої́ми, во ві́ки віко́в пою́ Тебі́: Аллилу́я! Амі́нь."]},{"h":"Тропар, глас 5","ps":["Христо́с воскре́се із ме́ртвих, / сме́ртію смерть попра́в, // і су́щим во гробі́х живо́т дарова́в."]},{"h":"Кондак, глас 8","ps":["А́ще і во гроб снизше́л єси́ Безсме́ртне, / но а́дову разруши́л єси́ си́лу, і воскре́сл єси́ я́ко побіди́тель Христе́ Бо́же, / жена́м мироно́сицям віща́вий, ра́дуйтеся: / і Твої́м апо́столом мир да́руяй, // па́дшим подая́й воскресе́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / нас ра́ди во ад сше́дшаго / і с Собо́ю вся // воскреси́вшаго."]}],"notes":[]},{"u":"Акафіст Нерукотворному Образу Господа нашого Ісуса Христа","e":"Akathist to the Image of our Lord Jesus Christ Not Made by Hands","secs":[{"h":"Кондак 1","ps":["Пречи́стому Твоєму́ О́бразу покланя́ємся, Благи́й, прося́ще проще́нія прегріше́ній на́ших, Христе́ Бо́же, во́лею бо благоволи́л єси́ пло́тію взи́ти на Крест, да ізба́виши, я́же созда́л єси́, от рабо́ти вра́жия, тім с наде́ждою вопіє́м Ті:","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Ікос 1","ps":["«Ісу́се, Спаси́телю мой, – моли́л смире́нно А́вгар князь Єде́ський, – прийди́ ко мні і ісціли́ неісці́льния болі́зні моя́, в ни́хже от мно́гих літ стражду́». Єму́ же подража́я, і аз, пораженний гріхо́вною прока́зою, мольбо́ю вопію́ си́це:","Го́споди мой, Го́споди, поми́луй м'я по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́.","Го́споди Спаси́телю мой, росо́ю ми́лості Твоє́й оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я.","Го́споди, отврати́ лице́ Твоє́ от гріх мої́х і вся беззако́нія моя́ очи́сти.","Го́споди, се́рдце чи́сто сози́жди во мні і дух прав обнови́ во утро́бі моє́й.","Го́споди, не отве́ржи мене́ от лиця́ Твоєго́ і Ду́ха Твоєго́ Свята́го не отими́ от мене́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 2","ps":["Ви́дя любо́в і ві́ру А́вгаря Єде́ськаго, Го́споди, Ти писа́л єси́ єму́ «Блаже́н єси́ А́вгар, не ви́дівий М'я і веровий в М'я. Аз пошлю́ ученика́ Моєго́ і той ісціли́ть тя і жизнь ві́чную пода́сть ті і су́щим с тобо́ю». Посли́ же, Го́споди, ми́лость Твою́ і мні вопію́щему: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум не постига́єть та́йни, как Госпо́дь приложе́нієм к Боже́ственному ли́ку Своєму́ убру́са, ізобрази́ на нем подо́біє Своє́, посила́ше о́ноє к А́вгарю, жела́ніє того́ ісполня́я. Сей же ра́дости вели́кой іспо́лнься, поклони́ся о́бразу Христо́ву. Єму́же і ми с благогові́нієм днесь поклоня́ємся, с мольбо́ю і ві́рою зову́ще:","Го́споди мой, Го́споди, устні́ моя́ отверзиши, і уста́ моя́ возвістя́ть хвалу́ Твою́, Го́споди мой, Го́споди, возврати́ мі ра́дость спасе́нія і Ду́хом Влади́чним утверди́ м'я.","Го́споди, Тебі́ Єди́ному согріши́х і лука́воє пред Тобо́ю сотвори́х, по ми́лості Твоє́й пощади́ м'я.","Го́споди мой, Го́споди, Спаси́телю мой, при́зри на скорб душі́ моєя́ і поспіши́ на по́мощ мні.","Го́споди мой, Го́споди, усли́ши м'я і от всіх скорбе́й ізба́ви м'я.","Го́споди Бо́же, Спаси́телю мой, прийди́, ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 3","ps":["Си́лою любве́ і ра́дости преіспо́лненний поклони́ся А́вгар Нерукотворе́нному о́бразу Спаси́теля ми́ра і, получи́в свої́х болі́зней ісціле́ніє, с ві́рою воззва́ «Христе́ Бо́же, всяк упова́ющий на Тя не постиди́ться». Сим поуча́я і нас всегда́ упова́ти на ми́лости Госпо́дні і пі́ти Єму́: Аллилу́я!"]},{"h":"Ікос 3","ps":["Імі́я любо́в к па́дшему ро́ду челові́чеському, Ти, Христе́ Бо́же, чрез єди́наго от ученико́в Твої́х воззва́л єси́ А́вгаря от мра́ка греховного і просвіти́л ду́шу єго́ сві́том і́стини Твоєя́. Воззови́ і меня от глубини́ гріхо́вния, да і аз с пла́чем возопію́ Тебі́ си́це:","Го́споди мой, Го́споди, да́руй мі сле́зи умиле́нія, да і́ми Тя умолю́ – очи́сти пре́жде конця́ вся моя́ прегріше́нія.","Го́споди, просвіти́ мою́ ду́шу сві́том Твоєго́ Боже́ственнаго позна́нія, і введи́ м'я по ми́лості Твоє́й в Ца́рство Твоє́.","Го́споди мой, Го́споди, просвіще́ніє моє́ і Спаси́тель мой, к Тебі́ прибіго́х, научи́ м'я твори́ти во́лю Твою́.","Го́споди мой, Го́споди, Бо́же мой, вразуми́ се́рдце моє́, і отжени́ от него́ іскуше́ніє лука́ваго, і наста́ви м'я на путь спасе́нія.","Го́споди мой, Го́споди, не отри́ни у́бо моле́нія моєго́ і усли́ши м'я, Твоє́ю Бла́гостію утверди́ се́рдце моє́ стра́хом Твої́м.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 4","ps":["Бу́ря страсте́й і треволне́ній жите́йських потопля́єть м'я, і се́рдце, об'ятоє у́жасом сме́рті, вопіє́ть Ті: Го́споди, ність помога́ющаго мі на землі́, спаси́ м'я, я́коже дре́вле А́вгаря, і да́руй ку́пно с ним пі́ти Ті: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша, я́ко іуде́є ненави́дять Тя, і хо́щуть ні́что зло́є соді́яти Тебі́, Го́споди, пи́шеть А́вгар: «Аз молю́: прийди́ ко мні і обита́й со мно́ю». Того́ любві́ подража́я, і аз, восстав із глубини́ паде́нія моєго́, дерзнове́нно молю́ Тя, Христе́ Бо́же, си́це:","Го́споди Бо́же мой, вни́ди в дом душі́ моєя́ і пребу́ди неотлуче́н со мно́ю грі́шним.","Го́споди, Бо́же се́рдця моєго́, прийди́ і соєдини́ м'я с Тобо́ю на ві́ки.","Го́споди мой, Го́споди, к Тебі́ прилепилась єси́ душа́ моя́, прийди́ і ра́дости іспо́лни се́рдце моє́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 5","ps":["Благослове́н гряди́й во і́м'я Госпо́днє – воспіва́ху дре́вле ді́ти єврейськії, встречая Го́спода в Ієрусали́мі. Ми же днесь, раскривая две́рі серде́ць на́ших гряду́щему к нам Спа́су, со умиле́нієм зове́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ди́вния глаго́ли Ти рекл єси́, Го́споди, всім погиба́ющим: «Да не смуща́ється се́рдце ва́ше, і да не устраша́ється, ві́руяй в Бо́га, і в Мене́ ві́руйте і наслі́діте Ца́рство, угото́ванноє вам от созда́нія ми́ра». Аз же, помишля́я своє́ беззако́ніє, молю́ Тя, Бла́же, утверди́ се́рдце моє́ і просвіти́ ум мой, Тебі́ вопію́щий:","Го́споди мой, Го́споди, при́зри на м'я і просвіти́ о́чі мої́, да не усну́ в смерть.","Го́споди мой, Го́споди, путеводя́ Ізра́їля от землі́ фараоновой, наста́ви м'я на путь Твой, да пойду́ во і́стині Твоє́й.","Го́споди Ісу́се Христе́, Си́не Бо́жий, ві́рую в Тя, помози́ моєму́ неві́рію.","Го́споди мой, Го́споди, да не я́ростію Твоє́ю обличи́ши мене́, і не удаля́йся от мене́ за беззако́нія моя́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния"]},{"h":"Кондак 6","ps":["Воззрі́ти очи́ма на о́браз Твой, Го́споди, не смі́ю окая́нний аз от лука́вих мої́х дія́нії, но я́ко мита́р, стеня́, взива́ю Ті: Бо́же, очи́сти м'я грі́шнаго от фарисе́йськаго лицемі́рія і научи́ чи́стим се́рдцем пі́ти милосе́рдію Твоєму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в ско́рбі моє́й утешительноє сло́во Твоє́, Спаси́телю мой, є́же рекл єси́: «Не оста́влю вас си́ри, прийду́ к вам». Того́ ра́ди аз, ізбі́гши темноту́ отча́янія, с наде́ждою на Твоє́ человіколю́біє прибіго́х к Тебі́ си́це моля́ся:","Го́споди мой, Го́споди, Прибі́жище моє́ в біді́ і в ско́рбі, не оста́ви м'я єди́на.","Го́споди мой, Го́споди, безгрі́шний, с беззако́нними вмененний, ізми́ м'я от рук ненави́дящих м'я.","Го́споди мой, Го́споди, от поруга́нія ви́димих і неви́димих враго́в сохрани́ м'я.","Го́споди мой, Го́споди, прости́ м'я і прийми́ м'я, я́коже блу́днаго дре́вле во об'я́тія Твоя́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 7","ps":["Ди́вния показа́л єси́ діла́ Твоя́, Го́споди, впречистем о́бразі Твоє́м і чудности дарова́л утіше́ніє всім земноро́дним, научи́в їх в ско́рбних обстояніях жи́зні прибіга́ти к Твоєму́ милосе́рдію і пі́ти Тебі́ с любо́вію: Аллилу́я."]},{"h":"Ікос 7","ps":["Храм нося́й тіле́сний весь оскверне́н, мно́жество соді́янних мно́ю лю́тих, трепе́щу стра́шнаго Су́днаго дне і молю́: покая́нія отве́рзи мі две́рі, Жизнода́вче, і я́ко Дави́д вопію́ Ті:","Го́споди мой, Го́споди, усли́ши моле́ніє моє́, внемли́ моли́тві моє́й і поми́луй м'я.","Го́споди Бо́же мой, Твой єсьм аз, вразуми́ м'я і жива́ бу́деть душа́ моя́.","Го́споди Бо́же мой, па́стирю мой, заблуди́х, я́ко овча́ поги́бшая, взищи́ раба́ Твоєго́ і спаси́ м'я.","Го́споди мой, Го́споди, поми́луй м'я, ісціли́ ду́шу мою́, я́ко согріши́х Тебі́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 8","ps":["Стра́шнаго дне прише́ствія Твоєго́ ужаса́юся, Христе́, і трепе́щу, я́ко іми́й мно́жество согріше́ній, но Ти, Ми́лостивий Бо́же, пре́жде конця́ обрати́ м'я, поющего Ті: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ любо́в к падшим челові́ком, о Ісу́сі, і дарова́л єси́ їм о́браз Твой Святи́й, я́сно глаго́лющий всім в ско́рбі і печа́лі су́щим: «Прийді́те ко Мні, всі тружда́ющіїся і обремене́ннії, і Аз упоко́ю ви». Сего́ ра́ди погиба́ющий, со дерзнове́нієм молю́ Тя, Христе́, си́це глаго́ля:","Го́споди мой, Го́споди, храни́телю мой, сохрани́ м'я от враго́в, напа́дающих на м'я.","Го́споди мой, Го́споди, во ви́шніх живи́й і на смире́нния призира́яй, при́зри на м'я грі́шнаго і бу́ди отрадой моє́й.","Го́споди мой, Го́споди, спаси́ м'я, утопа́ющаго в пучи́ні жите́йських іскуше́ній.","Го́споди мой, Го́споди, да не смуща́ється се́рдце моє́ і да не устраша́ється во іспові́данії і́мені Твоєго́.","Го́споди мой, Го́споди, прийми́ м'я, я́ко митаря́, я́ко Ханане́ю поми́луй, поми́луй м'я по ми́лості Твоє́й.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему, і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 9","ps":["Всі язи́ци, прийді́те, с любо́вію і тре́петом поклоні́мся пречи́стому о́бразу Спаси́теля ми́ра, ізба́вльшему нас от рабо́ти вра́жия і благода́рственно вопіє́м Єму́, Побіди́телю сме́рти і а́да: Аллилу́я."]},{"h":"Ікос 9","ps":["Весь пораженний прока́зою гріхо́вною, недоуміва́ю, ка́ко єсть досто́йно велича́ти Тя, о Влади́ко многоми́лостивий, но ві́рою серде́чною іспові́дую Тя, і́стиннаго Си́на Бо́жия, смире́нно стою́ пред о́бразом Твої́м Святи́м, си́це моля́ся:","Го́споди Ісу́се, Ра́досте моя́, даждь мі, да возра́дуюся о ми́лості Твоє́й.","Го́споди, Спаси́телю мой Преблаги́й, спаси́ раба́ Твоєго́ от неві́рія і беззако́нія.","Го́споди мой, Го́споди, Ми́лость неізрече́нная, благода́тію Твоє́ю потреби́ гнів в се́рдці моє́м.","Го́споди мой, Го́споди, чистота́ неопи́санная, чистоту́ се́рдця і ума́ даждь мі.","Го́споди мой, Го́споди, одія́йся сві́том я́ко ри́зою, освяти́ м'я, печалями жите́йськими омраче́ннаго.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 10","ps":["Го́споди мой, Го́споди, милосе́рдий Спаси́телю мой, ду́шу мою́ сту́дними дія́ніями лю́ті разсла́бленную воздви́гни Боже́ственним Твої́м милосе́рдієм, я́коже дре́вле разсла́бленнаго при о́вчей купі́лі, і на спасе́нія стезі́ наста́ви ю, да поє́м Ті: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Предві́чний, Уті́шителю, Христе́ І́стинний, очи́сти м'я от вся́кия скве́рни, я́коже очи́стил єси́ де́сять прокаже́нних і ісціли́ м'я, я́коже ісціли́л єси́ сребролюби́вую ду́шу Закхея митаря́, да воспою́ Ті, си́це глаго́ля:","Го́споди мой, Го́споди, неду́ги на́ша приє́мий і болі́зні понеси́й, ісціли́ болі́зні се́рдця моєго́.","Го́споди мой, Го́споди Ісу́се, Помо́щниче мой, помози́ мі, я́ко ізнемога́єть душа́ моя́ от ско́рби сея́.","Го́споди мой, Го́споди, о́чі да́вий сліпо́му во є́же ви́діти, даждь мі о́ко, да узрю́ кро́тость і терпі́ніє Твоє́.","Го́споди долготерпіли́вий, ізба́ви ду́шу мою́ от нечести́ваго і спаси́ м'я ра́ди ми́лости Твоєя́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє Тебі́ принося́ща, і сокруше́нним се́рдцем моля́щася, не пре́зри м'я, о Преблаги́й Влади́ко! Отврати́ у́бо лице́ Твоє́ от гріх мої́х! Но не отврати́ лиця́ Твоєго́ от раба́ пою́щаго Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Христе́ Сві́те і́стинний, просвіща́яй і освяща́яй вся́каго челові́ка гряду́щаго в мир, при́зри на м'я, грі́шнаго і непотре́бнаго раба́ Твоєго́ і іспра́ви жизнь мою́ по за́повідям Твої́м, і ду́шу мою́ освяти́, да принесу́ Ті моли́тву си́це:","Го́споди Ісу́се Христе́, Ти Світ ми́ра, сві́том Твої́м осія́й м'я.","Го́споди мой, Го́споди, Ти істо́чник жи́зні, да́руй душе́ моє́й жизнь нетлі́нную і утверди́ ю в за́повідіх Твої́х.","Го́споди Ісу́се Христе́, Ти Со́лнце пра́вди, пра́вдою Твоє́ю согрі́й ду́шу мою́ і озари́ ум мой.","Го́споди мой, Го́споди, Ти наста́вник мой, научи́ м'я твори́ти во́лю Твою́ і люби́ти Тя всім се́рдцем.","Го́споди мой, Го́споди, Ти отве́рзл єси́ о́чі сліпо́му, отве́рзи і мні две́рі покая́нія і, я́ко щедр, очи́сти вся гріхи́ моя́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 12","ps":["Благода́тію Твоє́ю всеси́льною, утверди́ се́рдце моє́ во ві́рі, наде́жде і любві́, да́руй мі покая́нієм і неослабленним ісполне́нієм за́повідей Твої́х достигнуть Ца́рствія Небе́снаго, іді́же с ли́ки апо́стольськими воспою́: Ті Аллилу́я."]},{"h":"Ікос 12","ps":["Ти, Па́стирю до́брий, рекл єси́ всім, в ско́рбі і печа́лі су́щим: «Дру́зі Мої́, Аз іду́ ко Отцю́ Моєму́ і Отцю́ ва́шему угото́вати мі́сто вам, но па́ки прийду́ і возьму вас к Себі́, а́ще за́повіді Моя́ соблюдаєте». Сему́ благогові́йно внима́я, дерзну́ і аз, погруже́нний в лю́тую скорб, приступи́ти к Тебі́, си́це моля́ся:","Го́споди мой, Го́споди, милосе́рдий Спаси́телю мой, спаси́ м'я погиба́ющаго.","Го́споди мой, Го́споди, отжени́ от мене́ ту́чі неві́рія, зла і вражди́ і Ду́хом Твої́м Благи́м наста́ви м'я на путь пра́вди.","Го́споди мой, Го́споди, утіше́ніє душі́ моєя́, уті́ши м'я в печа́лі су́щаго.","Го́споди Бо́же мой, і́мене ра́ди Твоєго́, оживи́ м'я і пра́вдою Твоє́ю ізведи́ із печа́лі ду́шу мою́.","Го́споди, Царю́ Преси́льний, пом'яни́ м'я, єгда́ при́йдеши во Ца́рствії Твоє́м.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 13","ps":["О, Премилосе́рдий і Преблаги́й Го́споди Бо́же, Спаси́телю мой, прише́дий в мир для спасе́нія па́дшаго челові́ка, не возгнуша́йся мене́ па́че всіх челові́к прегріши́вшаго і не отврати́ от мене́ лиця́ Твоєго́, но при́зри на лю́тую скорб і печа́ль душі́ моєя́, ісціли́ і утверди́ в сві́ті і́стини і любве́, да поє́м Ті: Аллилу́я!","О Спа́се мой Премилосе́рдий, прише́дий в мир для спасе́нія па́дшаго челові́ка, взищи́ м'я погиба́ющаго і благода́тію Твоє́ю ду́шу мою́ освяти́, ті́ло очи́сти і жизнь іспра́ви по за́повідем Твої́м, да воспою́ Ті чи́стим се́рдцем: Аллилу́я.","О Спа́се Мой Преми́лостивий, при́зри на раба́ Твоєго́, утопа́ющаго в мо́рі жите́йських іскуше́ній і бід, і, я́ко же дре́вле Петра́ утопа́юща, спаси́ благода́тію Твоє́ю, освяти́ ду́шу і утверди́ на стезі́ за́повідей Твої́х, да чи́стим се́рдцем і усти́ вопію́ Ті с любо́вію: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["«Ісу́се, Спаси́телю мой, – моли́л смире́нно А́вгар князь Єде́ський, – прийди́ ко мні і ісціли́ неісці́льния болі́зні моя́, в ни́хже от мно́гих літ стражду́». Єму́ же подража́я, і аз, пораженний гріхо́вною прока́зою, мольбо́ю вопію́ си́це:","Го́споди мой, Го́споди, поми́луй м'я по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́.","Го́споди Спаси́телю мой, росо́ю ми́лості Твоє́й оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я.","Го́споди, отврати́ лице́ Твоє́ от гріх мої́х і вся беззако́нія моя́ очи́сти.","Го́споди, се́рдце чи́сто сози́жди во мні і дух прав обнови́ во утро́бі моє́й.","Го́споди, не отве́ржи мене́ от лиця́ Твоєго́ і Ду́ха Твоєго́ Свята́го не отими́ от мене́.","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Кондак 1","ps":["Пречи́стому Твоєму́ О́бразу покланя́ємся, Благи́й, прося́ще проще́нія прегріше́ній на́ших, Христе́ Бо́же, во́лею бо благоволи́л єси́ пло́тію взи́ти на Крест, да ізба́виши, я́же созда́л єси́, от рабо́ти вра́жия, тім с наде́ждою вопіє́м Ті:","Го́споди Бо́же, Спаси́телю мой, прийди́ ко мні погибающему і ісціли́ болі́зні моя́ неісці́льния."]},{"h":"Молитва перша","ps":["Го́споди Ще́дре і Ми́лостиве, Долготерпіли́ве і Многоми́лостиве, внуши́ моли́тву на́шу і воньми́ гла́су моле́нія на́шего, сотвори́ с на́ми зна́меніє во бла́го, наста́ви нас на путь Твой, є́же ходи́ти во і́стині Твоє́й, возвесели́ сердця́ на́ша, во є́же боя́тися І́мене Твоєго́ свята́го. Зане́ ве́лій єси́ Ти і творя́й чудеса́, Ти єси́ Бог єди́н, і ність подо́бен Тебі́ в бозі́х, Го́споди, си́лен в ми́лості і благ в крі́пості, во є́же помога́ти і утіша́ти і спаса́ти вся упова́ющия на І́м'я свято́є Твоє́. Амі́нь."]},{"h":"Молитва друга","ps":["О, Преблаги́й Го́споди Ісу́се Христе́, Бо́же наш! Ти іногда́ челові́чеськаго о́браза Твоє́ лице́ пресвято́є оми́во водо́ю і оте́р убру́сом, чуде́сне о́ноє на том же убру́сі ізобрази́ти і Єде́ському кня́зю Авга́рю во ісціле́ніє неду́га єго́ посла́ти благоволи́л єси́: се і ми ни́ні, грі́шнії раби́ Твої́, одержи́мії душе́вними і тіле́сними неду́ги на́шими, лиця́ Твоєго́, Го́споди, і́щем і с Дави́дом во смире́нії душ на́ших зове́м: не отврати́ лиця́ Твоєго́ от нас, і уклони́ся гні́вом от рабо́в Твої́х: помо́щник нам бу́ди, не отри́ни нас і не оста́ви нас. О, всеми́лостивий Го́споди, Спаси́телю наш! Ізобрази́ Сам Себе́ в душа́х на́ших, да, во святи́ні і пра́вді жи́тельствующе, бу́дем си́нове Твої́ і наслі́дници ца́рствія Твоєго́, і та́ко Тебі́, преми́лостиваго Бо́га на́шего, ку́пно со безнача́льним Отце́м Твої́м і Пресвяти́м Ду́хом, сла́вити не преста́нем во ві́ки. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Пречи́стому Твоєму́ о́бразу покланя́ємся, Благи́й, / прося́ще проще́нія прегріше́ній на́ших, Христе́ Бо́же: / во́лею бо благоволи́л єси́ пло́тію взи́ти на Крест, / да ізба́виши я́же созда́л єси́ от рабо́ти вра́жия. / Тім благода́рственно вопіє́м Ті: / ра́дости іспо́лнил єси́ вся, Спа́се наш, // прише́дий спасти́ мир."]},{"h":"Кондак, глас 2","ps":["Неізрече́ннаго і Боже́ственнаго Твоєго́ к челові́ком смотре́нія, / неопи́санноє Сло́во О́тчеє, / і о́браз непи́санний, і богопи́санний побіди́телен, / ві́дуще нело́жнаго Твоєго́ воплоще́нія, // почита́єм, того́ лобиза́юще."]},{"h":"Величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і почита́єм пречи́стаго лиця́ Твоєго́ // пресла́вноє воображе́ніє."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Живода́вче Христе́, / і чтим о́браз Твой Святи́й, / і́мже нас спасл єси́ // от рабо́ти вра́жия."]}],"notes":[]},{"u":"Акафіст Покрову Пресвятої Богородиці","e":"Akathist to the Protection of the Most Holy Theotokos","secs":[{"h":"Кондак 1","ps":["Ізбра́нній предві́чним Царе́м, преви́шшей вся́каго созда́нія, небесе́ і землі́ Цари́це, прише́дшей іногда́ во Влахе́рнськую це́рков на моли́тву, досто́йноє поклоне́ніє с благодаре́нієм принося́ще, я́ко во тьмі су́щії, под Твой світя́щийся омофо́р с ві́рою і умиле́нієм прибіга́єм. Ти же, я́ко іму́щи держа́ву непобіди́мую, от вся́ких нас бід свобожда́й, да зове́м Ті:","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Ікос 1","ps":["Арха́нгел і а́нгел мно́жество, с Предте́чею, Богосло́вом і всіх святи́х ли́ком сопредста́ша Тебі́, Цари́це своє́й, в це́ркві Влахе́рнстій і, умиле́нная моле́нія Твоя́ о всем ми́рі сли́шавше, со удивле́нієм возопи́ша такова́я:","Ра́дуйся, Бо́га Отця́ безнача́льнаго предві́чноє благоволе́ніє;","ра́дуйся, Бо́га Си́на безлі́тнаго пречи́стоє вмісти́лище.","Ра́дуйся, Бо́га Ду́ха Всесвята́го ізбра́нноє жили́ще;","ра́дуйся, го́рних чино́в а́нгельських непрестаю́щеє удивле́ніє.","Ра́дуйся, те́мних сил а́дських всегро́зноє устраше́ніє;","ра́дуйся, Ю́же на возду́сі сріта́ють многоочи́тії херуви́ми.","Ра́дуйся, Є́йже похва́льная воспису́ють шестокрила́тії серафи́ми;","ра́дуйся, Єя́же преблаго́му покро́ву і ми, земноро́днії, благода́рні покланя́ємся.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 2","ps":["Ви́дівше Тя святи́й Андре́й со Єпифа́нієм в це́ркві на возду́сі за христия́ни Бо́гу моля́щуюся, позна́ша, я́ко Ма́тер єси́ возне́сшагося на не́бо Христа́ Бо́га на́шего, і, припа́дше на зе́млю, ра́достно покланя́хуся всеблаго́му покро́ву Твоєму́, зову́ще: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий єси́, Богоро́дице Ді́во, в защище́нії люде́й правосла́вних, сего́ ра́ди вразі́ на́ші і не познаю́ть, коль сильна́ єсть моли́тва Бо́жия Ма́тере. Ми же, о Твоє́м всемо́щнім заступле́нії до́брі ві́дуще, си́це к Тебі́ со умиле́нієм зове́м:","Ра́дуйся, премилосе́рдая уті́шительнице всіх скорб'я́щих і обремене́нних;","ра́дуйся, неусипа́ющая наста́внице всіх заблу́ждших і осліпле́нних.","Ра́дуйся, пра́ведно дви́жимий гнів Бо́жий на нас Твої́м моле́нієм ско́ро утоля́ющая;","ра́дуйся, зли́я стра́сті на́ша всемо́щним манове́нієм укроща́ющая.","Ра́дуйся, крі́пкоє возбужде́ніє спя́щих со́вістей;","ра́дуйся, нетру́дноє преодолі́ніє беззако́нних на́виков.","Ра́дуйся, Єя́же ра́ди ад стене́т і ду́си зло́би трепе́щуть;","ра́дуйся, Єя́же ра́ди врата́ рая́ всім нам отверза́ються.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́єть с ві́рою і благогові́нієм прибіга́ющих к Твоєму́ всечестно́му покро́ву: єди́ній бо то́чію Тебі́, Пресвяті́й і Пречи́стій Ма́тері Бо́жієй, даде́ся, да вся́коє проше́ніє Твоє́ іспо́лниться. Тім у́бо всяк во́зраст ві́рних славосло́вить Тя і Си́на Твоєго́, зову́щ: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія неоску́дноє, всім конце́м землі́ простира́єши ру́ку по́мощі, Влади́чице: боля́щим — ісціле́ніє, стра́ждущим — осла́бу, сліпи́м — прозрі́ніє і всім вся, по коєго́ждо потре́бі подає́ши, благода́рні вопію́щим:","Ра́дуйся, правосла́вія несокруши́мая крі́посте і огра́до;","ра́дуйся, святи́х хра́мов і олтаре́й пе́рвійшеє украше́ніє.","Ра́дуйся, благоче́стія вірні́йшеє огражде́ніє;","ра́дуйся, благосе́рдих градоправи́телей неусипа́ющая споспі́шнице.","Ра́дуйся, непобіди́мая воєво́до вожде́й і во́їнств христия́нських;","ра́дуйся, свято́є зерца́ло пра́вди судія́м немздоприї́мним.","Ра́дуйся, соверше́нний ра́зуме наста́вников і дітоводи́телей;","ра́дуйся, благослове́ніє домо́в і семе́йств благочести́вих.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 4","ps":["Бу́рею мно́гих бід одержи́мим нам помога́єши, Влади́чице: стої́ши бо пред лице́м олтаря́ Госпо́дня, воздви́гши ру́ці Твої́ і мо́лишися, я́ко да на́шу недосто́йную моли́тву при́зрить Госпо́дь, Цар сла́ви, і послу́шаєть проше́нія призива́ющих і́м'я Твоє́ свято́є, к Си́ну же Твоєму́ зову́щих: Аллилу́я."]},{"h":"Ікос 4","ps":["Усли́ша Госпо́дь Бог Ісу́са Нави́на моля́щася, і повеліва́юща со́лнцю ста́ти, до́ндеже отмсти́ть враго́м. Сли́шить і Твоя́ ни́ні моле́нія Госпо́дь Ісу́с, ізбра́нная пала́то Ду́ха Свята́го. Ті́мже і ми, грі́шнії, на Твой наді́ющеся покро́в, Тебі́, я́ко Бо́жієй Ма́тері, глаго́лати дерза́єм:","Ра́дуйся, от Со́лнця ми́сленнаго озаре́нная і нас сві́том незаходи́мим просвіща́ющая;","ра́дуйся, сія́нієм пречи́стия душі́ Твоєя́ всю зе́млю просвіти́вшая.","Ра́дуйся, чистото́ю тілесе́ Твоєго́ вся небеса́ возвесели́вшая;","ра́дуйся, святи́х оби́телей Христо́вих покро́в і снабді́ніє.","Ра́дуйся, ві́рних па́стирей Це́ркве бо́дрость і вразумле́ніє;","ра́дуйся, богобоя́зненних і́ноков і і́нокинь наста́внице.","Ра́дуйся, невозмуща́ємоє успокоє́ніє благогові́йних ста́рцев;","ра́дуйся, та́йноє весе́ліє чи́стих дів і вдови́ць.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 5","ps":["Богови́дець Мойсе́й во ополче́нії іногда́ на Амали́ка, єгда́ ру́ці воздвиза́ше, Ізра́їль одоліва́ше, єгда́ же ру́ці низпуща́ше, тогда́ Амали́к побіжда́ше, поддержа́щими же єго́ укріпле́н, побіди́ врага́. Ти же, о Богома́ти, возді́вши ру́ці Твої́ на умоле́ніє, а́ще і ники́мже поддержи́ма, всегда́ побіжда́єши враги́ христия́нськия, і нам щит єси́ непобіди́м, вопію́щим: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше Тя святи́х собо́ри на возду́сі в це́ркві Влахе́рнстій, моле́бнії ру́ці к Си́ну і Бо́гу простира́ющую, ра́достно со арха́нгели і а́нгели благода́рную Ті піснь воспі́ша. Ми же кріпча́йшима, па́че Мойсе́ових рук, дла́ньма Твої́ма укріпля́ємі, уми́льно вопіє́м:","Ра́дуйся, Єя́же ру́ці поддержи́ть за всіх нас єди́ная Єя́ к нам любо́в і милосе́рдіє;","ра́дуйся, пред Не́юже вразі́ на́ша, ви́димії і неви́димії, стоя́ти не мо́гуть.","Ра́дуйся, те́мноє по́лчище страсте́й і по́хотей на́ших прогоня́ющая;","ра́дуйся, Огнь Боже́ственний — Христа́ неопа́льно на руку́ Своє́ю держа́щая і нас, хла́дних, тім воспламеня́ющая.","Ра́дуйся, во́їнствующих на плоть цілому́дрієм ізря́дноє вінча́ніє;","ра́дуйся, подвиза́ющихся в пості́ і безмо́лвії при́сноє собесі́дованіє.","Ра́дуйся, ізнемога́ющих от уни́нія і печа́лі ско́рая уті́шительнице;","ра́дуйся, благода́тію смире́нія і терпі́нія снабдіва́ющая.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 6","ps":["Пропові́дник неоскудіва́ємия благода́ті і ми́лостей Твої́х яви́ся святи́й Рома́н Сладкопі́вець, єгда́ от Тебе́ во сні прия́т сви́ток кни́жний на сніде́ніє: тім у́бо умудре́н, нача́ть разу́мно пі́ти во сла́ву Твою́, святи́м же писа́ти похва́льная, взива́я с ві́рою: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ от і́стиннаго Со́лнця пра́вди заря́, Ді́во Богоотрокови́це, просвіща́ющая всіх прему́дростію Бо́га, Си́на Твоєго́, і в позна́ніє і́стини приводя́щая зову́щих Ті такова́я:","Ра́дуйся, Бо́жию Си́лу і Бо́жию Прему́дрость — Христа́ пло́тію породи́вшая;","ра́дуйся, юро́дивую му́дрость ві́ка сего́ посрами́вшая, і осліпле́нних є́ю на путь пра́вий наставля́ющая.","Ра́дуйся, святи́я ві́ри охране́ніє і правосла́вних догма́тов наста́внице;","ра́дуйся, нечести́вих єресе́й і тлітво́рних раско́лов іскорени́тельнице.","Ра́дуйся, та́йная і неудо́б предви́дінная вся до́брі ві́дущая, і і́мже подоба́єть, сказу́ющая;","ра́дуйся, лжи́вих прови́дцев і су́єтная гада́нія посрамля́ющая.","Ра́дуйся, в час недоумі́ній мисль бла́гу на се́рдці полага́ющая;","ра́дуйся, от па́губних начина́ній і несми́сленних пожела́ній восп'яща́ющая.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 7","ps":["Хотя́й долготерпіли́вий Всеви́дець Госпо́дь яви́ти Своєго́ человіколю́бія неізслі́димую щедро́т бе́здну, ізбра́ Тебе́ єди́ну в Ма́тер Себе́, і сотвори́ Тя лю́дем непреодолі́нноє защище́ніє: да а́ще кто от них і пра́ведним судо́м Бо́жиїм осужде́нія досто́їн яви́ться, Твої́м оба́че держа́вним покро́вом сохраня́ється на покая́ніє, зови́й: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вная показа́л єси́ діла́ Твоя́ в Пречи́стій Ма́тері Твоє́й, Го́споди, єгда́ пречу́дний омофо́р в руці́ Єя́ світя́щийся па́че луч со́лнечних яви́ся, і́мже покрива́ше лю́ди, су́щия в це́ркві Влахе́рнстій. О такові́м у́бо зна́менії милосе́рдаго Єя́ заступле́нія усли́шавше, у́жасом і ра́достію одержи́ми, всі глаго́лаху:","Ра́дуйся, нерукотворе́нний омофо́р, а́ки о́блак, над всім ми́ром распросте́ршая;","ра́дуйся, Преві́чнаго Архієре́я, Си́на Своєго́, зна́меніє на руці́ Своє́й держа́щая.","Ра́дуйся, но́вую ми́лость і но́вую благода́ть сим в Це́ркві Правосла́вній явля́ющая;","ра́дуйся, сто́лпе о́блачний, от іскуше́ній і собла́знов ми́ра всіх нас покрива́ющий.","Ра́дуйся, сто́лпе о́гненний, среди́ мгли гріха́ всім нам путь спасе́нія показу́ющий;","ра́дуйся, я́вних благоче́стія подви́жников я́вноє укріпле́ніє.","Ра́дуйся, та́йних среди́ ми́ра рабо́в Бо́жиїх та́йноє вразумле́ніє;","ра́дуйся, і мене́, обнаже́ннаго до́брих діл, не оставля́ющая Свої́м покро́вом і благода́тію.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 8","ps":["Ди́вно Тя от небе́с во Влахе́рнстій це́ркві я́вльшуюся, а́нгели воспі́ша, апо́столи просла́виша, лик святи́телей і преподо́бних, і жен святи́х сосло́віє восхвали́ша, Предте́ча с Богосло́вом поклони́шася, лю́діє же, су́щії в це́ркві, с весе́лієм вопія́ху: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі́ми ви́шніми і ни́жніми влади́чествуя Госпо́дь, узрі́в Тя в це́ркві Ма́тер Свою́ стоя́щу і со умиле́нієм к Нему́ моля́щуюся, рече́: «проси́, Ма́ти Моя́, зане́ не отвращу́ся Тебі́, но іспо́лню вся проше́нія Твоя́ і благода́рственная си́це Тебі́ всіх пі́ти научу́»:","Ра́дуйся, ковче́же заві́та, в не́мже храни́ться освяще́ніє всего́ ро́да челові́чеськаго;","ра́дуйся, ста́мно пресвята́я, в не́йже а́лчущим пра́вди блюде́ться Хліб жи́зні ві́чния.","Ра́дуйся, сосу́де всезлати́й, в не́мже угото́вася нас ра́ди плоть і кров Боже́ственнаго А́гнця;","ра́дуйся, оста́вленних врача́ми на Свої́ всемо́щния ру́ці приє́млющая.","Ра́дуйся, разсла́бленних ті́лом, но не ду́хом і ві́рою, со одра́ болі́зні воздвиза́ющая;","ра́дуйся, погубля́ющим от неду́га ум, но́вий і лу́чшій смисл подаю́щая.","Ра́дуйся, на стро́потнім путі́ гріха́ і страсте́й нас прему́дре запина́ющая;","ра́дуйся, жесто́кость нераска́яннаго се́рдця на́шего умиля́ющая.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє похва́льная прино́сить Тебі́, і́стинній Бо́жієй Ма́тері і Засту́пнице всіх, притека́ющих к Тебі́, ві́дуще, я́ко несокруши́мим покро́вом Твої́м пра́ведних возвеселя́єши, грі́шних заступа́єши, бі́дствующих ізбавля́єши і мо́лишися о всіх ві́рних, зову́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії, я́ко ри́би безгла́сния, недоумі́ють, ка́ко восхвали́ти по достоя́нію вели́кий всечестна́го Покро́ва Твоєго́ пра́здник: вся бо о Тебі́ от них глаго́лемая не суть дово́льна к єди́ному ізчисле́нію щедро́т Твої́х. Ми же, Твоя́ неісче́тния благодія́нія ви́дяще, с весе́лієм взива́єм:","Ра́дуйся, от я́зви і всегуби́тельства сме́ртнаго нас соблюда́ющая;","ра́дуйся, от внеза́пнаго колеба́нія землі́ гра́ди і ве́сі сохраня́ющая.","Ра́дуйся, от разлія́нія вод і потопле́нія руко́ю крі́пкою возводя́щая;","ра́дуйся, от запале́нія о́гненнаго росо́ю моли́тв Твої́х ізбавля́ющая.","Ра́дуйся, от гла́да душе́внаго і тіле́снаго Хлі́бом Жи́зні снабдіва́ющая;","ра́дуйся, уда́ри мо́лнії і гро́ма от глави́ на́шея отводя́щая.","Ра́дуйся, от наше́ствія іноплеме́нник і та́йних уби́йць спаса́ющая;","ра́дуйся, от дома́шнія бра́ні і вражди́ єдинокро́вних ми́ром і любо́вію огражда́ющая.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й род челові́чеський от пре́лести вра́жия человіколю́бець Госпо́дь Тебе́, Ма́тер Свою́, дарова́ земни́м нам в по́мощ, покро́в і защи́ту, да бу́деши печа́льним утіше́ніє, скорб'я́щим ра́дованіє, оби́димим засту́пниця, і да всіх із глубини́ гріхо́вния воздви́гнеши, пою́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["«Царю́ Небе́сний — глаго́лаше в моли́тві на возду́сі со а́нгели стоя́щая Всенепоро́чная Цари́ця, — прийми́ вся́каго челові́ка, моля́щаяся к Тебі́ і призива́юща і́м'я Моє́ на по́мощ, да не оти́деть от ли́ка Моєго́ тощ і неусли́шан». Сію́ всеблагу́ю моли́тву сли́шавше, собо́ри святи́х благода́рні возопи́ша:","Ра́дуйся, чи́стих рука́ми і се́рдцем земледі́льцев благослове́нними плода́ми вінча́ющая;","ра́дуйся, по́моще і пра́ведноє мздовоздая́ніє всім пра́во ку́плю де́ющим.","Ра́дуйся, клятвопреступле́ній і непра́ведних стяжа́ній всенаро́дноє обличе́ніє;","ра́дуйся, бе́дствующим в путі́, на су́ші і вода́х внеза́пноє вспоможе́ніє.","Ра́дуйся, безча́дних роди́телей плода́ми ві́ри і ду́ха веселя́щая;","ра́дуйся, безма́терніх сиро́т незри́мая воспита́тельнице.","Ра́дуйся, крі́пкая засту́пнице су́щих в пліну́ і ізгна́нії;","ра́дуйся, неусипа́ющая попечи́тельнице во у́зах і темни́ці сідя́щих.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє сли́шаще і те́плій Твоє́й моли́тві о нас вне́млюще, про́сим Тебе́, Ді́во Богоро́дице, не пре́зри гла́са рабо́в Твої́х: к Тебі́ бо в напа́стіх і ско́рбіх прибіга́єм і пред Тобо́ю в біда́х на́ших сле́зи пролива́єм, зову́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко світоприє́мную свіщу́, в моли́тві горя́щую, ви́дяще Тя на возду́сі Влахе́рнськая це́рков, согла́сно со мно́жеством люде́й, в ней би́вших, возглаша́ше: «отку́ду мні сіє́, да при́йде Ма́ти Го́спода моєго́ ко мні?» Святи́й же Андре́й со Єпифа́нієм те́плі моля́хуся к Тебі́, зову́ще:","Ра́дуйся, всіх даро́в духо́вних і тіле́сних незави́стная пода́тельнице;","ра́дуйся, полага́ющих нача́ло покая́нія грі́шников ві́рная предста́тельнице.","Ра́дуйся, борю́щихся со страстьми́ і прило́гами вра́жіїми всегда́шняя спобо́рнице;","ра́дуйся, незри́моє укроще́ніє влади́к жесто́ких і звіронра́вних.","Ра́дуйся, та́йний поко́є і отра́до рабо́в кро́тких і стра́ждущих;","ра́дуйся, всежела́нноє соверше́ніє благи́х супру́жеств.","Ра́дуйся, ма́терей дітородя́щих ско́роє і безболі́зненноє разріше́ніє;","ра́дуйся, в час кончи́ни єди́ная всім нам помо́щнице.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ нам у Си́на Твоєго́ і Бо́га, простри́ нам ру́ку по́мощі, отжени́ от нас вся́каго врага́ і супоста́та, і умири́ на́шу жизнь, да не поги́бнем лю́ті, без покая́нія, но прийми́ нас во ві́чния кро́ви, Покрови́тельнице на́ша, да ра́дующеся Тебі́ зове́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твой держа́вний покро́в, хва́лим Тя всі, я́ко тве́рдую предста́тельницю на́шу, і покланя́ємся Тебі́, о нас моля́щейся: ві́руєм бо і наді́ємся, я́ко іспро́сиши у Си́на Твоєго́ і Бо́га блага́я ві́чная і вре́менная, всім с любо́вію вопію́щим Тебі́ си́це:","Ра́дуйся, всей вселе́нній крі́пкоє заступле́ніє;","ра́дуйся, всіх стихі́й земни́х і небе́сних освяще́ніє.","Ра́дуйся, всіх време́н го́да благослове́ніє;","ра́дуйся, всіх наві́тов і іскуше́ній от ми́ра, пло́ті і дия́вола находя́щих, попра́ніє.","Ра́дуйся, неча́ємоє примире́ніє ожесточе́нно вражду́ющих;","ра́дуйся, недові́домоє ісправле́ніє нераска́янних грі́шников.","Ра́дуйся, не отверга́ющая всі́ми презрі́нних і отве́рженних;","ра́дуйся, сами́х отча́янних от ро́ва поги́белі ісхища́ющая.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 13","ps":["О, всепі́тая Ма́ти, пречи́стая Госпоже́, Ді́во Богоро́дице! К Тебі́ возвожду́ душе́вния і тіле́сния о́чі, к Тебі́ простира́ю разсла́бленния ру́ці і із глубини́ се́рдця вопію́: при́зри на ві́ру і смире́ніє душі́ моєя́, покри́й м'я всемо́щним омофо́ром Твої́м, да ізба́влюся от всіх бід і напа́стей, і в час кончи́ни моєя́, о Всеблага́я, предста́ни мні і угото́ваннаго ра́ди гріхо́в мої́х ізба́ви муче́нія, да ви́ну покланя́яся зову́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел і а́нгел мно́жество, с Предте́чею, Богосло́вом і всіх святи́х ли́ком сопредста́ша Тебі́, Цари́це своє́й, в це́ркві Влахе́рнстій і, умиле́нная моле́нія Твоя́ о всем ми́рі сли́шавше, со удивле́нієм возопи́ша такова́я:","Ра́дуйся, Бо́га Отця́ безнача́льнаго предві́чноє благоволе́ніє;","ра́дуйся, Бо́га Си́на безлі́тнаго пречи́стоє вмісти́лище.","Ра́дуйся, Бо́га Ду́ха Всесвята́го ізбра́нноє жили́ще;","ра́дуйся, го́рних чино́в а́нгельських непрестаю́щеє удивле́ніє.","Ра́дуйся, те́мних сил а́дських всегро́зноє устраше́ніє;","ра́дуйся, Ю́же на возду́сі сріта́ють многоочи́тії херуви́ми.","Ра́дуйся, Є́йже похва́льная воспису́ють шестокрила́тії серафи́ми;","ра́дуйся, Єя́же преблаго́му покро́ву і ми, земноро́днії, благода́рні покланя́ємся.","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Кондак 1","ps":["Ізбра́нній предві́чним Царе́м, преви́шшей вся́каго созда́нія, небесе́ і землі́ Цари́це, прише́дшей іногда́ во Влахе́рнськую це́рков на моли́тву, досто́йноє поклоне́ніє с благодаре́нієм принося́ще, я́ко во тьмі су́щії, под Твой світя́щийся омофо́р с ві́рою і умиле́нієм прибіга́єм. Ти же, я́ко іму́щи держа́ву непобіди́мую, от вся́ких нас бід свобожда́й, да зове́м Ті:","Ра́дуйся, Ра́досте на́ша, покри́й нас от вся́каго зла честни́м Твої́м омофо́ром."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх сил, небесе́ і землі́ Цари́це, гра́да і страни́ на́шея всемо́щная Засту́пнице! Прийми́ хвале́бно-благода́рственноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, і вознеси́ моли́тви на́ші ко престо́лу Бо́га, Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим і проба́вить благода́ть Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію покланя́ющимся чудотво́рному о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостивиши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рой Засту́пниці на́шей: усли́ши нас, моля́щихся Тебі́, осіни́ нас вседержа́вним покро́вом Твої́м і іспроси́ у Бо́га, Си́на Твоєго́, па́стирем на́шим — ре́вность і бді́ніє о душа́х, градоправи́телем — му́дрость і си́лу, судія́м — пра́вду і нелицеприя́тіє, наста́вником — ра́зум і смиренному́дріє, супру́гом — любо́в і согла́сіє, ча́дом — послуша́ніє, оби́димим — терпі́ніє, оби́дящим — страх Бо́жий, скорб'я́щим — благоду́шіє, ра́дующимся — воздержа́ніє, всім же нам — дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пресвята́я, умилосе́рдися на немощни́я лю́ди Твоя́: разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й, і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ша к зрі́нію спасе́нія. Ми́лостива нам бу́ди зді і та́мо, в страні́ земна́го прише́льствія і на стра́шнім суді́ Си́на Твоєго́. Преста́вльшіяся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со а́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, сла́ва небе́сних і упова́ніє земни́х, Ти по Бо́зі на́ша Наде́жда і Засту́пниця всіх, притека́ющих к Тебі́ с ві́рою. К Тебі́ у́бо мо́лимся і Тебі́, я́ко всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш предає́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["Цари́це моя́ Преблага́я, Наде́ждо моя́ Пресвята́я, прия́телище си́рим і стра́нним Засту́пнице, бі́дствующих по́моще і озлобля́ємих покро́ве, зри́ши мою́ напа́сть, зри́ши мою́ скорб: отвсю́ду іскуше́нієм одержи́м єсьм, а заступа́ющаго ність. Ти у́бо сама́ помози́ мі я́ко не́мощну, окорми́ м'я я́ко стра́нна, наста́ви я́ко заблу́ждша, уврачу́й і спаси́ я́ко безнаде́жна. Не і́мам бо іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о Ма́ти всіх скорб'я́щих і обремене́нних! При́зри у́бо на м'я, грі́шнаго і во озлобле́нії су́щаго, і покри́й м'я пресвяти́м омофо́ром Твої́м, да ізба́влен бу́ду от зол, м'я обише́дших, і восхвалю́ ви́ну препі́тоє і́м'я Твоє́. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь благові́рнії лю́діє сві́тло пра́зднуєм / осіня́ємі Твої́м, Богома́ти, прише́ствієм, / і к Твоєму́ взира́юще Пречи́стому о́бразу, уми́льно глаго́лем: / покри́й нас честни́м Твої́м Покро́вом, / і ізба́ви нас от вся́каго зла, / моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь предстої́ть в це́ркві, / і с ли́ки святи́х неви́димо за ни мо́литься Бо́гу, / А́нгели со архієре́ї покланя́ються, / апо́столи же со проро́ки ликовству́ють: // нас бо ра́ди мо́лить Богоро́диця Преві́чнаго Бо́га."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим Покро́в Твой святи́й: / Тя бо ви́ді святи́й Андре́й на возду́сі, // за ни Христу́ моля́щуюся."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Ма́ти Христа́, Бо́га на́шего, // і всесла́вний сла́вим Покро́в Твой."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Ма́ти Христа́, Бо́га на́шего, / І́же к Си́ну Свої́ ру́ці простира́ющи, і о ми́рі моля́щися, / і честни́м Свої́м омофо́ром защища́ющи // град і лю́ди от враго́в на́ших."]}],"notes":[]}];
export default D;
